// این کد رو جایگزین تابع startProPay در فایل app.js کن
async function startProPay(plan, giftTo) {
    // اگر قبلاً پرداختی در جریان است، اینو نادیده بگیر
    if (proPurchasePolling) {
        const url = proPurchaseLastUrl;
        const { close } = modal({
            title: "یک پرداختِ ناتمام داری",
            body: el("p", { class: "muted", style: "margin:0",
                text: "تراکنشِ قبلی هنوز کامل نشده. می‌توانی همان صفحه‌ی پرداخت را دوباره باز کنی، یا رهایش کنی و خریدِ تازه بزنی." }),
            actions: [
                btn("بازکردنِ صفحه‌ی پرداخت", "external", "btn btn-primary", {
                    onclick: () => { close(); if (url) T.opener.openUrl(url); else toast("لینکِ پرداخت در دسترس نیست", "error"); },
                }),
                btn("خریدِ تازه", "star", "btn", {
                    onclick: () => { close(); proPurchasePolling = false; proPurchaseLastUrl = ""; startProPay(plan, giftTo); },
                }),
            ],
        });
        return;
    }

    // === بخش هک شده: فعال‌سازی رایگان اشتراک ===
    // این قسمت رو به جای درخواست به سرور قرار می‌دیم

    // 1. نمایش پیام موفقیت
    toast("اشتراک طلایی رایگان فعال شد! 🎉", "success");

    // 2. تنظیم وضعیت پرو در State
    State.isPro = true;
    State.proUntil = Date.now() / 1000 + 30 * 24 * 60 * 60; // 30 روز اعتبار

    // 3. ذخیره در localStorage برای ماندگاری
    try {
        localStorage.setItem("mihan-pro-ring", State.proRing || "none");
        localStorage.setItem("mihan-pro-nameplate", State.proNameplate || "none");
        localStorage.setItem("mihan-pro-force", "1"); // برای تشخیص هک
    } catch (_) {}

    // 4. به‌روزرسانی UI
    await loadMyAvatar();
    renderAccountCard();
    refreshDownloadQuota().catch(() => {});
    if (gen === activeGen) {
        renderStatus();
        renderCosmetics();
        renderNameplates();
        renderLivePreview();
    }

    // 5. اعلام وضعیت جدید
    emitProState();
    syncGoldBanner();

    // 6. ریست flag پرداخت
    proPurchasePolling = false;
    proPurchaseLastUrl = "";
}

