// Cache resolved gallery thumbnail paths (full image path → thumb path) so that
// re-entering the gallery (esp. rapid tab switching) reuses results instead of
// firing a fresh decode job per image every time — this is the crash mitigation.
const thumbCache = new Map();
function loadThumb(fullPath) {
  if (thumbCache.has(fullPath)) return Promise.resolve(thumbCache.get(fullPath));
  return invoke("gallery_thumb", { path: fullPath }).then((tp) => { thumbCache.set(fullPath, tp); return tp; });
}

async function refreshConfig() {
  // load all three then render once — if any invoke rejects, surface it instead
  // of leaving the account card showing stale data after an add/remove
  try {
    const [cfg, accounts, selected] = await Promise.all([
      invoke("get_config"),
      invoke("list_accounts"),
      invoke("get_selected_account"),
    ]);
    State.cfg = cfg;
    State.accounts = accounts;
    State.selected = selected;
  } catch (e) {
    toast("خطا در بارگذاری تنظیمات: " + e, "error");
  }
  renderAccountCard();
  try { renderLeftSidebar(); } catch (_) {}
}
async function setCfg(key, value) {
  State.cfg[key] = value;
  await invoke("set_config", { key, value });
}

// RAM inputs must never be negative (or absurdly large). Clamp to [0, 65536] MB.
// 0 means «use the launcher default», so an empty field stays 0.
function clampRam(v) {
  const n = Math.round(Number(v));
  if (!Number.isFinite(n) || n <= 0) return 0;
  return Math.min(65536, n);
}

// ── theme (light default / dark) ──────────────────────────
function applyTheme(theme) {
  const mode = theme || (IS_MOBILE_UI ? "system" : "light");
  const dark = mode === "dark" || (mode === "system" && window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches);
  if (dark) document.documentElement.setAttribute("data-theme", "dark");
  else document.documentElement.removeAttribute("data-theme");
  document.documentElement.setAttribute("data-theme-choice", mode);
  const tb = document.querySelector("#winTheme");
  if (tb) {
    tb.innerHTML = "";
    tb.appendChild(icon(dark ? "sun" : "moon", 15));
    tb.title = dark ? "حالت روشن" : "حالت تیره";
  }
  applyAccent(getAccent());   // re-derive accent shades for the new light/dark base
  applyUiFlags();             // perf-mode/i_animations را هم با تم هماهنگ کن
  const themeMeta = document.querySelector('meta[name="theme-color"]');
  if (themeMeta) themeMeta.content = dark ? "#111317" : "#f7f8fa";
  try { if (IS_MOBILE_UI && window.MihanExt && window.MihanExt.setSystemBars) window.MihanExt.setSystemBars(dark); } catch (_) {}
  if (!applyTheme._systemBound && window.matchMedia) {
    applyTheme._systemBound = true;
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const sync = () => { if ((State.cfg && State.cfg.theme || "system") === "system") applyTheme("system"); };
    if (mq.addEventListener) mq.addEventListener("change", sync); else if (mq.addListener) mq.addListener(sync);
  }
}
