    out[0] = 0x01; out[1] = (isKey ? 0x01 : 0x00) | (((codecId || 0) & 0x7) << 1);
    dv.setUint32(2, frameId, true); dv.setUint16(6, idx, true); dv.setUint16(8, total, true);
