// ⚠ ترتیب حیاتی است: اول دوربینِ فعلی بسته می‌شود، بعد دوربینِ تازه باز. اگر
// برعکس باشد (که طبیعی‌تر به نظر می‌رسد و اولین تلاشِ من هم همان بود) اندروید
// «NotReadableError: Could not start video source» می‌دهد — این گوشی‌ها اجازه‌ی
// بازبودنِ هم‌زمانِ دو دوربین را نمی‌دهند؛ در لاگِ سیستم دیده می‌شود که دوربینِ دوم
// وصل و بلافاصله قطع می‌شود.
//
// هزینه‌ی این ترتیب آن است که اگر بازکردنِ دوربینِ تازه شکست بخورد، دیگر استریمِ
// قبلی هم در دست نیست — پس همان جهتِ قبلی دوباره باز می‌شود و اگر آن هم نشد،
// ارسالِ تصویر تمیز بسته می‌شود (نه اینکه یک تماسِ نیمه‌خراب بماند).
async function switchVideoCamera() {
  const v = Voice.videoSending;
  if (!v || v.kind !== "camera") return toast("اول دوربین را روشن کن", "error");
  if (v.switching) return;
  v.switching = true;
  const prev = Voice.videoFacing || "user";
  const next = prev === "user" ? "environment" : "user";
  const grab = (facing) => navigator.mediaDevices.getUserMedia({
    // ideal نه exact: گوشی‌ای که آن دوربین را ندارد باید هرچه دارد بدهد، نه خطا.
    video: {
      facingMode: { ideal: facing },
      height: { ideal: VIDEO_MAX_H_CAMERA, max: VIDEO_MAX_H_CAMERA },
      frameRate: { ideal: VIDEO_FPS, max: VIDEO_FPS },
    },
    audio: false,
  });
  try { v.stream.getTracks().forEach((t) => t.stop()); } catch (_) {}
  let stream = null;
  try {
    stream = await grab(next);
  } catch (_) {
    try {
      const back = await grab(prev);                 // برگشت به همان دوربینِ قبلی
      v.stream = back;
      v.video.srcObject = back;
      try { await v.video.play(); } catch (_) {}
      Voice.videoForceKeyframe = true;
    } catch (_) {
      stopVideoShare();
    }
    v.switching = false;
    return toast("دوربینِ دیگری پیدا نشد.", "error");
  }
  const track = stream.getVideoTracks()[0];
  const st = (track && track.getSettings) ? track.getSettings() : {};
  const w = Math.max(2, (st.width || v.w) & ~1), h = Math.max(2, (st.height || v.h) & ~1);
  Voice.videoFacing = next;
  if (!track || w !== v.w || h !== v.h) {
    // ابعاد عوض شد → انکودر با ابعادِ قدیمی به‌درد نمی‌خورد. استریمِ تازه را هم
    // می‌بندیم تا startVideoShare دوباره با دوربینِ آزاد شروع کند (وگرنه همان
    // NotReadableError این بار سرِ راه‌اندازیِ دوباره می‌آید).
    try { stream.getTracks().forEach((t) => t.stop()); } catch (_) {}
    v.switching = false;
    stopVideoShare();
    await startVideoShare();
    return;
  }
  v.stream = stream;
  v.facing = next;
  v.video.srcObject = stream;
  try { await v.video.play(); } catch (_) {}
  // گیرنده‌ها وسطِ یک GOP هستند و تصویرِ تازه بدونِ keyframe آشغال می‌شود.
  Voice.videoForceKeyframe = true;
  v.switching = false;
  voiceRerender();
}

function stopVideoShare() {
  const v = Voice.videoSending;
  if (!v) return;
  // اشتراکِ صفحه استریمِ JS ندارد؛ ضبط سمتِ بومی است و باید همان‌جا بسته شود.
  if (v.kind === "screen") { stopScreenShare(); return; }
  Voice.videoSending = null;
  try { v.stop && v.stop(); } catch (_) {}
  try { v.enc && v.enc.enc && v.enc.enc.close(); } catch (_) {}
  try { v.stream && v.stream.getTracks().forEach((t) => t.stop()); } catch (_) {}
  try { if (v.video) { v.video.srcObject = null; v.video.remove(); } } catch (_) {}
  voiceSend({ t: "video_stop" });
  voiceRerender();
}

function handleAudioFrame(buf) {
  if (Voice.deaf || !Voice.audioCtx || buf.byteLength < 6) return;
  const dv = new DataView(buf);
  const mid = dv.getUint16(0, true);
  if (mid === Voice.meMid) return;
  if (Voice.stats) Voice.stats.recv++;
  const chByte = dv.getUint8(5);           // بایتِ ۵: بیتِ 0x80 = ساندبرد، ۷ بیتِ پایین = تعدادِ کانال
  const isSb = !!(chByte & 0x80);
  const ch = (chByte & 0x7f) || 1;
  const opus = new Uint8Array(buf, 6);
  const d = getDecoder(mid, ch, isSb); if (!d || !d.decoder) return;
  try {
    d.ts += 20000;
    d.decoder.decode(new EncodedAudioChunk({ type: "key", timestamp: d.ts, data: opus }));
    if (Voice.stats) Voice.stats.dec++;
  } catch (e) { if (Voice.stats) Voice.stats.err = "decErr:" + (e && e.message || e); }
}
function playDecoded(d, ad) {
  const ctx = Voice.audioCtx; if (!ctx) { try { ad.close(); } catch (_) {} return; }
  const frames = ad.numberOfFrames, rate = ad.sampleRate || 48000;
  let f32;
  try { f32 = new Float32Array(frames); ad.copyTo(f32, { planeIndex: 0, format: "f32-planar" }); }
  catch (_) { try { ad.close(); } catch (_) {} return; }
  try { ad.close(); } catch (_) {}
  const ab = ctx.createBuffer(1, frames, rate); ab.copyToChannel(f32, 0);
  const node = ctx.createBufferSource(); node.buffer = ab; node.connect(d.gain);
  const now = ctx.currentTime, LEAD = 0.09;
  let t = d.nextTime;
  if (t < now + 0.02) t = now + LEAD;   // underrun/شروع → با لیدِ jitter همگام کن
  node.start(t); d.nextTime = t + ab.duration;
  if (Voice.stats) Voice.stats.played++;
}

// ── چت روم ──
// دکمه‌ی کپیِ کوچک که با hover روی پیامِ چت ظاهر می‌شود.
function chatCopyBtn(text) {
  return btn(null, "copy", "chat-copy", {
    title: "کپی",
    onclick: async (e) => {
      e.stopPropagation();
      try { await navigator.clipboard.writeText(text || ""); toast("کپی شد", "success"); }
      catch (_) { try { const t = document.createElement("textarea"); t.value = text || ""; document.body.appendChild(t); t.select(); document.execCommand("copy"); t.remove(); toast("کپی شد", "success"); } catch (_) {} }
    },
  });
}
function renderChatMsg(m) {
  const row = el("div", { class: "vc-msg" + (m.self ? " mine" : "") });
  { const av = avatarEl(m.from, m.avatar || (m.self ? (Voice.avatar || State.myAvatar) : null), 28); if (!m.self && m.from) nameClick(m.from, av); row.appendChild(av); }
  const bub = el("div", { class: "vc-bubble" });
  if (!m.self) bub.appendChild(nameClick(m.from, el("div", { class: "vc-msg-from", text: m.from })));
  bub.appendChild(el("div", { class: "vc-msg-text", text: m.text }));
  row.appendChild(bub);
  row.appendChild(chatCopyBtn(m.text));
  return row;
}
function pushChat(m) {
  Voice.chat.push(m);
  if (Voice.chat.length > 200) Voice.chat.shift();
  if (Voice.chatListEl) { Voice.chatListEl.appendChild(renderChatMsg(m)); Voice.chatListEl.scrollTop = Voice.chatListEl.scrollHeight; }
}
function onChat(m) { pushChat({ self: false, from: m.from, avatar: m.avatar, text: m.text, ts: m.ts }); }

// ── ساندبرد (پدهای صوتیِ کاستوم — محلی، در مسیرِ صدا میکس می‌شوند) ──
function b64ToBytes(b64) {
  const bin = atob(b64); const n = bin.length; const a = new Uint8Array(n);
  for (let i = 0; i < n; i++) a[i] = bin.charCodeAt(i);
  return a;
}
async function loadPads() {
  try { Voice.pads = await invoke("voice_pad_list"); } catch (_) { Voice.pads = []; }
  voiceRerender();
}
// ── صدای ساندبرد (سمتِ شنونده) ──
// ساندبرد روی یک «کانالِ جدا» فرستاده می‌شود (انکودرِ مجزا)، پس هر شنونده می‌تواند بلندیِ صدای
// ساندبردِ همه (هم خودش هم بقیه) را مستقل از صدای حرف‌زدن کم/قطع کند. این مقدار روی sbOutGain
// اعمال می‌شود که خروجیِ همه‌ی صداهای ساندبردی است که می‌شنوی. ۰ = کاملاً بی‌صدا. در localStorage می‌ماند.
function sbVolGet() {
  const v = parseFloat(localStorage.getItem("sb_volume"));
  return isNaN(v) ? 1 : Math.max(0, Math.min(1, v));
}
function sbVolSet(v) {
  v = Math.max(0, Math.min(1, v));
  localStorage.setItem("sb_volume", String(v));
  if (Voice.sbOutGain) { try { Voice.sbOutGain.gain.value = v; } catch (_) {} }
}
// کنترلِ اسلایدر + بی‌صدا — هم در پنلِ ویس و هم در صفحهٔ تنظیمات استفاده می‌شود.
function soundboardVolControl() {
  const wrap = el("div", { class: "sb-vol", style: "margin-top:6px" });
  const cur = Math.round(sbVolGet() * 100);
  const slider = el("input", { type: "range", min: "0", max: "100", step: "5", value: String(cur), style: "flex:1" });
  const pct = el("span", { class: "dim", style: "min-width:42px;text-align:left", text: cur + "٪" });
  const chk = el("input", { type: "checkbox" }); chk.checked = (cur === 0);
  let lastNonZero = cur > 0 ? cur : 100;
  const apply = (p) => { sbVolSet(p / 100); pct.textContent = p + "٪"; };
  slider.addEventListener("input", () => { const p = +slider.value; if (p > 0) lastNonZero = p; chk.checked = (p === 0); apply(p); });
  chk.addEventListener("change", () => { const p = chk.checked ? 0 : (lastNonZero || 100); slider.value = String(p); apply(p); });
  wrap.append(
    el("label", { class: "vc-check", style: "gap:6px;margin-bottom:6px" }, chk, el("span", { text: "بی‌صدا کردنِ ساندبرد" })),
    el("div", { class: "row", style: "align-items:center;gap:8px" }, el("span", { class: "dim", style: "font-size:12px;min-width:32px", text: "صدا" }), slider, pct)
  );
  return wrap;
}
const SB_COOLDOWN_MS = 2000;   // بینِ هر پخشِ ساندبرد حداقل ۲ ثانیه فاصله (ضدِ اسپم)
async function playPad(file) {
  if (!Voice.audioCtx || !Voice.sbDest) return toast("اول وارد یک روم شو", "error");
  if (Voice.sbDisabled && !isOwner()) return toast("ساندبرد توسطِ مدیرِ روم خاموش است", "error");
  const nowMs = performance.now();
  if (nowMs - (Voice.lastPadAt || 0) < SB_COOLDOWN_MS) {
    const rem = Math.ceil((SB_COOLDOWN_MS - (nowMs - (Voice.lastPadAt || 0))) / 1000);
    return toast(`بینِ پخش‌ها ۲ ثانیه صبر کن (${rem})`, "error");
  }
  Voice.lastPadAt = nowMs;
  try { await Voice.audioCtx.resume(); } catch (_) {}
  let buf = Voice.padBuffers.get(file);
  if (!buf) {
    try {
      const b64 = await invoke("voice_pad_read", { file });
      buf = await Voice.audioCtx.decodeAudioData(b64ToBytes(b64).buffer);
      Voice.padBuffers.set(file, buf);
    } catch (_) { return toast("پخش صدا ناموفق بود", "error"); }
  }
  const node = Voice.audioCtx.createBufferSource();
  node.buffer = buf;
  if (Voice.sbDest) node.connect(Voice.sbDest);        // کانالِ جدای ساندبرد → انکودرِ مجزا → بقیه
  if (Voice.sbOutGain) node.connect(Voice.sbOutGain);  // شنیدنِ خودت (با ولومِ شنونده‌ی خودت)
  node.start();
  Voice.padPlayingUntil = performance.now() + buf.duration * 1000 + 150;  // تا آخرش روی کانالِ ساندبرد فرستاده شود
}
const PAD_MAX_SEC = 10;   // ساندبرد حداکثر ۱۰ ثانیه
async function addPad() {
  const f = await pickFile("audio/*");
  if (!f) return;
  try {
    const ctx = Voice.audioCtx || newAudioCtx();
    const decoded = await ctx.decodeAudioData(await f.arrayBuffer());
    const defName = (f.name || "sound").replace(/\.[^.]+$/, "").replace(/[^A-Za-z0-9_\- ]/g, "_").slice(0, 24) || "sound";
    openPadCropEditor(ctx, decoded, defName);   // ادیتورِ کراپ: کاربر بازه‌ی دلخواه (≤۱۰ث) را انتخاب می‌کند
  } catch (e) { toast("خطا در باز کردنِ صدا: " + e, "error"); }
}

// ادیتورِ صدا: موجِ صدا را می‌کشد و کاربر با دو دستگیره بازه‌ای (حداکثر ۱۰ ثانیه) انتخاب می‌کند
// که نگه داشته شود؛ بقیه حذف می‌شود. دکمه‌ی پیش‌نمایش هم دارد.
function openPadCropEditor(ctx, decoded, defName) {
  const dur = decoded.duration;
  const W = 560, H = 130;
  const css = getComputedStyle(document.documentElement);
  const ACC = (css.getPropertyValue("--accent") || "#3b82f6").trim();
  const cv = el("canvas", { width: String(W), height: String(H), style: "width:100%;max-width:560px;border-radius:10px;background:var(--panel-2);cursor:ew-resize;touch-action:none" });
  const g = cv.getContext("2d");
  const ch0 = decoded.getChannelData(0);
  let selA = 0, selB = Math.min(dur, PAD_MAX_SEC);
  const durLabel = el("div", { class: "dim", style: "margin-top:8px" });
  const nameIn = el("input", { class: "input", value: defName, placeholder: "نام صدا", maxlength: "24", style: "margin-top:10px" });

  const xOf = (t) => (t / dur) * W, tOf = (x) => Math.max(0, Math.min(dur, (x / W) * dur));
  function draw() {
    g.clearRect(0, 0, W, H);
    // موج
    const step = Math.max(1, Math.floor(ch0.length / W));
    g.strokeStyle = "rgba(140,150,170,.55)"; g.lineWidth = 1;
    for (let x = 0; x < W; x++) {
      let mn = 1, mx = -1;
      for (let j = 0; j < step; j++) { const v = ch0[x * step + j] || 0; if (v < mn) mn = v; if (v > mx) mx = v; }
      const y1 = (1 - (mx + 1) / 2) * H, y2 = (1 - (mn + 1) / 2) * H;
      g.beginPath(); g.moveTo(x + 0.5, y1); g.lineTo(x + 0.5, y2); g.stroke();
    }
    // بازه‌ی انتخابی
    const xa = xOf(selA), xb = xOf(selB);
    g.fillStyle = "rgba(59,130,246,.20)"; g.fillRect(xa, 0, xb - xa, H);
    g.fillStyle = ACC; g.fillRect(xa - 2, 0, 4, H); g.fillRect(xb - 2, 0, 4, H);
    durLabel.textContent = `بازه‌ی انتخابی: ${(selB - selA).toFixed(1)} ثانیه (حداکثر ${PAD_MAX_SEC}) — از کلِ ${dur.toFixed(1)} ثانیه`;
  }
  draw();

  // درگ: نزدیک‌ترین دستگیره را جابه‌جا کن (با محدودیتِ ۱۰ ثانیه)
  let drag = null;
  const localX = (e) => { const r = cv.getBoundingClientRect(); const cx = (e.touches ? e.touches[0].clientX : e.clientX) - r.left; return cx / r.width * W; };
  const onMove = (e) => {
    if (!drag) return; e.preventDefault();
    const t = tOf(localX(e));
    if (drag === "a") { selA = Math.min(t, selB - 0.2); if (selB - selA > PAD_MAX_SEC) selB = Math.min(dur, selA + PAD_MAX_SEC); }
    else { selB = Math.max(t, selA + 0.2); if (selB - selA > PAD_MAX_SEC) selA = Math.max(0, selB - PAD_MAX_SEC); }
    selA = Math.max(0, selA); selB = Math.min(dur, selB); draw();
  };
  const onUp = () => { drag = null; window.removeEventListener("mousemove", onMove); window.removeEventListener("mouseup", onUp); };
  const onDown = (e) => {
    const x = localX(e); drag = Math.abs(x - xOf(selA)) <= Math.abs(x - xOf(selB)) ? "a" : "b";
    window.addEventListener("mousemove", onMove); window.addEventListener("mouseup", onUp); onMove(e);
  };
  cv.addEventListener("mousedown", onDown);
  cv.addEventListener("touchstart", onDown, { passive: false }); cv.addEventListener("touchmove", onMove, { passive: false }); cv.addEventListener("touchend", onUp);

  let previewSrc = null;
  const stopPreview = () => { try { previewSrc && previewSrc.stop(); } catch (_) {} previewSrc = null; };
  const playBtn = btn("پیش‌نمایش بازه", "play", "btn btn-sm", { onclick: () => {
    stopPreview();
    previewSrc = ctx.createBufferSource(); previewSrc.buffer = decoded; previewSrc.connect(ctx.destination);
    try { ctx.resume(); } catch (_) {}
    previewSrc.start(0, selA, Math.max(0.05, selB - selA));
  } });

  const body = el("div", {},
    el("p", { class: "muted", style: "margin:0 0 10px", text: "دو طرفِ بازه‌ی آبی را بکش تا فقط همان قسمت از صدا بماند (حداکثر ۱۰ ثانیه)." }),
    cv, durLabel,
    el("label", { class: "field" }, el("span", { text: "نام صدا" }), nameIn),
    el("div", { class: "row", style: "gap:8px;margin-top:10px" }, playBtn));

  const dlg = modal({
    title: "برشِ صدا برای ساندبرد", body,
    actions: [
      btn("افزودن به ساندبرد", "check", "btn btn-primary", { onclick: async (e) => {
        stopPreview();
        const sr = decoded.sampleRate;
        const a = Math.floor(selA * sr), b = Math.floor(selB * sr);
        if (b - a < sr * 0.1) { toast("بازه خیلی کوتاه است", "error"); return; }
        const eb = e.currentTarget; eb.disabled = true; eb.innerHTML = '<span class="spinner"></span>';
        try {
          const frames = b - a;
          const trimmed = ctx.createBuffer(decoded.numberOfChannels, frames, sr);
          for (let c = 0; c < decoded.numberOfChannels; c++) trimmed.copyToChannel(decoded.getChannelData(c).subarray(a, b), c);
          const wav = audioBufferToWav(trimmed);
          const name = (nameIn.value.trim().replace(/[^A-Za-z0-9_\- ]/g, "_") || "sound") + ".wav";
          Voice.pads = await invoke("voice_pad_add_data", { name, data: bytesToB64(wav) });
          dlg.close(); toast("صدا اضافه شد ✓", "success"); voiceRerender();
        } catch (err) { toast("خطا: " + err, "error"); eb.disabled = false; eb.innerHTML = ""; eb.appendChild(icon("check", 16)); eb.appendChild(el("span", { text: "افزودن به ساندبرد" })); }
      } }),
      btn("انصراف", null, "btn btn-ghost", { onclick: () => { stopPreview(); onUp(); dlg.close(); } }),
    ],
  });
}
function bytesToB64(bytes) {
  let bin = ""; const ch = 0x8000;
  for (let i = 0; i < bytes.length; i += ch) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + ch));
  return btoa(bin);
}
// AudioBuffer → WAV (PCM 16-bit) برای ذخیره‌ی پدِ کات‌شده
function audioBufferToWav(buf) {
  const numCh = buf.numberOfChannels, sr = buf.sampleRate, n = buf.length;
  const blockAlign = numCh * 2, dataLen = n * blockAlign;
  const ab = new ArrayBuffer(44 + dataLen), dv = new DataView(ab);
  const ws = (o, s) => { for (let i = 0; i < s.length; i++) dv.setUint8(o + i, s.charCodeAt(i)); };
  ws(0, "RIFF"); dv.setUint32(4, 36 + dataLen, true); ws(8, "WAVE");
  ws(12, "fmt "); dv.setUint32(16, 16, true); dv.setUint16(20, 1, true);
  dv.setUint16(22, numCh, true); dv.setUint32(24, sr, true);
  dv.setUint32(28, sr * blockAlign, true); dv.setUint16(32, blockAlign, true); dv.setUint16(34, 16, true);
  ws(36, "data"); dv.setUint32(40, dataLen, true);
  const chans = [];
  for (let c = 0; c < numCh; c++) chans.push(buf.getChannelData(c));
  let off = 44;
  for (let i = 0; i < n; i++) for (let c = 0; c < numCh; c++) {
    let s = Math.max(-1, Math.min(1, chans[c][i]));
    dv.setInt16(off, s < 0 ? s * 0x8000 : s * 0x7FFF, true); off += 2;
  }
  return new Uint8Array(ab);
}
async function deletePad(file) {
  try { Voice.pads = await invoke("voice_pad_delete", { file }); Voice.padBuffers.delete(file); voiceRerender(); } catch (_) {}
}

// ── مدیریتِ روم (اکشن‌های مالک) ──
function modAction(action, mid) { voiceSend({ t: "mod", action, mid }); }

// ── کنترل‌ها ──
function setMute(b) {
  Voice.mute = b; if (!b && Voice.deaf) Voice.deaf = false;
  const me = Voice.members.get(Voice.meMid); if (me) { me.mute = Voice.mute; me.deaf = Voice.deaf; }
  sendState({ mute: Voice.mute, deaf: Voice.deaf });
  voiceRerender();
}
function setDeaf(b) {
  Voice.deaf = b; Voice.mute = b ? true : false;
  const me = Voice.members.get(Voice.meMid); if (me) { me.mute = Voice.mute; me.deaf = Voice.deaf; }
  sendState({ mute: Voice.mute, deaf: Voice.deaf });
  voiceRerender();
}

// ── پلِ ویسِ درون‌بازی (Android) ──────────────────────────────────────────
// وقتی بازی لانچ می‌شود، Activityِ خودِ Pojav (نه WebViewِ لانچر) روی صفحه است. صدا/میکروفون
// همچنان در همین WebView زنده می‌مانند (تست شد: AudioContext/mic track در تمامِ طولِ لانچ
// «running»/«live» می‌مانند)، ولی هیچ رابطِ کاربری‌ای برای دیدن/کنترلِ تماس در آن لحظه نیست.
// MihanInjector (سمتِ جاوا) یک پنلِ شناورِ کوچک داخلِ اکتیویتیِ بازی تزریق می‌کند و هر ~۱ ثانیه
// اینجا evaluateJavascript می‌زند تا وضعیت را بخواند و دکمه‌های میوت/خروج را صدا بزند — بدونِ
// نیاز به هیچ WebViewِ دومی یا تغییرِ smaliِ Pojav.
window.__mihanVoiceState = function () {
  try {
    if (typeof Voice === "undefined" || !Voice || !Voice.room) return null;
    return {
      inRoom: true, name: (Voice.room && Voice.room.name) || "",
      muted: !!Voice.mute, deaf: !!Voice.deaf, speaking: !!Voice._speakShown,
      // so the floating panel can warn about a dead mic too — in-game is exactly where the user
      // has no other way to notice, the launcher UI being completely off screen behind the game
      micError: !!Voice.micError,
    };
  } catch (_) { return null; }
};
window.__mihanVoiceMuteToggle = function () { try { setMute(!Voice.mute); } catch (_) {} };
// Defined here, next to its siblings, rather than in mihan-polyfill.js where it started out:
// app.js is loaded as <script type="module">, so setDeaf/Voice are module-scoped and simply do
// not exist in the polyfill's scope — the panel's deafen button was silently doing nothing.
window.__mihanVoiceDeafToggle = function () { try { setDeaf(!Voice.deaf); } catch (_) {} };
window.__mihanVoiceLeave = function () { try { voiceLeaveRoom(); } catch (_) {} };
// وضعیتِ نگه‌داشتنِ کلید/اسکرول جدا از هم نگه‌داری می‌شود تا تایم‌اوتِ اسکرول هیچ‌وقت
// وضعیتِ نگه‌داشتنِ کلیدِ صفحه‌کلید را پاک نکند (و برعکس) — قبلاً هر دو یک فلگِ مشترک
// (Voice.pttActive) را می‌نوشتند و اسکرولِ هم‌زمان با نگه‌داشتنِ کلید باعثِ قطعِ زودرسِ صدا می‌شد.
let _pttKeyHeld = false, _pttWheelHeld = false;
function _recomputePttActive() { Voice.pttActive = _pttKeyHeld || _pttWheelHeld; }
function bindPttKeys() {
  if (Voice._keysBound) return; Voice._keysBound = true;
  // کلیدهای صفحه‌کلید (شامل اسکرول موس هم کار کند)
  document.addEventListener("keydown", (e) => {
    if (!Voice.ptt || !Voice.room || e.repeat) return;
    // اگر کلید PTT با کلید فشرده‌شده مطابقت داشت
    if (Voice.pttKey && Voice.pttKey === e.code) {
      const a = document.activeElement;
      if (a && (a.tagName === "INPUT" || a.tagName === "TEXTAREA" || a.isContentEditable)) return;
      e.preventDefault(); _pttKeyHeld = true; _recomputePttActive();
      return;
    }
    // Space به‌عنوان fallback
    if (e.code !== "Space") return;
    const a = document.activeElement;
    if (a && (a.tagName === "INPUT" || a.tagName === "TEXTAREA" || a.isContentEditable)) return;
    e.preventDefault(); _pttKeyHeld = true; _recomputePttActive();
  });
  document.addEventListener("keyup", (e) => {
    if (!Voice.ptt) return;
    if (e.code === "Space" || (Voice.pttKey && Voice.pttKey === e.code)) { _pttKeyHeld = false; _recomputePttActive(); }
  });
  // پشتیبانی از دکمه‌های موس (چپ/راست/وسط/عقب/جلو)
  document.addEventListener("mousedown", (e) => {
    if (!Voice.ptt || !Voice.room) return;
    const MOUSE_MAP = { 3: "Mouse4", 4: "Mouse5" };
    const mapped = MOUSE_MAP[e.button] || ("Mouse" + e.button);
    if (Voice.pttKey && Voice.pttKey === mapped) {
      e.preventDefault(); _pttKeyHeld = true; _recomputePttActive();
    }
  });
  document.addEventListener("mouseup", (e) => {
    if (!Voice.ptt) return;
    const MOUSE_MAP = { 3: "Mouse4", 4: "Mouse5" };
    const mapped = MOUSE_MAP[e.button] || ("Mouse" + e.button);
    if (Voice.pttKey && Voice.pttKey === mapped) { _pttKeyHeld = false; _recomputePttActive(); }
  });
  // پشتیبانی از اسکرول موس (بالا/پایین) — فلگِ مستقلِ خودش را دارد، با کلیدِ صفحه‌کلید تداخل نمی‌کند
  let _wheelClearTimer = null;
  document.addEventListener("wheel", (e) => {
    if (!Voice.ptt || !Voice.room) return;
    if (Voice.pttKey === "WheelUp" || Voice.pttKey === "WheelDown") {
      e.preventDefault(); _pttWheelHeld = true; _recomputePttActive();
      // اسکرول PTT را بعد از کوتاهی غیرفعال کن (momentary) — فقط فلگِ اسکرول، نه فلگِ کلید
      clearTimeout(_wheelClearTimer);
      _wheelClearTimer = setTimeout(() => { _pttWheelHeld = false; _recomputePttActive(); }, 200);
    }
  }, { passive: false });
}

// ── دیالوگ‌های ساخت/ورود ──
function openCreateRoom() {
  const name = el("input", { class: "input", placeholder: "نام روم", maxlength: "40" });
  const privChk = el("input", { type: "checkbox" });
  const body = el("div", {},
    el("label", { class: "field" }, el("span", { text: "نام روم" }), name),
    el("label", { class: "vc-check" }, privChk, el("span", { text: "روم خصوصی (فقط با کد قابل ورود)" })));
  const dlg = modal({
    title: "ساخت روم صوتی", body, actions: [
      btn("بساز", "check", "btn btn-primary", { onclick: async () => {
        try { await voiceEnsureConnected(); } catch (_) { return toast("اتصال به سرور صدا ناموفق بود", "error"); }
        voiceSend({ t: "create", name: name.value.trim(), private: privChk.checked });
        dlg.close();
      } }),
      btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
    ],
  });
  setTimeout(() => name.focus(), 50);
}
function openJoinByCode() {
  const code = el("input", { class: "input", placeholder: "مثلاً ABC234", maxlength: "12", style: "text-transform:uppercase;direction:ltr;text-align:center;letter-spacing:2px" });
  const dlg = modal({
    title: "ورود با کد", body: el("label", { class: "field" }, el("span", { text: "کد دعوتِ روم را وارد کن" }), code),
    actions: [
      btn("ورود", "logIn", "btn btn-primary", { onclick: async () => {
        const v = code.value.trim().toUpperCase(); if (!v) return toast("کد را وارد کن", "error");
        try { await voiceEnsureConnected(); } catch (_) { return toast("اتصال به سرور صدا ناموفق بود", "error"); }
        voiceSend({ t: "join", code: v }); dlg.close();
      } }),
      btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
    ],
  });
  setTimeout(() => code.focus(), 50);
}

// ── ساختِ UI ──
function memberStatusText(m) {
  if (m.speaking && !m.srv_mute) return "در حال صحبت";
  if (m.hand_up) return "درخواست صحبت";
  if (m.srv_mute) return "بی‌صدا توسط مدیر";
  if (m.deaf) return "صدای تماس بسته";
  if (m.mute) return "میکروفون بسته";
  return "آماده‌ی صحبت";
}
function renderMember(m) {
  const amOwner = isOwner();
  const thisIsOwner = !!(Voice.room && m.username === Voice.room.owner);
  const root = el("div", { class: "vc-member" + (m.speaking && !m.srv_mute ? " speaking" : "") });
  const ring = el("div", { class: "vc-ring" }, avatarEl(m.username, m.avatar, 56));
  if (!m.self && m.username) nameClick(m.username, ring);
  const badges = el("div", { class: "vc-badges" });
  memberBadges(badges, m);
  root.appendChild(ring); root.appendChild(badges);
  root.appendChild(el("div", { class: "vc-mname" },
    thisIsOwner ? el("span", { class: "vc-crown", title: "مدیرِ روم" }, icon("crown", 12)) : null,
    el("span", { text: (m.username || "?") + (m.self ? " (تو)" : "") })));
  const status = el("div", { class: "vc-member-status", text: memberStatusText(m) });
  root.appendChild(status);
  if (amOwner && !m.self && !thisIsOwner) {   // کنترل‌های مدیر برای این عضو
    const menu = el("details", { class: "vc-member-menu" });
    menu.appendChild(el("summary", { class: "btn btn-sm" }, icon("settings", 14), el("span", { text: "مدیریت" })));
    const closeMenu = (fn) => () => { menu.open = false; fn(); };
    menu.appendChild(el("div", { class: "vc-member-actions" },
      btn(m.srv_mute ? "اجازه‌ی صحبت" : "بی‌صدا کردن", m.srv_mute ? "mic" : "micOff", "btn btn-sm", {
        onclick: closeMenu(() => modAction(m.srv_mute ? "unmute" : "mute", m.mid)),
      }),
      btn("اخراج از تماس", "phoneOff", "btn btn-sm btn-danger", {
        onclick: closeMenu(() => {
          if (confirm(`«${m.username}» از تماس خارج شود؟`)) modAction("kick", m.mid);
        }),
      }),
      btn("بن از این روم", "ban", "btn btn-sm btn-danger", {
        onclick: closeMenu(() => {
          if (confirm(`«${m.username}» را بن می‌کنی؟ دیگر نمی‌تواند وارد این روم شود.`)) modAction("ban", m.mid);
        }),
      })));
    root.appendChild(menu);
  }
  // ── تصویرِ زنده‌ی همین عضو ──
  // مثلِ نسخه‌ی دسکتاپ، تصویر داخلِ کارتِ خودِ عضو می‌نشیند (نه در یک گریدِ جدا)، با
  // همان برچسب و همان دکمه‌ی بزرگ‌نمایی.
  const vs = Voice.videoStreams && Voice.videoStreams.get(m.mid);
  // ── پیش‌نمایشِ تصویرِ خودت ──
  // المانِ <video> که startVideoShare می‌سازد فقط منبعِ canvasِ انکودر بود و هرگز
  // به صفحه نمی‌رفت: دوربین روشن می‌شد، فریم برای بقیه می‌رفت، ولی خودت هیچ
  // نمی‌دیدی — «پیش‌نمایش دوربین را نشان نمی‌دهد». همان المان را در همان جایگاهی
  // می‌گذاریم که تصویرِ بقیه می‌نشیند، پس چیزی دوباره دیکود/کپی نمی‌شود.
  const selfVideo = m.mid === Voice.meMid && Voice.videoSending && Voice.videoSending.video;
  if (selfVideo) {
    root.classList.add("is-streaming");
    const plate = root.querySelector(":scope > .nx-row-plate");
    if (plate) plate.remove();
    root.classList.remove("nx-plate-row");
    selfVideo.classList.add("vc-video-tile", "vc-self-video");
    // آینه فقط برای دوربینِ جلو: چیزی که برای بقیه می‌رود آینه نیست، ولی آدم
    // انتظار دارد پیش‌نمایشِ خودش مثلِ آینه باشد (رفتارِ هر اپِ تماسِ تصویری).
    selfVideo.classList.toggle("is-mirrored",
      Voice.videoSending.kind === "camera" && (Voice.videoFacing || "user") !== "environment");
    root.appendChild(el("div", { class: "vc-member-video" },
      selfVideo,
      el("span", { class: "vc-member-video-tag", text: "تصویرِ تو" })));
  } else if (vs && vs.canvas && m.mid !== Voice.meMid) {
    root.classList.add("is-streaming");
    // وقتی تصویر داریم پس‌زمینه‌ی نیم‌پلیت برداشته می‌شود: دو لایه‌ی تصویری روی هم
    // کارت را شلوغ و متن را ناخوانا می‌کند.
    const plate = root.querySelector(":scope > .nx-row-plate");
    if (plate) plate.remove();
    root.classList.remove("nx-plate-row");
    root.appendChild(el("div", { class: "vc-member-video" },
      vs.canvas,
      el("span", { class: "vc-member-video-tag", text: "تصویرِ زنده" }),
      btn(null, "maximize", "btn vc-video-expand", {
        title: "بزرگ کردن تصویر", "aria-label": "بزرگ کردن تصویر",
        onclick: (e) => { e.stopPropagation(); openVideoViewer(m.mid); },
      })));
  }
  Voice.memberEls.set(m.mid, { root, badges, status });
  return root;
}
function buildVoiceLobby(c) {
  const actions = el("div", { class: "row", style: "gap:8px;flex-wrap:wrap;margin-top:4px" },
    btn("ساخت روم", "plus", "btn btn-primary", { onclick: openCreateRoom }),
    btn("ورود با کد", "hash", "btn", { onclick: openJoinByCode }),
    btn(null, "refreshCw", "btn btn-icon", { title: "تازه‌سازی", onclick: async () => {
      try { await voiceEnsureConnected(); voiceSend({ t: "list" }); } catch (_) { toast("اتصال به سرور صدا ناموفق بود", "error"); }
    } }));
  // «میکروفون نداری؟ از موبایلت استفاده کن» (mic.mihancraft.com) روی نسخه‌ی موبایل حذف شد —
  // خودِ گوشی میکروفون دارد؛ startMic() همیشه میکروفونِ فعالِ فعلیِ سیستم را می‌گیرد
  // (به‌طورِ خودکار با میکِ گوشی/هندزفری/بلوتوث هماهنگ می‌شود).
  const card = el("div", { class: "card" }, secTitle("روم‌های صوتی", "mic"),
    el("p", { class: "muted", style: "margin:-4px 0 4px", text: "یک روم بساز یا به یکی بپیوند تا با بقیه صحبت کنی." }), actions);
  const list = el("div", { class: "vc-rooms" });
  const rooms = Voice.rooms || [];
  if (!rooms.length) {
    list.appendChild(el("div", { class: "empty" }, el("div", { class: "big" }, icon("mic", 42)), el("div", { text: "هنوز رومی ساخته نشده — اولین نفر باش!" })));
  } else {
    rooms.forEach((r) => {
      const mem = Array.isArray(r.members) ? r.members : [];
      const cnt = (typeof r.count === "number") ? r.count : mem.length;
      // ردیفِ آواتارهای کنارِ‌هم (تا ۵ تا) + شمارشِ نفرات به‌جای نوشتنِ نام‌ها
      const stack = el("div", { class: "vc-room-stack" });
      mem.slice(0, 5).forEach((u) => stack.appendChild(avatarEl(u.username, u.avatar, 26)));
      if (cnt > 5) stack.appendChild(el("div", { class: "vc-room-more", text: "+" + (cnt - 5).toLocaleString("fa-IR") }));
      list.appendChild(el("div", { class: "vc-room-card" },
        el("div", { class: "vc-room-ico" }, icon("volume2", 20)),
        el("div", { style: "flex:1;min-width:0" },
          el("div", { class: "vc-room-name", text: r.name }),
          el("div", { class: "row", style: "gap:8px;align-items:center;margin-top:4px" },
            el("span", { class: "dim", text: `${cnt.toLocaleString("fa-IR")} نفر` }),
            stack)),
        btn("ورود", "logIn", "btn btn-sm btn-primary", { onclick: () => voiceSend({ t: "join", room_id: r.id }) })));
    });
  }
  card.appendChild(list);
  c.appendChild(card);
}
// گریدِ اعضا را (از روی Voice.members) می‌سازد. هم در ساختِ اولیه و هم در آپدیتِ
// زنده‌ی join/leave استفاده می‌شود — تا چتِ روم بازساخته نشود.
function fillMembersGrid() {
  const grid = Voice.membersGridEl; if (!grid) return;
  Voice.memberEls = new Map();
  grid.innerHTML = "";
  const ordered = [...Voice.members.values()].sort((a, b) => (a.mid === Voice.meMid ? -1 : b.mid === Voice.meMid ? 1 : a.mid - b.mid));
  ordered.forEach((m) => grid.appendChild(renderMember(m)));
}
// وقتی کسی وارد/خارج می‌شود فقط لیستِ اعضا را به‌روز کن (نه کلِ صفحه)؛ اگر گرید موجود
// نیست (مثلاً در لابی هستیم) به بازساخت کامل برمی‌گردد.
function voiceUpdateMembers() {
  if (Voice.room && Voice.membersGridEl && document.body.contains(Voice.membersGridEl)) {
    fillMembersGrid();
    const count = Voice.members.size.toLocaleString("fa-IR");
    const badge = Voice.container && Voice.container.querySelector(".vc-count-badge");
    const meta = Voice.container && Voice.container.querySelector(".vc-room-count");
    if (badge) badge.textContent = count;
    if (meta) meta.textContent = `${count} نفر حاضر`;
  } else voiceRerender();
}
