// روی موبایل، کارت‌های سنگینِ صفحه‌ی تماس داخلِ یک بخشِ جمع‌شدنی می‌روند.
// چیدمانِ این صفحه برای دسکتاپِ دوستونه نوشته شده؛ روی موبایل هر دو ستون پشتِ سرِ هم می‌افتند و
// ارتفاع به ~۲۰۷۰px می‌رسد (اندازه‌گیری‌شده روی گوشی: پنلِ مدیریت ۸۲۵، چت ۳۳۰، اعضا ۳۲۰،
// ساندبرد ۲۸۶) در حالی که نمایشگر ۶۳۹px است — یعنی چهار صفحه اسکرول تا رسیدن به هر چیزی.
// «همه‌چی خارج از دسترسه» دقیقاً همین است.
function vcCollapsible(card, title, ic, openByDefault) {
  if (!IS_MOBILE_UI) return card;
  const d = el("details", { class: "card vc-collapse" });
  if (openByDefault) d.setAttribute("open", "");
  const sum = el("summary", { class: "vc-collapse-head" },
    el("span", { class: "vc-collapse-title" }, icon(ic, 16), el("span", { text: title })),
    el("span", { class: "vc-collapse-chev" }, icon("chevronDown", 16)));
  d.appendChild(sum);
  // کارت داخلی دیگر خودش قاب نمی‌خواهد — قابِ بیرونی همان details است.
  card.classList.remove("card");
  card.classList.add("vc-collapse-body");
  d.appendChild(card);
  return d;
}

function buildVoiceRoom(c) {
  const r = Voice.room;
  const head = el("div", { class: "card vc-room-header" });
  const tw = el("div", { style: "flex:1;min-width:0" });
  tw.appendChild(el("div", { class: "vc-room-title" }, icon(r.private ? "lock" : "volume2", 18), el("span", { text: r.name })));
  tw.appendChild(el("div", { class: "vc-room-meta" },
    el("span", { class: "vc-live-dot" }),
    el("span", { text: "تماس فعال" }),
    el("span", { text: "•" }),
    el("span", { class: "vc-room-count", text: `${Voice.members.size.toLocaleString("fa-IR")} نفر حاضر` }),
    el("span", { text: "•" }),
    el("span", { text: r.private ? "روم خصوصی" : "روم عمومی" })));
  if (r.private && r.code) {
    tw.appendChild(el("div", { class: "vc-code-row" },
      el("span", { class: "dim", text: "کد دعوت:" }),
      el("code", { class: "vc-code", text: r.code }),
      btn("کپی دعوت", "copy", "btn btn-sm", { title: "کپی کد دعوت", onclick: () => {
        try { navigator.clipboard.writeText(r.code); toast("کد کپی شد", "success"); } catch (_) {}
      } })));
  }
  head.appendChild(tw);
  head.appendChild(btn("پایان تماس", "phoneOff", "btn btn-danger vc-leave-call", { onclick: () => {
    if (confirm("از این تماس خارج می‌شوی؟")) voiceLeaveRoom();
  } }));
  c.appendChild(head);

  // Ordered by how badly each one breaks the call: a mic that never opened means nothing you say
  // leaves this device at all, which outranks being muted by the room owner.
  if (Voice.micError) {
    c.appendChild(el("div", { class: "vc-banner" }, icon("micOff", 16),
      el("span", { text: "میکروفونت باز نشد، پس هیچ‌کس صدایت را نمی‌شنود. " + Voice.micError }),
      btn("تلاش دوباره", "refresh", "btn btn-sm", { onclick: () => {
        startMic().then(() => { Voice.micError = null; voiceRerender(); })
          .catch((e) => { Voice.micError = micErrorMessage(e); toast(Voice.micError, "error"); voiceRerender(); });
      } })));
  } else if (Voice.srvMute) {
    c.appendChild(el("div", { class: "vc-banner" }, icon("micOff", 16),
      el("span", { text: "مدیرِ روم تو را بی‌صدا کرده — تا وقتی اجازه ندهد صدایت پخش نمی‌شود." })));
  } else if (isOwner()) {
    c.appendChild(el("div", { class: "vc-banner owner" }, icon("crown", 16),
      el("span", { text: "تو مدیر این تماسی؛ مدیریت هر عضو روی کارت خودش و تنظیمات جمعی پایین فهرست اعضاست." })));
  }

  const shell = el("div", { class: "vc-call-layout" });
  const main = el("div", { class: "vc-call-main" });
  const side = el("aside", { class: "vc-call-side" });

  const membersCard = el("section", { class: "card vc-members-card" });
  membersCard.appendChild(el("div", { class: "vc-section-head" },
    el("div", {},
      secTitle("اعضای حاضر", "users"),
      el("p", { class: "muted vc-section-help", text: isOwner() ? "برای مدیریت هر نفر، دکمه‌ی مدیریت زیر همان عضو را بزن." : "وضعیت میکروفون هر عضو به‌صورت زنده نمایش داده می‌شود." })),
    el("span", { class: "vc-count-badge", text: Voice.members.size.toLocaleString("fa-IR") })));
  const grid = el("div", { class: "vc-members" });
  Voice.membersGridEl = grid;   // مرجعِ پایدار تا با join/leave فقطِ همین گرید آپدیت شود (نه کلِ صفحه/چت)
  fillMembersGrid();
  membersCard.appendChild(grid);
  // ── مسدودشده‌ها ──
  // بن‌کردن روی اندروید کار می‌کرد ولی یک‌طرفه بود: هیچ فهرستی از بن‌شده‌ها دیده نمی‌شد و
  // «unban» هیچ ورودی‌ای در رابط نداشت، پس یک بنِ اشتباهی برای همیشه می‌ماند.
  if (isOwner() && Voice.banned.size) {
    const bannedSection = el("section", { class: "vc-banned-section" });
    bannedSection.appendChild(el("div", { class: "vc-banned-title" },
      icon("ban", 15),
      el("strong", { text: "کاربران مسدودشده" }),
      el("span", { class: "vc-banned-count", text: Voice.banned.size.toLocaleString("fa-IR") })));
    const bannedList = el("div", { class: "vc-banned-list" });
    [...Voice.banned.values()].forEach((b) => {
      const username = b.username || "کاربر";
      bannedList.appendChild(el("div", { class: "vc-banned-card" },
        el("div", { class: "vc-banned-avatar" }, avatarEl(username, b.avatar, 38),
          el("span", { class: "vc-banned-stamp", text: "مسدود" })),
        el("div", { class: "vc-banned-user" },
          el("strong", { text: username }),
          el("small", { text: "اجازه ورود به روم را ندارد" })),
        btn("رفع مسدودی", "unlock", "btn btn-sm vc-unban-btn", {
          "aria-label": `رفع مسدودی ${username}`,
          onclick: () => modAction("unban", username),
        })));
    });
    bannedSection.appendChild(bannedList);
    membersCard.appendChild(bannedSection);
  }
  // روی موبایل کنترلِ تماس (میوت/قطع) باید بدونِ اسکرول در دسترس باشد، پس قبل از فهرستِ اعضا
  // می‌نشیند؛ روی دسکتاپ ترتیبِ اصلی (اعضا بعد کنترل) حفظ می‌شود.
  if (!IS_MOBILE_UI) main.appendChild(membersCard);

  const ctl = el("div", { class: "card vc-controls" });
  ctl.appendChild(el("div", { class: "vc-controls-head" },
    el("strong", { text: "کنترل تماس" }),
    el("span", { class: "muted", text: Voice.srvMute ? "میکروفونت توسط مدیر بسته شده" : "تنظیمات فقط برای خودت" })));
  const primaryControls = el("div", { class: "vc-primary-controls" });
  primaryControls.appendChild(btn(Voice.mute ? "روشن کردن میکروفون" : "بستن میکروفون", Voice.mute ? "micOff" : "mic", "btn vc-call-control" + (Voice.mute ? " is-off" : " is-on"), { onclick: () => setMute(!Voice.mute) }));
  primaryControls.appendChild(btn(Voice.deaf ? "شنیدن دوباره" : "بستن صدای تماس", Voice.deaf ? "headphoneOff" : "headphones", "btn vc-call-control" + (Voice.deaf ? " is-off" : ""), { onclick: () => setDeaf(!Voice.deaf) }));
  // دوربین — همان دکمه‌ی «دوربین»ِ نسخه‌ی دسکتاپ. (دو دکمه‌ی دیگرِ آن ردیف،
  // «اشتراکِ صفحه» و «صفحه + دوربین»، این‌جا نیستند: getDisplayMedia در WebViewِ
  // اندروید وجود ندارد، پس دکمه‌شان فقط یک خطای همیشگی می‌شد.)
  {
    const on = !!Voice.videoSending;
    // دکمه‌ی دوربین فقط وضعیتِ دوربین را بگوید: وقتی صفحه در حالِ اشتراک است این
    // دکمه نباید «بستن دوربین» باشد، چون دوربینی روشن نیست.
    const camOn = on && Voice.videoSending.kind === "camera";
    primaryControls.appendChild(btn(camOn ? "بستن دوربین" : "دوربین", camOn ? "x" : "video",
      "btn vc-call-control" + (camOn ? " is-on" : ""),
      { onclick: () => (camOn ? stopVideoShare() : startVideoShare()) }));
    // اشتراکِ صفحه — روی دسکتاپ همیشه بود؛ این‌جا تازه ممکن شد (MihanScreenCast).
    if (screenShareSupported()) {
      const sharing = on && Voice.videoSending.kind === "screen";
      primaryControls.appendChild(btn(sharing ? "قطعِ اشتراکِ صفحه" : "اشتراکِ صفحه", "monitor",
        "btn vc-call-control" + (sharing ? " is-on" : ""),
        { onclick: () => (sharing ? stopScreenShare() : startScreenShare()) }));
    }
    // تعویضِ جلو/عقب فقط وقتی معنا دارد که دوربین روشن باشد و منبع هم دوربین باشد.
    if (on && Voice.videoSending.kind === "camera") {
      const back = (Voice.videoFacing || "user") === "environment";
      primaryControls.appendChild(btn(back ? "دوربینِ جلو" : "دوربینِ پشت", "refreshCw",
        "btn vc-call-control",
        { title: "تعویضِ دوربین", onclick: () => switchVideoCamera() }));
    }
  }
  const pttChk = el("input", { type: "checkbox" }); pttChk.checked = Voice.ptt;
  pttChk.addEventListener("change", () => { Voice.ptt = pttChk.checked; Voice.pttActive = false; setCfg("voice_ptt", Voice.ptt); registerPttHotkey(); voiceRerender(); });
  primaryControls.appendChild(el("label", { class: "vc-ptt-toggle" },
    pttChk,
    el("span", { class: "vc-ptt-copy" },
      el("strong", { text: "فشار برای صحبت" }),
      el("small", { text: Voice.ptt ? `روشن · کلید ${pttKeyLabel(Voice.pttKey)}` : "خاموش" }))));
  ctl.appendChild(primaryControls);
  if (Voice.ptt) {
    const hold = btn(`نگه‌دار و حرف بزن — یا کلیدِ ${pttKeyLabel(Voice.pttKey)}`, "mic", "btn btn-primary vc-hold");
    const down = (e) => { e.preventDefault(); Voice.pttActive = true; hold.classList.add("active"); };
    const up = () => { Voice.pttActive = false; hold.classList.remove("active"); };
    hold.addEventListener("mousedown", down); hold.addEventListener("mouseup", up); hold.addEventListener("mouseleave", up);
    hold.addEventListener("touchstart", down, { passive: false }); hold.addEventListener("touchend", up);
    const pttRow = el("div", { class: "vc-ptt-row" }, hold);
    // انتخابِ کلیدِ سراسری — حتی وقتی لانچر در پس‌زمینه است (مثلاً داخلِ بازی) کار می‌کند
    pttRow.appendChild(btn("تغییر کلید", "settings", "btn btn-sm", { title: "تغییرِ کلیدِ فشار-برای-صحبت (سراسری)", onclick: capturePttKey }));
    ctl.appendChild(pttRow);
  }
  if (!isOwner()) {
    // غیرمدیر: دستِ بالا — به مدیر علامت می‌دهد که می‌خواهد صحبت کند (مخصوصاً وقتی میوتِ پیش‌فرض روشن است)
    const meMem = Voice.members.get(Voice.meMid);
    const up = !!(meMem && meMem.hand_up);
    ctl.appendChild(btn(up ? "لغو درخواست صحبت" : "درخواست صحبت", "hand", "btn vc-hand-btn" + (up ? " btn-primary" : ""), { onclick: () => modAction(up ? "lower_hand" : "raise_hand") }));
  }
  main.appendChild(ctl);
  if (IS_MOBILE_UI) main.appendChild(vcCollapsible(membersCard, "اعضای حاضر", "users", true));
  if (isOwner()) main.appendChild(vcCollapsible(buildVoiceAdminPanel(), "مدیریت روم", "settings", false));

  const chat = el("div", { class: "card vc-chat" }, secTitle("چت روم", "messageCircle"));
  const list = el("div", { class: "vc-chat-list" }); Voice.chatListEl = list;
  (Voice.chat || []).forEach((m) => list.appendChild(renderChatMsg(m)));
  chat.appendChild(list);
  const input = el("input", { class: "input vc-chat-input", placeholder: "پیامت را بنویس…", maxlength: "500" });
  const send = () => { const t = input.value.trim(); if (!t) return; voiceSend({ t: "chat", text: t }); pushChat({ self: true, from: Voice.username, avatar: Voice.avatar, text: t, ts: Date.now() / 1000 }); input.value = ""; };
  input.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); send(); } });
  chat.appendChild(el("div", { class: "vc-chat-form" }, input, btn(null, "send", "btn btn-primary btn-icon", { onclick: send })));
  side.appendChild(vcCollapsible(chat, "چت روم", "messageCircle", false));
  side.appendChild(vcCollapsible(buildSoundboard(), "ساندبرد", "volume2", false));
  shell.appendChild(main);
  shell.appendChild(side);
  c.appendChild(shell);
  setTimeout(() => { list.scrollTop = list.scrollHeight; }, 0);
}
function buildSoundboard() {
  const card = el("div", { class: "card vc-soundboard" });
  // اگر مدیرِ روم ساندبرد را خاموش کرده باشد، اعضای عادی نمی‌توانند صدا پخش کنند.
  if (Voice.sbDisabled && !isOwner()) {
    card.appendChild(secTitle("ساندبرد", "volume2"));
    card.appendChild(el("div", { class: "muted", style: "padding:10px", text: "ساندبرد توسطِ مدیرِ روم خاموش شده است." }));
    return card;
  }
  card.appendChild(el("div", { class: "vc-sb-head" },
    secTitle("ساندبرد", "volume2"),
    btn("افزودن صدا", "plus", "btn btn-sm", { onclick: addPad })));
  card.appendChild(soundboardVolControl());
  const grid = el("div", { class: "vc-pads" });
  if (!(Voice.pads && Voice.pads.length)) {
    grid.appendChild(el("div", { class: "muted", style: "padding:8px", text: "هنوز صدایی اضافه نکردی. «افزودن صدا» را بزن (mp3/wav/ogg…)." }));
  } else {
    Voice.pads.forEach((p) => {
      grid.appendChild(el("div", { class: "vc-pad" },
        el("button", { class: "vc-pad-btn", title: p.label, onclick: () => playPad(p.file) }, icon("volume2", 16), el("span", { text: p.label })),
        btn(null, "x", "btn btn-sm btn-icon vc-pad-del", { title: "حذف", onclick: (e) => { e.stopPropagation(); deletePad(p.file); } })));
    });
  }
  card.appendChild(grid);
  card.appendChild(el("div", { class: "dim", style: "margin-top:6px;font-size:11px", text: "صداها فقط روی سیستمِ خودت ذخیره می‌شن؛ وقتی می‌زنی، از کانالِ صدای تو برای همه‌ی روم پخش می‌شه." }));
  return card;
}
function buildVoiceUI(c) {
  // متن/فوکوس/مکان‌نمای inputِ چت را قبل از بازسازی نگه می‌داریم تا وقتی پیام یا عضوِ جدید می‌آید و
  // پنل دوباره ساخته می‌شود، نوشته‌ی کسی که در حالِ تایپ است نپرد.
  const prev = c.querySelector(".vc-chat-input");
  const prevVal = prev ? prev.value : null;
  const wasFocused = prev && document.activeElement === prev;
  const selStart = prev ? prev.selectionStart : null;
  c.innerHTML = "";
  if (Voice.room) buildVoiceRoom(c); else buildVoiceLobby(c);
  if (prevVal) {
    const ni = c.querySelector(".vc-chat-input");
    if (ni) {
      ni.value = prevVal;
      if (wasFocused) { ni.focus(); try { ni.setSelectionRange(selStart, selStart); } catch (_) {} }
    }
  }
}

Pages.voice = async (root) => {
  { const a = adCard("voice_tab"); if (a) root.appendChild(a); }
  const info = await invoke("voice_info");
  if (!info || !info.logged_in) {
    root.appendChild(el("div", { class: "card" }, secTitle("گفتگوی صوتی", "mic"),
      el("p", { class: "muted", text: "برای گفتگوی صوتی اول وارد حساب لانچر شو (ثبت‌نام یا ورود)." })));
    root.appendChild(launcherAccountCard());
    return;
  }
  if (typeof AudioEncoder === "undefined" || typeof AudioDecoder === "undefined" || typeof MediaStreamTrackProcessor === "undefined") {
    root.appendChild(el("div", { class: "card" }, secTitle("گفتگوی صوتی", "mic"),
      el("p", { class: "muted", text: "نسخه‌ی WebView2 این سیستم از کدک صوتی (WebCodecs) پشتیبانی نمی‌کند. لطفاً WebView2 را به‌روزرسانی کن." })));
    return;
  }
  Voice.info = info; bindPttKeys();
  // کلید و حالتِ ذخیره‌شده‌ی فشار-برای-صحبت را بارگذاری و کلیدِ سراسری را ثبت کن
  Voice.pttKey = State.cfg.ptt_key || "F8";
  if (typeof State.cfg.voice_ptt === "boolean") Voice.ptt = State.cfg.voice_ptt;
  bindGlobalPtt(); registerPttHotkey();
  const c = el("div", { class: "voice-page" });
  root.appendChild(c);
  Voice.container = c;
  Voice.rerender = () => buildVoiceUI(c);
  onPageLeave(() => {
    Voice.rerender = null; Voice.container = null; Voice.chatListEl = null; Voice.membersGridEl = null;
    if (!Voice.room) voiceTeardown();   // در روم نیستی → اتصال را ببند؛ در روم هستی → تماس را زنده نگه‌دار
  });
  // اگر از قبل در روم هستی فوری بساز؛ وگرنه فقط یک اسپینرِ سبک تا لیستِ روم‌ها برسد —
  // این جلوی «دوبار لود شدن» (ساختِ کامل اولیه + بازساخت بعد از اتصال) را می‌گیرد.
  if (Voice.room) buildVoiceUI(c);
  else c.appendChild(el("div", { class: "row", style: "justify-content:center;padding:48px;grid-column:1/-1" }, el("span", { class: "spinner" })));
  // اتصال در پس‌زمینه (بدونِ await) تا صفحه فوری باز شود و قفلِ ناوبری معطل نماند.
  voiceEnsureConnected()
    .then(() => { if (!Voice.room) voiceSend({ t: "list" }); else voiceRerender(); })
    .catch(() => { c.innerHTML = ""; toast("اتصال به سرور صدا ناموفق بود — اینترنت/فیلترشکن را بررسی کن.", "error"); });
};

// ── چتِ همگانی (Global chat — مثلِ چت گلوبالِ Clash of Clans) ─
// همه‌ی کاربرها در یک کانالِ سراسری چت می‌کنند. اتصالِ WebSocket مثلِ صدا، با
// reconnect خودکار و backoff. پیام‌ها از سرور echo می‌شوند (با id/زمانِ سروری)،
// پس برای جلوگیری از دوتاشدن، پیامِ خودمان را محلی اضافه نمی‌کنیم.
const Chat = {
  info: null, ws: null, connected: false, _connecting: false,
  username: null, avatar: null, online: 0,
  msgs: [], seenIds: new Set(), oldestId: null, loadingMore: false,
  groups: [], currentChannel: 0, currentGroup: null, currentTopic: 0, topics: [],
  pingTimer: null, reconnectTimer: null, retry: 0,
  listEl: null, sidebarEl: null, container: null, jumpEl: null, _alive: false,
};

function chatSend(obj) { try { if (Chat.ws && Chat.ws.readyState === 1) Chat.ws.send(JSON.stringify(obj)); } catch (_) {} }

function chatStatusText() {
  if (Chat.connected) return `آنلاین: ${Chat.online}`;
  return Chat._connecting ? "در حال اتصال…" : "آفلاین — تلاش مجدد…";
}
function chatRefreshHeader() {
  if (Chat.onlineEl) Chat.onlineEl.textContent = chatStatusText();
  if (Chat.dotEl) Chat.dotEl.classList.toggle("on", Chat.connected);
}

function chatFindChannel(channelId) {
  for (const group of (Chat.groups || [])) {
    const channel = (group.channels || []).find((x) => Number(x.id) === Number(channelId));
    if (channel) return { group, channel };
  }
  return null;
}

function chatCanPost() {
  const found = chatFindChannel(Chat.currentChannel);
  if (!found || found.channel.type !== "broadcast") return true;
  return ["owner", "admin"].includes(found.group.role);
}

function chatRefreshComposer() {
  const canPost = chatCanPost();
  if (Chat.inputEl) {
    Chat.inputEl.disabled = !canPost;
    Chat.inputEl.placeholder = canPost ? "پیامت را بنویس…  (Enter ارسال، Shift+Enter خط جدید)" : "این کانال فقط برای انتشار مدیران است";
  }
  (Chat.composerButtons || []).forEach((x) => { if (x) x.disabled = !canPost; });
  if (Chat.readonlyEl) Chat.readonlyEl.style.display = canPost ? "none" : "flex";
}

function chatUpdateChannelHeader() {
  const found = chatFindChannel(Chat.currentChannel);
  const broadcast = !!(found && found.channel.type === "broadcast");
  if (Chat.titleEl) Chat.titleEl.textContent = found ? `${broadcast ? "📣" : "👥"} ${broadcast ? found.channel.name : found.group.name}` : "گفتگوی زنده";
  if (Chat.subEl) Chat.subEl.textContent = found
    ? (broadcast ? `${found.group.name} · کانال انتشار؛ فقط مدیران پیام می‌دهند` : `${found.group.members || 1} عضو · همهٔ اعضا می‌توانند پیام بدهند`)
    : "همه‌ی کاربرهای لانچر اینجا با هم گپ می‌زنند";
  if (Chat.manageBtn) Chat.manageBtn.style.display = found ? "" : "none";
  if (Chat.pinnedBarEl) {
    const pinned = found && found.group.pinned;
    if (pinned) {
      Chat.pinnedBarEl.style.display = "flex";
      Chat.pinnedBarEl.innerHTML = "";
      const labels = { image: "🖼️ تصویر", gif: "GIF", video: "🎬 ویدیو", voice: "🎤 پیامِ صوتی", poll: "📊 نظرسنجی", file: "📎 فایل" };
      Chat.pinnedBarEl.appendChild(icon("pin", 14));
      Chat.pinnedBarEl.appendChild(el("span", { class: "gc-pinned-text", text: pinned.text || labels[pinned.kind] || "پیام", onclick: () => scrollToMessage(Chat.listEl, pinned.id) }));
      if (["owner", "admin"].includes(found.group.role)) {
        Chat.pinnedBarEl.appendChild(btn(null, "x", "btn btn-sm btn-icon", { title: "برداشتنِ پین", onclick: () => chatSend({ t: "unpin_message", group: found.group.id }) }));
      }
    } else {
      Chat.pinnedBarEl.style.display = "none";
    }
  }
  chatRefreshComposer();
}

function chatResetMessages() {
  Chat.msgs = []; Chat.seenIds = new Set(); Chat.oldestId = null; Chat.noMoreHistory = false;
  Chat.loadingMore = false; clearChatReply();
  if (Chat.listEl) Chat.listEl.innerHTML = `<div class="muted gc-empty">در حال بارگذاری پیام‌ها…</div>`;
}

function chatSelectChannel(channelId) {
  channelId = Number(channelId) || 0;
  if (channelId === Chat.currentChannel && Chat.msgs.length) return;
  Chat.currentChannel = channelId; Chat.currentTopic = 0; Chat.topics = [];
  const found = chatFindChannel(channelId);
  Chat.currentGroup = found ? found.group.id : null;
  chatResetMessages(); chatUpdateChannelHeader(); renderChatSidebar(); renderTopicsBar();
  if (Chat.connected) {
    chatSend({ t: "switch_channel", channel: channelId });
    if (channelId) chatSend({ t: "list_topics", channel: channelId });
  }
}

// سوییچ به یک موضوعِ خاصِ داخلِ همان کانال (topicId=0 یعنی برگشت به جریانِ عمومی).
function chatSelectTopic(topicId) {
  topicId = Number(topicId) || 0;
  if (topicId === Chat.currentTopic && Chat.msgs.length) return;
  Chat.currentTopic = topicId;
  chatResetMessages(); renderTopicsBar();
  if (Chat.connected) chatSend({ t: "switch_topic", topic: topicId });
}

// نوارِ موضوع‌ها — فقط داخلِ یک کانالِ واقعی نمایش داده می‌شود (نه چتِ عمومی).
function renderTopicsBar() {
  const barEl = Chat.topicsBarEl; if (!barEl) return;
  barEl.innerHTML = "";
  if (!Chat.currentChannel) { barEl.style.display = "none"; return; }
  barEl.style.display = "flex";
  const generalChip = el("button", { class: "gc-topic-chip" + (Chat.currentTopic === 0 ? " active" : ""), type: "button", text: "کلی" });
  generalChip.addEventListener("click", () => chatSelectTopic(0));
  barEl.appendChild(generalChip);
  (Chat.topics || []).forEach((tp) => {
    const chip = el("button", { class: "gc-topic-chip" + (Chat.currentTopic === tp.id ? " active" : ""), type: "button", text: tp.name });
    chip.addEventListener("click", () => chatSelectTopic(tp.id));
    barEl.appendChild(chip);
  });
  const addBtn = btn(null, "plus", "btn btn-sm btn-icon", { title: "موضوعِ جدید", onclick: () => {
    chatNameDialog("موضوعِ جدید", "نامِ موضوع…", (name) => chatSend({ t: "create_topic", channel: Chat.currentChannel, name }));
  } });
  barEl.appendChild(addBtn);
}

function chatNameDialog(title, placeholder, onSubmit) {
  const input = el("input", { class: "input", maxlength: "40", placeholder });
  const dlg = modal({ title, body: el("label", { class: "field" }, el("span", { text: "نام" }), input), actions: [
    btn("ساخت", "plus", "btn btn-primary", { onclick: () => {
      const name = input.value.trim();
      if (name.length < 2) return toast("نام باید حداقل ۲ کاراکتر باشد.", "error");
      onSubmit(name); dlg.close();
    } }),
    btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
  ] });
  input.addEventListener("keydown", (e) => { if (e.key === "Enter") dlg.body.querySelector(".btn-primary")?.click(); });
  input.focus();
}

// ماتریسِ اختیاراتِ قابلِ‌تخصیص به یک مدیر — باید دقیقاً با GROUP_PERMISSIONS در chat.py هم‌خوان بماند.
const GROUP_PERMISSION_LABELS = {
  kick: "اخراجِ عضو", ban: "بن‌کردنِ عضو", mute: "سکوت‌کردنِ عضو", pin: "پین‌کردنِ پیام",
  manage_channels: "ساختِ کانالِ جدید", add_member: "افزودنِ مستقیمِ عضو", manage_invites: "ساختِ لینکِ دعوت",
};

// دیالوگِ تنظیمِ اختیاراتِ یک مدیرِ خاص — فقط owner می‌بیند. permissions=null یعنی «همه‌ی اختیارات» (پیش‌فرض).
function openMemberPermissionsDialog(group, mem) {
  const current = mem.permissions || {};
  const allByDefault = mem.permissions == null;
  const checkboxes = {};
  const body = el("div", { style: "display:flex;flex-direction:column;gap:10px;min-width:260px" },
    el("p", { class: "muted", style: "font-size:12px", text: `اختیاراتِ «${mem.username}» به‌عنوانِ مدیر در این گروه:` }));
  Object.keys(GROUP_PERMISSION_LABELS).forEach((key) => {
    const cb = el("input", { type: "checkbox" });
    cb.checked = allByDefault ? true : !!current[key];
    checkboxes[key] = cb;
    body.appendChild(el("label", { class: "row", style: "gap:8px;align-items:center;cursor:pointer" },
      cb, el("span", { text: GROUP_PERMISSION_LABELS[key] })));
  });
  const dlg = modal({
    title: "اختیاراتِ مدیر",
    body,
    actions: [
      btn("ذخیره", "check", "btn btn-primary", { onclick: () => {
        const permissions = {};
        Object.keys(checkboxes).forEach((key) => { permissions[key] = checkboxes[key].checked; });
        chatSend({ t: "set_member_permissions", group: group.id, username: mem.username, permissions });
        dlg.close();
      } }),
      btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
    ],
  });
}

// پنلِ مدیریتِ گروه: پابلیک/خصوصی، لینکِ دعوت، افزودنِ مستقیم، فهرستِ اعضا با کیک/بن/سکوت.
function openGroupManageDialog(group) {
  const myRole = group.role;
  const isOwner = myRole === "owner";
  const body = el("div", { style: "display:flex;flex-direction:column;gap:16px;min-width:320px" });

  if (isOwner) {
    const cb = el("input", { type: "checkbox" });
    cb.checked = group.is_public !== false;
    cb.addEventListener("change", () => chatSend({ t: "set_group_public", group: group.id, is_public: cb.checked }));
    body.appendChild(el("label", { class: "row", style: "gap:8px;align-items:center;cursor:pointer" },
      cb, el("span", { text: "گروهِ عمومی (در فهرستِ «گروه‌های عمومی» دیده می‌شود)" })));
  }

  if (["owner", "admin"].includes(myRole)) {
    const inviteWrap = el("div", { class: "field" }, el("span", { text: "لینکِ دعوت" }));
    // اختصاصیِ یک کانال (اختیاری) — بعدِ عضویت مستقیم همان کانال باز می‌شود، نه اولین کانالِ گروه
    const chSelect = el("select", { class: "input" },
      el("option", { value: "", text: "کلِ گروه (کانالِ پیش‌فرض)" }),
      ...(group.channels || []).map((ch) => el("option", { value: String(ch.id), text: ch.name })));
    const inviteRow = el("div", { class: "row", style: "gap:6px" });
    const inviteBtn = btn("ساختِ کدِ دعوت", "link", "btn btn-sm");
    inviteBtn.addEventListener("click", () => {
      Chat._pendingInviteResolve = (token) => {
        inviteRow.innerHTML = "";
        const codeEl = el("input", { class: "input", readonly: "readonly", style: "flex:1;font-family:monospace" });
        codeEl.value = token;
        const copyBtn = btn(null, "copy", "btn btn-sm btn-icon", { title: "کپی" });
        copyBtn.addEventListener("click", () => { navigator.clipboard.writeText(token).then(() => toast("کدِ دعوت کپی شد", "success")).catch(() => {}); });
        inviteRow.appendChild(codeEl); inviteRow.appendChild(copyBtn);
      };
      chatSend({ t: "create_invite", group: group.id, channel: chSelect.value ? Number(chSelect.value) : null });
    });
    inviteRow.appendChild(inviteBtn);
    inviteWrap.appendChild(chSelect);
    inviteWrap.appendChild(inviteRow);
    body.appendChild(inviteWrap);

    const addWrap = el("div", { class: "field" }, el("span", { text: "افزودنِ مستقیمِ عضو" }));
    const addSearch = el("input", { class: "input", placeholder: "جستجوی کاربر…" });
    const addResults = el("div", { class: "dm-search-res" });
    let addSt = null;
    addSearch.addEventListener("input", () => {
      clearTimeout(addSt);
      addSt = setTimeout(async () => {
        const q = addSearch.value.trim(); addResults.innerHTML = "";
        if (!q) return;
        try {
          const res = await invoke("dm_users", { q });
          ((res && res.users) || []).slice(0, 6).forEach((u) => {
            const row = el("div", { class: "dm-thread", style: "cursor:pointer" }, avatarEl(u.username, u.avatar, 28), el("div", { class: "dm-name", text: u.username }));
            row.addEventListener("click", () => { chatSend({ t: "add_member", group: group.id, username: u.username }); addSearch.value = ""; addResults.innerHTML = ""; });
            addResults.appendChild(row);
          });
        } catch (_) {}
      }, 300);
    });
    addWrap.appendChild(addSearch); addWrap.appendChild(addResults);
    body.appendChild(addWrap);
  }

  const membersWrap = el("div", { class: "field" }, el("span", { text: "اعضا" }));
  const membersList = el("div", { style: "display:flex;flex-direction:column;gap:2px;max-height:260px;overflow-y:auto" });
  const bansLabel = el("div", { class: "muted", style: "font-size:11px;margin-top:10px;display:none", text: "بن‌شده‌ها" });
  const bansList = el("div", { style: "display:flex;flex-direction:column;gap:2px" });
  membersWrap.appendChild(membersList); membersWrap.appendChild(bansLabel); membersWrap.appendChild(bansList);
  body.appendChild(membersWrap);

  const roleLabel = { owner: "مالک", admin: "مدیر", member: "عضو" };
  function renderMembers(data) {
    membersList.innerHTML = "";
    (data.members || []).forEach((mem) => {
      const isSelf = String(mem.username).toLowerCase() === String(Chat.username || "").toLowerCase();
      const iCanAct = !isSelf && ["owner", "admin"].includes(myRole) && mem.role !== "owner" && (mem.role !== "admin" || isOwner);
      const row = el("div", { class: "list-item" },
        avatarEl(mem.username, null, 28),
        el("div", { style: "flex:1;min-width:0" },
          el("div", { style: "font-weight:600", text: mem.username }),
          el("div", { class: "muted", style: "font-size:11px", text: (roleLabel[mem.role] || mem.role) + (mem.muted ? " · سکوت‌شده" : "") })));
      if (iCanAct) {
        const actions = el("div", { class: "row", style: "gap:4px" });
        if (isOwner && mem.role === "member") {
          actions.appendChild(btn(null, "shield", "btn btn-sm btn-icon", { title: "ارتقا به مدیر",
            onclick: () => chatSend({ t: "set_member_role", group: group.id, username: mem.username, role: "admin" }) }));
        }
        if (isOwner && mem.role === "admin") {
          actions.appendChild(btn(null, "settings", "btn btn-sm btn-icon", { title: "اختیاراتِ مدیر",
            onclick: () => openMemberPermissionsDialog(group, mem) }));
          actions.appendChild(btn(null, "chevronDown", "btn btn-sm btn-icon", { title: "تنزل به عضوِ عادی",
            onclick: () => confirmDialog("تنزلِ مدیر", `«${mem.username}» به عضوِ عادی تنزل یابد؟`, () => chatSend({ t: "set_member_role", group: group.id, username: mem.username, role: "member" })) }));
        }
        actions.appendChild(btn(null, mem.muted ? "volume2" : "volumeX", "btn btn-sm btn-icon", {
          title: mem.muted ? "برداشتنِ سکوت" : "سکوت (۱ساعت)",
          onclick: () => chatSend(mem.muted ? { t: "unmute_member", group: group.id, username: mem.username } : { t: "mute_member", group: group.id, username: mem.username, duration: 3600 }),
        }));
        actions.appendChild(btn(null, "userMinus", "btn btn-sm btn-icon", { title: "حذف از گروه",
          onclick: () => confirmDialog("حذفِ عضو", `«${mem.username}» از گروه حذف شود؟`, () => chatSend({ t: "kick_member", group: group.id, username: mem.username })) }));
        actions.appendChild(btn(null, "ban", "btn btn-sm btn-icon", { title: "بن‌کردن",
          onclick: () => confirmDialog("بن‌کردنِ عضو", `«${mem.username}» بن شود؟ دیگر نمی‌تواند عضو شود.`, () => chatSend({ t: "ban_member", group: group.id, username: mem.username })) }));
        row.appendChild(actions);
      }
      membersList.appendChild(row);
    });
    bansList.innerHTML = "";
    const bans = data.bans || [];
    bansLabel.style.display = bans.length ? "" : "none";
    bans.forEach((b) => {
      bansList.appendChild(el("div", { class: "list-item" },
        el("div", { style: "flex:1", text: b.username }),
        btn("آنبن", null, "btn btn-sm btn-ghost", { onclick: () => chatSend({ t: "unban_member", group: group.id, username: b.username }) })));
    });
  }
  function loadMembers() { Chat._pendingMembersResolve = renderMembers; chatSend({ t: "list_members", group: group.id }); }
  Chat._manageDialogGroup = group.id; Chat._manageDialogRefresh = loadMembers;
  loadMembers();

  const dlg = modal({
    title: `مدیریتِ «${group.name}»`, body,
    actions: [btn("بستن", null, "btn btn-ghost", { onclick: () => dlg.close() })],
    onClose: () => { Chat._manageDialogGroup = null; Chat._manageDialogRefresh = null; },
  });
}

// سایدبارِ گروه/کانال — سرور (chat-server/chat.py) پروتکلِ کامل دارد؛ اینجا فقط رندر می‌شود.
function renderChatSidebar() {
  const side = Chat.sidebarEl; if (!side) return;
  side.innerHTML = "";

  const newGroupBtn = btn(null, "plus", "btn btn-sm btn-icon", { title: "گروهِ جدید" });
  newGroupBtn.addEventListener("click", () => {
    chatNameDialog("گروهِ جدید", "مثلاً: گیمرهای مایهان", (name) => chatSend({ t: "create_group", name }));
  });
  const joinInviteBtn = btn(null, "link", "btn btn-sm btn-icon", { title: "پیوستن با کدِ دعوت" });
  joinInviteBtn.addEventListener("click", () => {
    chatNameDialog("پیوستن با کدِ دعوت", "کدِ دعوت را وارد کن", (token) => chatSend({ t: "join_by_invite", token }));
  });
  side.appendChild(el("div", { class: "gc-side-head" }, el("strong", { text: "چت" }), el("div", { class: "row", style: "gap:4px" }, joinInviteBtn, newGroupBtn)));

  side.appendChild(el("button", {
    class: "gc-channel gc-global" + (Number(Chat.currentChannel) === 0 ? " active" : ""),
    onclick: () => chatSelectChannel(0),
  }, icon("globe", 15), el("span", { text: "چت همگانی" })));

  const groups = Chat.groups || [];
  const joined = groups.filter((g) => g.joined);
  const open = groups.filter((g) => !g.joined);

  joined.forEach((g) => {
    const canManage = ["owner", "admin"].includes(g.role);
    const groupEl = el("div", { class: "gc-group" },
      el("div", { class: "gc-group-head" },
        el("div", { class: "gc-group-name" }, icon("users", 13), el("span", { text: g.name })),
        el("span", { class: "gc-member-count", text: String(g.members || 1) })));
    (g.channels || []).forEach((ch) => {
      const broadcast = ch.type === "broadcast";
      const chBtn = el("button", {
        class: "gc-channel" + (Number(Chat.currentChannel) === Number(ch.id) ? " active" : ""),
        title: broadcast ? "کانالِ انتشار — فقط مالک/ادمین پیام می‌دهند" : "کانالِ گفت‌وگو — همه پیام می‌دهند",
      }, icon(broadcast ? "megaphone" : "messageCircle", 14), el("span", { text: ch.name }));
      chBtn.addEventListener("click", () => chatSelectChannel(ch.id));
      groupEl.appendChild(chBtn);
    });
    if (canManage) {
      const addChBtn = el("button", { class: "gc-add-channel" }, icon("plus", 13), el("span", { text: "کانالِ جدید" }));
      addChBtn.addEventListener("click", () => {
        chatNameDialog("کانالِ جدید", "مثلاً: اطلاعیه‌ها", (name) => chatSend({ t: "create_channel", group: g.id, name }));
      });
      groupEl.appendChild(addChBtn);
    }
    side.appendChild(groupEl);
  });

  if (open.length) {
    side.appendChild(el("div", { class: "gc-group-head", style: "border-top:1px solid var(--glass-brd);padding-top:8px;margin-top:2px" },
      el("span", { class: "muted", style: "font-size:11px", text: "گروه‌های عمومی" })));
    open.forEach((g) => {
      const joinBtn = btn(g.name, "plus", "gc-channel gc-join", { title: "عضویت در این گروه" });
      joinBtn.addEventListener("click", () => chatSend({ t: "join_group", group: g.id }));
      side.appendChild(joinBtn);
    });
  }

  if (!joined.length && !open.length) {
    side.appendChild(el("div", { class: "gc-side-empty muted", text: "هنوز گروهی نیست — اولین گروه را بساز!" }));
  }
}

// ── فیلترِ ضدِ فحش: کلماتِ زشت (فارسی + فینگلیش) را با «حرف بد» جایگزین می‌کند ──
const PROFANITY = [
  "کیر","کص","کس‌کش","کسکش","کسخل","کسخول","کونی","کون","جنده","جاکش","کیری","کسمشنگ","کسشعر","کسشر",
  "مادرجنده","مادرسگ","پدرسگ","حرومزاده","حرومزاد","بیشرف","بی‌شرف","عوضی","گاییدم","گاییدن","بگام","بگایی",
  "لاشی","لجن","آشغال عوضی","دیوث","قرمساق","فاحشه","ساک زدن","ساکیدن","تخمی","ریدم","ریدی","گه خوری","گوه خوری",
  "kir","kos","koskesh","koskhol","kooni","koon","jende","jakesh","kiri","madarjende","madarsag","pedarsag",
  "haromzade","bisharaf","gaeedam","gaidam","goh","gooh","ridam","koskhar","dayoos","koskholi","fuck","shit","bitch","asshole","whore","slut","dick","pussy"
];
let PROFANITY_RE = null;
try { PROFANITY_RE = new RegExp("(" + PROFANITY.map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|") + ")", "gi"); } catch (_) {}
function filterProfanity(t) {
  if (!t || !PROFANITY_RE) return t || "";
  try { return t.replace(PROFANITY_RE, "حرف بد"); } catch (_) { return t; }
}

function setChatReply(m) {
  const labels = { image: "🖼️ تصویر", gif: "GIF", video: "🎬 ویدیو", voice: "🎤 پیام صوتی", poll: "📊 نظرسنجی" };
  Chat.replyTo = { id: m.id, from: m.from, text: (m.text || labels[m.kind] || "پیام").slice(0, 120) };
  const bar = Chat.replyBarEl; if (!bar) return;
  bar.innerHTML = "";
  bar.appendChild(el("div", { class: "gc-reply-bar-in" },
    el("span", { class: "gc-reply-ico" }, icon("reply", 14)),
    el("div", { style: "flex:1;min-width:0" },
      el("div", { class: "gc-reply-from", text: "پاسخ به " + (m.from || "") }),
      el("div", { class: "gc-reply-text", text: filterProfanity(Chat.replyTo.text) })),
    btn(null, "x", "btn btn-sm btn-icon", { title: "لغو", onclick: clearChatReply })));
  bar.style.display = "";
  try { Chat.inputEl && Chat.inputEl.focus(); } catch (_) {}
}
function clearChatReply() {
  Chat.replyTo = null;
  const bar = Chat.replyBarEl; if (bar) { bar.innerHTML = ""; bar.style.display = "none"; }
}
// کلیک روی نقل‌قولِ «پاسخ به …» بالای یک حباب: پیامِ اصلی رو (اگه هنوز توی همون لیستِ رندرشده
// باشه) پیدا می‌کنه، بهش اسکرول می‌کنه و یه لحظه هایلایتش می‌کنه.
function scrollToMessage(listEl, msgId) {
  if (!listEl || !msgId) return;
  const target = listEl.querySelector(`[data-mid="${CSS.escape(String(msgId))}"]`);
  if (!target) { toast("پیامِ اصلی توی این بخش از تاریخچه نیست", ""); return; }
  target.scrollIntoView({ block: "center", behavior: "smooth" });
  target.classList.add("gc-highlight");
  setTimeout(() => target.classList.remove("gc-highlight"), 1200);
}

function chatMediaUrl(path) {
  return (path && String(path).startsWith("/")) ? (socialBase() + path) : String(path || "");
}

function chatReactionPicker(m) {
  const emojis = ["👍", "❤️", "😂", "😮", "😢", "🔥", "👏", "🎉"];
  const body = el("div", { class: "gc-emoji-grid" });
  const dlg = modal({ title: "واکنش", body, actions: [] });
  emojis.forEach((emoji) => body.appendChild(el("button", { class: "gc-emoji-btn", text: emoji, onclick: () => {
    chatSend({ t: "react", message: m.id, emoji }); dlg.close();
  } })));
}

function chatDeleteMessage(m) {
  const label = m.kind === "text" ? "این پیام" : "این فایل/رسانه";
  const dlg = modal({ title: "حذف پیام", body: el("p", { text: `${label} برای همه حذف شود؟` }), actions: [
    btn("حذف برای همه", "trash", "btn btn-danger", { onclick: () => {
      chatSend({ t: "delete_message", message: m.id }); dlg.close();
    } }),
    btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
  ] });
}

function renderChatReactions(m) {
  const bar = el("div", { class: "gc-reactions" });
  (m.reactions || []).forEach((r) => bar.appendChild(el("button", {
    class: "gc-reaction" + (r.mine ? " mine" : ""),
    onclick: () => chatSend({ t: "react", message: m.id, emoji: r.emoji }),
  }, el("span", { text: r.emoji }), el("b", { text: String(r.count || 0) }))));
  return bar;
}

function renderChatPayload(bub, m) {
  const kind = m.kind || "text", extra = m.extra || {};
  if (kind === "sticker" && extra.media) {
    // استیکر بدونِ حبابِ تصویر و بدونِ کادر نشان داده می‌شود — مثلِ تلگرام.
    bub.classList.add("is-sticker");
    bub.appendChild(el("img", { class: "gc-sticker", src: chatMediaUrl(extra.media),
      alt: extra.name || "استیکر", loading: "lazy" }));
  } else if (["image", "gif"].includes(kind) && extra.media) {
    const img = el("img", { class: "gc-media-image", src: chatMediaUrl(extra.media), alt: extra.name || "تصویر", loading: "lazy" });
    img.addEventListener("click", () => T.opener.openUrl(img.src)); bub.appendChild(img);
  } else if (kind === "video" && extra.media) {
    const video = el("video", { class: "gc-media-video", controls: "", preload: "metadata", playsinline: "" });
    video.src = chatMediaUrl(extra.media); bub.appendChild(video);
  } else if (kind === "voice" && extra.media) {
    const audio = el("audio", { class: "gc-media-audio", controls: "", preload: "none" });
    audio.src = chatMediaUrl(extra.media);
    bub.appendChild(el("div", { class: "gc-voice" }, icon("mic", 17), audio,
      extra.duration ? el("span", { class: "muted", text: `${extra.duration}s` }) : el("span")));
  } else if (kind === "file" && extra.media) {
    const name = extra.name || "فایل";
    const file = el("button", { class: "gc-file", title: "دریافت فایل", onclick: () => T.opener.openUrl(chatMediaUrl(extra.media)) },
      el("span", { class: "gc-file-icon" }, icon("file", 22)),
      el("span", { class: "gc-file-info" },
        el("strong", { text: name }),
        el("small", { text: extra.size ? fmtBytes(extra.size) : "برای دریافت کلیک کن" })),
      icon("download", 17));
    bub.appendChild(file);
  } else if (kind === "poll") {
    const poll = extra.poll || extra;
    const wrap = el("div", { class: "gc-poll" }, el("strong", { class: "gc-poll-question", text: poll.question || m.text || "نظرسنجی" }));
    const total = Number(poll.total || 0), counts = poll.counts || [];
    (poll.options || []).forEach((option, i) => {
      const count = Number(counts[i] || 0), pct = total ? Math.round(count * 100 / total) : 0;
      wrap.appendChild(el("button", { class: "gc-poll-option" + (Number(poll.mine) === i ? " selected" : ""), onclick: () => chatSend({ t: "poll_vote", message: m.id, option: i }) },
        el("span", { class: "gc-poll-fill", style: `width:${pct}%` }),
        el("span", { class: "gc-poll-label", text: option }),
        el("span", { class: "gc-poll-count", text: total ? `${pct}٪` : "" })));
    });
    wrap.appendChild(el("div", { class: "muted gc-poll-total", text: `${total} رأی` })); bub.appendChild(wrap);
  }
  if (kind === "text" || (m.text && kind !== "poll")) bub.appendChild(el("div", { class: "gc-text", text: filterProfanity(m.text) }));
  const reactions = renderChatReactions(m); if (reactions.childElementCount) bub.appendChild(reactions);
}

function renderChatLine(m) {
  const self = (m.from === Chat.username);
  const row = el("div", { class: "gc-msg" + (self ? " mine" : ""), "data-mid": String(m.id || "") });
  { const av = avatarEl(m.from, m.avatar || (self ? (Chat.avatar || State.myAvatar) : null), 34); if (!self) nameClick(m.from, av); row.appendChild(av); }
  const bub = el("div", { class: "gc-bubble" });
  const from = el("div", { class: "gc-from" }, styledName(m.from, "", self ? " (تو)" : ""));
  const meta = el("div", { class: "gc-msg-meta" }, self ? from : nameClick(m.from, from));
  if (m.ts) meta.appendChild(el("time", { class: "gc-time", text: fmtChatTime(m.ts) }));
  // تعدادِ بازدید — فقط کانال‌هایِ نوعِ broadcast دارند (سرور فقط برایِ آن‌ها views می‌فرستد)
  if (typeof m.views === "number") meta.appendChild(el("span", { class: "gc-views", title: "تعدادِ بازدید" }, icon("eye", 12), " " + m.views));
  bub.appendChild(meta);
  // نقلِ پیامی که به آن پاسخ داده شده — کلیک‌پذیر: می‌بره سراغِ پیامِ اصلی
  if (m.reply) bub.appendChild(el("div", { class: "gc-reply-quote", style: "cursor:pointer", onclick: () => scrollToMessage(Chat.listEl, m.reply.to) },
    el("span", { class: "gc-reply-from", text: m.reply.from || "" }),
    el("span", { class: "gc-reply-text", text: filterProfanity(m.reply.text || "") })));
  renderChatPayload(bub, m);
  row.appendChild(bub);
  const canManageHere = (() => { const f = chatFindChannel(Chat.currentChannel); return !!f && ["owner", "admin"].includes(f.group.role); })();
  row.appendChild(el("div", { class: "gc-acts" },
    btn(null, "reply", "btn btn-sm btn-icon gc-copy", { title: "پاسخ", onclick: () => setChatReply(m) }),
    el("button", { class: "btn btn-sm btn-icon gc-copy", title: "واکنش", text: "☺", onclick: () => chatReactionPicker(m) }),
    m.text ? chatCopyBtn(m.text) : el("span"),
    canManageHere ? btn(null, "pin", "btn btn-sm btn-icon gc-copy", { title: "پین‌کردن", onclick: () => { const f = chatFindChannel(Chat.currentChannel); chatSend({ t: "pin_message", group: f.group.id, message: m.id }); } }) : el("span"),
    self ? btn(null, "trash", "btn btn-sm btn-icon gc-copy", { title: "حذف پیام", onclick: () => chatDeleteMessage(m) }) : el("span")));
  return row;
}
function fmtChatTime(ts) {
  try {
    const d = new Date(ts * 1000);
    const hh = String(d.getHours()).padStart(2, "0");
    const mm = String(d.getMinutes()).padStart(2, "0");
    return `${hh}:${mm}`;
  } catch (_) { return ""; }
}

function chatAppend(m) {
  if (m.id != null) { if (Chat.seenIds.has(m.id)) return; Chat.seenIds.add(m.id); }
  Chat.msgs.push(m);
  if (Chat.msgs.length > 400) {
    const drop = Chat.msgs.shift();
    if (drop && drop.id != null) Chat.seenIds.delete(drop.id);
  }
  if (Chat.listEl) {
    const near = (Chat.listEl.scrollHeight - Chat.listEl.scrollTop - Chat.listEl.clientHeight) < 80;
    if (Chat.listEl.querySelector(".gc-empty")) Chat.listEl.innerHTML = "";
    Chat.listEl.appendChild(renderChatLine(m));
    if (near) Chat.listEl.scrollTop = Chat.listEl.scrollHeight;
    else if (Chat.jumpEl) Chat.jumpEl.classList.add("show");
  }
}

function chatRerenderMessages() {
  if (!Chat.listEl) return;
  const near = (Chat.listEl.scrollHeight - Chat.listEl.scrollTop - Chat.listEl.clientHeight) < 90;
  Chat.listEl.innerHTML = "";
  Chat.msgs.forEach((x) => Chat.listEl.appendChild(renderChatLine(x)));
  if (!Chat.msgs.length) Chat.listEl.appendChild(el("div", { class: "muted gc-empty", text: "هنوز پیامی نیست — اولین نفر باش!" }));
  if (near) Chat.listEl.scrollTop = Chat.listEl.scrollHeight;
}

function chatScrollToLatest() {
  const list = Chat.listEl;
  if (!list) return;
  if (Chat._pinStop) { Chat._pinStop(); Chat._pinStop = null; }
  const apply = () => {
    if (Chat.listEl !== list || !list.isConnected) return false;
    list.scrollTop = list.scrollHeight;
    // در موبایل ارتفاعِ صفحه‌ی چت همیشه محدود نمی‌شود، پس .gc-list خودش اسکرول ندارد و
    // اسکرولِ واقعی روی یکی از والدها (کانتینرِ صفحه) یا خودِ سند است — همه را ته ببر.
    for (let n = list.parentElement; n && n !== document.body; n = n.parentElement) {
      if (n.scrollHeight - n.clientHeight > 8) n.scrollTop = n.scrollHeight;
    }
    const de = document.scrollingElement || document.documentElement;
    if (de && de.scrollHeight - de.clientHeight > 8) de.scrollTop = de.scrollHeight;
    if (Chat.jumpEl) Chat.jumpEl.classList.remove("show");
    return true;
  };
  apply();
  requestAnimationFrame(() => { apply(); requestAnimationFrame(apply); });
  // در وب‌ویویِ اندروید لیست دیرتر چیده می‌شود (آواتارها/فونت/انیمیشنِ ورودِ صفحه) و
  // ارتفاعش پس از این چند فریم هنوز رشد می‌کند؛ نتیجه‌اش این بود که چت از اولین پیام باز می‌شد.
  // پس تا ۲٫۵ ثانیه ته‌ی لیست را نگه می‌داریم، مگر خودِ کاربر اسکرول کند.
  const started = Date.now();
  const timer = setInterval(() => {
    if (!apply() || Date.now() - started > 2500) stop();
  }, 60);
  const onImg = (e) => { if (e.target && e.target.tagName === "IMG") apply(); };
  // همان تپی که صفحه‌ی چت را باز می‌کند، پس از سوارشدنِ لیست یک pointerdown روی خودِ لیست
  // می‌فرستد؛ اگر بی‌درنگ لغو کنیم دوباره بالای لیست می‌مانیم — پس ۴۰۰ms اول را نادیده بگیر.
  const userStop = () => { if (Date.now() - started > 400) stop(); };
  const stop = () => {
    clearInterval(timer);
    list.removeEventListener("load", onImg, true);
    list.removeEventListener("wheel", userStop);
    list.removeEventListener("touchstart", userStop);
    list.removeEventListener("pointerdown", userStop);
    if (Chat._pinStop === stop) Chat._pinStop = null;
  };
  list.addEventListener("load", onImg, true);
  list.addEventListener("wheel", userStop, { passive: true });
  list.addEventListener("touchstart", userStop, { passive: true });
  list.addEventListener("pointerdown", userStop, { passive: true });
  Chat._pinStop = stop;
}

function chatOnHistory(m, isMore) {
  if (m.channel != null && Number(m.channel) !== Number(Chat.currentChannel)) return;
  if (m.topic != null && Number(m.topic) !== Number(Chat.currentTopic)) return;
  const list = (m.messages || []).slice().sort((a, b) => {
    const aKey = Number(a.id || a.ts || a.created_at || 0);
    const bKey = Number(b.id || b.ts || b.created_at || 0);
    return aKey - bKey;
  });
  list.forEach((x) => noteProCosmetics(x.from, x.color, x.ring, x.nameplate));
  if (isMore) {
    // پیام‌های قدیمی‌تر را بالای لیست تزریق کن و موقعیتِ اسکرول را حفظ کن
    // پاسخِ خالی یعنی به ابتدایِ تاریخچه رسیدیم. بدونِ این پرچم، هر بار که کاربر
    // بالایِ لیست بماند دوباره همان درخواست می‌رفت و سرور بی‌دلیل کوبیده می‌شد.
    if (!list.length) { Chat.noMoreHistory = true; Chat.loadingMore = false; return; }
    Chat.oldestId = list[0].id;
    // ادغام در Chat.msgs نباید به وجودِ Chat.listEl گره بخورد: آن المان فقط مالِ
    // رابطِ قدیمیِ چت است و در مسنجرِ جدید (nx) هرگز ست نمی‌شود — یعنی آن‌جا
    // پیام‌های قدیمیِ گرفته‌شده از سرور بی‌صدا دور ریخته می‌شدند و چت «بیشتر لود
    // نمی‌کرد». مسنجرِ جدید خودش از روی Chat.msgs رندر می‌کند.
    const older = [];
    list.forEach((x) => { if (x.id != null && !Chat.seenIds.has(x.id)) { Chat.seenIds.add(x.id); older.push(x); } });
    Chat.msgs = older.concat(Chat.msgs);
    if (Chat.listEl) {
      const prevH = Chat.listEl.scrollHeight;
      const frag = document.createDocumentFragment();
      older.forEach((x) => frag.appendChild(renderChatLine(x)));
      Chat.listEl.insertBefore(frag, Chat.listEl.firstChild);
      Chat.listEl.scrollTop = Chat.listEl.scrollHeight - prevH;
    }
    Chat.loadingMore = false;
    return;
  }
  // بارگذاریِ اولیه — فقط ۱۰۰ پیامِ اخیر (بقیه با اسکرول به بالا لود می‌شود تا لگ نزند)
  const recent = list.slice(-100);
  Chat.msgs = recent.slice();
  Chat.seenIds = new Set(recent.map((x) => x.id).filter((x) => x != null));
  Chat.oldestId = recent.length ? recent[0].id : null;
  if (Chat.listEl) {
    Chat.listEl.innerHTML = "";
    recent.forEach((x) => Chat.listEl.appendChild(renderChatLine(x)));
    if (!recent.length) Chat.listEl.appendChild(el("div", { class: "muted gc-empty", text: "هنوز پیامی نیست — اولین نفر باش!" }));
    chatScrollToLatest();
  }
}

function chatOnMessage(ev) {
  let m; try { m = JSON.parse(ev.data); } catch (_) { return; }
  switch (m.t) {
    case "welcome":
      Chat.username = m.username; Chat.avatar = m.avatar;
      noteProCosmetics(m.username, m.color, m.ring, m.nameplate);
      if (Chat.currentChannel) chatSend({ t: "switch_channel", channel: Chat.currentChannel });
      // فهرستِ گروه‌ها/کانال‌ها را همیشه پسِ هر (باز)اتصال بگیر — تبِ اجتماعی روی همین Chat.groups
      // می‌نشیند و اگر فقط صفحه‌ی قدیمیِ چت آن را درخواست کند، پس از reconnect بیات می‌ماند.
      chatSend({ t: "groups" });
      break;
    case "groups":
      Chat.groups = Array.isArray(m.groups) ? m.groups : [];
      if (Chat.currentChannel && !chatFindChannel(Chat.currentChannel)) Chat.currentChannel = 0;
      renderChatSidebar(); chatUpdateChannelHeader();
      break;
    case "group_created":
    case "channel_created":
    case "group_joined":
      if (m.channel) chatSelectChannel(m.channel);
      chatSend({ t: "groups" });
      break;
    // ── قابلیت‌هایِ سبکِ تلگرام ──
    case "message_edited": {
      // متنِ پیامِ کش‌شده را جا‌به‌جا به‌روز کن تا رابط (چه قدیمی چه اجتماعی) تازه رندر کند.
      const hit = Chat.msgs.find((x) => Number(x.id) === Number(m.id));
      if (hit) { hit.text = m.text; hit.edited_at = m.edited_at; }
      break;
    }
    case "group_left":
    case "group_deleted":
    case "channel_deleted":
      // از جایی که دیگر وجود ندارد بیرون بیا، وگرنه کاربر در یک کانالِ مرده گیر می‌کند.
      if (m.t !== "group_left" || Chat.currentGroup === m.group) {
        Chat.currentChannel = 0; Chat.currentTopic = 0; Chat.msgs = []; Chat.seenIds = new Set();
      }
      chatSend({ t: "groups" });
      break;
    case "join_requested":
      toast(m.msg || "درخواستت ثبت شد؛ منتظرِ تأییدِ مدیر باش.", "info");
      break;
    case "join_request_new":
      toast(`${m.username} می‌خواهد عضوِ گروه شود.`, "info");
      break;
    case "history_cleared":
      // تاریخچه‌ی این کانال برایِ همه پاک شد — کشِ محلی هم باید خالی شود وگرنه کاربر
      // پیام‌هایی را می‌بیند که دیگر روی سرور نیستند.
      if (Number(m.channel) === Number(Chat.currentChannel)) {
        Chat.msgs = []; Chat.seenIds = new Set();
      }
      break;
    case "history": chatOnHistory(m, !!m.before); break;
    case "msg": {
      if (m.channel != null && Number(m.channel) !== Number(Chat.currentChannel)) break;
      // broadcast_channel سمتِ سرور فقط بر اساسِ کانال فیلتر می‌کند، نه موضوع — اینجا باید خودمان
      // پیامِ موضوعِ دیگر (یا برعکس، پیامِ جریانِ عمومی وقتی داخلِ یک موضوعیم) را رد کنیم.
      if (m.topic != null && Number(m.topic) !== Number(Chat.currentTopic)) break;
      noteProCosmetics(m.from, m.color, m.ring, m.nameplate);
      const line = { id: m.id, from: m.from, avatar: m.avatar, text: m.text, ts: m.ts, reply: m.reply,
        kind: m.kind || "text", extra: m.extra || {}, reactions: m.reactions || [] };
      chatAppend(line);
      // پیام‌های عادیِ همگانی مزاحم کاربر نمی‌شوند؛ فقط پاسخ مستقیم به پیام خود او اعلان دارد.
      const repliedToMe = !!(m.reply && Chat.username && String(m.reply.from || "") === String(Chat.username));
      if (m.from && m.from !== Chat.username && activePage !== "chat" && repliedToMe) {
        desktopNotify("پاسخ به پیام شما", String(m.text || "").slice(0, 140), "chat", { sender: m.from });
      }
      break;
    }
    case "message_deleted": {
      if (m.channel != null && Number(m.channel) !== Number(Chat.currentChannel)) break;
      Chat.msgs = Chat.msgs.filter((x) => Number(x.id) !== Number(m.id));
      Chat.seenIds.delete(m.id);
      if (Chat.replyTo && Number(Chat.replyTo.id) === Number(m.id)) clearChatReply();
      chatRerenderMessages();
      break;
    }
    case "poll_update": {
      const item = Chat.msgs.find((x) => Number(x.id) === Number(m.id));
      if (!item) break;
      item.extra = item.extra || {};
      const previousMine = item.extra.poll && item.extra.poll.mine;
      item.extra.poll = { ...(m.poll || {}) };
      if (m.actor !== Chat.username) item.extra.poll.mine = previousMine;
      chatRerenderMessages(); break;
    }
    case "reaction_update": {
      const item = Chat.msgs.find((x) => Number(x.id) === Number(m.id));
      if (!item) break;
      const previousMine = new Set((item.reactions || []).filter((r) => r.mine).map((r) => r.emoji));
      item.reactions = (m.reactions || []).map((r) => ({ ...r, mine: previousMine.has(r.emoji) }));
      if (m.actor === Chat.username) {
        const own = item.reactions.find((r) => r.emoji === m.emoji);
        if (own) own.mine = !!m.active;
      }
      chatRerenderMessages(); break;
    }
    case "gif_results":
      // پاسخِ Pickerِ قبلی (مثلاً وقتی کاربر GIF را بست و استیکر را باز کرد) نباید بنشیند.
      if (Chat.gifPicker && (!m.kind || m.kind === Chat.gifPicker.kind)) {
        Chat.gifPicker.render(Array.isArray(m.gifs) ? m.gifs : []);
      }
      break;
    case "gif_saved":
      if (Chat.gifPicker) Chat.gifPicker.request();
      break;
    case "gif_added":
      toast((m.kind === "sticker" ? "استیکر" : "GIF") + " به مجموعه اضافه شد", "success");
      if (Chat.gifPicker) Chat.gifPicker.request();
      break;
    case "online":
      Chat.online = m.count || 0;
      // فهرستِ یکپارچه‌ی کانال‌ها فقط در پوسته‌ی دسکتاپ هست؛ هابِ اجتماعیِ موبایل نسخه‌ی خودش را دارد.
      chatRefreshHeader();
      if (typeof renderUnifiedChannelRows === "function") renderUnifiedChannelRows();
      // شمارشِ آنلاینِ هر گروه داخلِ پیامِ groups می‌آید، نه این‌جا. رفرش را throttle
      // می‌کنیم چون سرور روی هر اتصال/قطعِ کسی این رویداد را می‌فرستد.
      if (Chat.connected && Date.now() - (Chat._lastGroupSync || 0) > 30000) {
        Chat._lastGroupSync = Date.now();
        try { chatSend({ t: "groups" }); } catch (_) {}
      }
      break;
    case "member_removed":
      toast(`«${m.username}» از گروه حذف شد.`, "success");
      if (Chat._manageDialogGroup === m.group) Chat._manageDialogRefresh && Chat._manageDialogRefresh();
      break;
    case "member_banned":
      toast(`«${m.username}» بن شد.`, "success");
      if (Chat._manageDialogGroup === m.group) Chat._manageDialogRefresh && Chat._manageDialogRefresh();
      break;
    case "member_unbanned":
      toast(`«${m.username}» آنبن شد.`, "success");
      if (Chat._manageDialogGroup === m.group) Chat._manageDialogRefresh && Chat._manageDialogRefresh();
      break;
    case "member_muted":
      if (m.me) toast("در این گروه سکوت شدی.", "error");
      else { toast(`«${m.username}» سکوت شد.`, "success"); if (Chat._manageDialogGroup === m.group) Chat._manageDialogRefresh && Chat._manageDialogRefresh(); }
      break;
    case "member_unmuted":
      toast(`سکوتِ «${m.username}» برداشته شد.`, "success");
      if (Chat._manageDialogGroup === m.group) Chat._manageDialogRefresh && Chat._manageDialogRefresh();
      break;
    case "member_added":
      toast(`«${m.username}» به گروه اضافه شد.`, "success");
      if (Chat._manageDialogGroup === m.group) Chat._manageDialogRefresh && Chat._manageDialogRefresh();
      break;
    case "member_role_changed": {
      const isMe = String(m.username || "").toLowerCase() === String(Chat.username || "").toLowerCase();
      const roleFa = m.role === "admin" ? "مدیر" : "عضوِ عادی";
      toast(isMe ? `نقشِ تو در این گروه به «${roleFa}» تغییر کرد.` : `نقشِ «${m.username}» به «${roleFa}» تغییر کرد.`, "success");
      if (Chat._manageDialogGroup === m.group) Chat._manageDialogRefresh && Chat._manageDialogRefresh();
      break;
    }
    case "member_permissions_changed": {
      const isMe2 = String(m.username || "").toLowerCase() === String(Chat.username || "").toLowerCase();
      if (isMe2) toast("اختیاراتِ مدیریتی‌ات در این گروه به‌روز شد.", "success");
      if (Chat._manageDialogGroup === m.group) Chat._manageDialogRefresh && Chat._manageDialogRefresh();
      break;
    }
    case "invite_created":
      if (Chat._pendingInviteResolve) { Chat._pendingInviteResolve(m.token); Chat._pendingInviteResolve = null; }
      break;
    case "members_list":
      if (Chat._pendingMembersResolve) { Chat._pendingMembersResolve(m); Chat._pendingMembersResolve = null; }
      break;
    case "topics_list":
      if (Number(m.channel) === Number(Chat.currentChannel)) { Chat.topics = m.topics || []; renderTopicsBar(); }
      break;
    case "topic_created":
      if (Number(m.channel) === Number(Chat.currentChannel)) {
        toast(`موضوعِ «${m.name}» ساخته شد`, "success");
        chatSend({ t: "list_topics", channel: m.channel });
        chatSelectTopic(m.topic);
      }
      break;
    case "error": toast(m.msg || "خطا در چت", "error"); break;
    case "pong": default: break;
  }
}

function chatConnect() {
  if (!Chat._alive) return;
  if (Chat.ws && (Chat.ws.readyState === 0 || Chat.ws.readyState === 1)) return;
  Chat._connecting = true; chatRefreshHeader();
  let ws;
  try { ws = new WebSocket(Chat.info.url); } catch (_) { chatScheduleReconnect(); return; }
  Chat.ws = ws;
  Chat._openedAt = Date.now();
  ws.onopen = () => { Chat.retry = 0; try { ws.send(JSON.stringify({ t: "hello", token: Chat.info.token })); } catch (_) {} };
  ws.onmessage = (ev) => {
    if (!Chat.connected) { Chat.connected = true; Chat._connecting = false; Chat._everConnected = true; chatRefreshHeader(); }
    chatOnMessage(ev);
  };
  ws.onerror = () => {};
  ws.onclose = (ev) => {
    const lived = Date.now() - (Chat._openedAt || 0);
    Chat.connected = false; Chat._connecting = false; chatRefreshHeader();
    if (Chat.pingTimer) { clearInterval(Chat.pingTimer); Chat.pingTimer = null; }
    // اگر بلافاصله بعد از hello بسته شد (و هیچ‌وقت پیامی نگرفتیم) یعنی توکن تأیید نشد → کاربر باید دوباره وارد شود.
    if (!Chat._everConnected && lived < 2500) {
      Chat._authFail = (Chat._authFail || 0) + 1;
      if (Chat._authFail >= 2 && Chat.listEl) {
        Chat.listEl.innerHTML = `<div class="muted gc-empty" style="line-height:2">نتونستیم به چت وصلت کنیم.<br>یک‌بار از حسابِ لانچر خارج و دوباره وارد شو، بعد برگرد به این تب.</div>`;
      }
    }
    chatScheduleReconnect();
  };
  if (Chat.pingTimer) clearInterval(Chat.pingTimer);
  Chat.pingTimer = setInterval(() => chatSend({ t: "ping" }), 25000);
}

function chatScheduleReconnect() {
  if (!Chat._alive) return;
  if (Chat.reconnectTimer) return;
  const delay = Math.min(1000 * Math.pow(2, Chat.retry), 15000);
  Chat.retry += 1;
  Chat.reconnectTimer = setTimeout(() => { Chat.reconnectTimer = null; chatConnect(); }, delay);
}

// The chat server snapshots Pro cosmetics during the websocket handshake.
// Reconnect after a successful change so newly sent messages carry the new
// frame/background for everyone, not only in this launcher's local preview.
function chatRefreshCosmetics() {
  if (!Chat._alive || !Chat.ws) return;
  try {
    if (Chat.ws.readyState === WebSocket.OPEN || Chat.ws.readyState === WebSocket.CONNECTING) {
      Chat.ws.close(1000, "cosmetics-refresh");
    }
  } catch (_) {}
}

function chatTeardown() {
  Chat._alive = false;
  if (Chat.pingTimer) { clearInterval(Chat.pingTimer); Chat.pingTimer = null; }
  if (Chat.reconnectTimer) { clearTimeout(Chat.reconnectTimer); Chat.reconnectTimer = null; }
  try { if (Chat.ws) { Chat.ws.onclose = null; Chat.ws.close(); } } catch (_) {}
  Chat.ws = null; Chat.connected = false; Chat._connecting = false;
  Chat.listEl = null; Chat.sidebarEl = null; Chat.container = null; Chat.jumpEl = null; Chat.onlineEl = null; Chat.dotEl = null;
  Chat.titleEl = null; Chat.subEl = null; Chat.manageBtn = null; Chat.pinnedBarEl = null; Chat.topicsBarEl = null;
}

// جداکردن DOM صفحه بدون بستن WebSocket؛ پیام‌ها در همه‌ی صفحه‌های لانچر زنده می‌مانند.
// بیرون از تب چت فقط ریپلای مستقیم به پیام خود کاربر اعلان دسکتاپ نشان می‌دهد.
function chatDetachUi() {
  Chat.listEl = null; Chat.sidebarEl = null; Chat.container = null; Chat.jumpEl = null; Chat.onlineEl = null; Chat.dotEl = null;
  Chat.titleEl = null; Chat.subEl = null; Chat.manageBtn = null; Chat.pinnedBarEl = null; Chat.topicsBarEl = null;
  Chat.inputEl = null; Chat.replyBarEl = null;
}

async function ensureBackgroundChat() {
  let info; try { info = await invoke("chat_info"); } catch (_) { return; }
  if (!info || !info.logged_in) return;
  if (Chat.ws && Chat._wsToken && Chat._wsToken !== info.token) chatTeardown();
  Chat.info = info; Chat._wsToken = info.token; Chat._alive = true;
  chatConnect();
}

// ── سیستمِ اجتماعی: پروفایل + پیامِ خصوصی + دوستی + تماسِ عادیِ ۲نفره ───────────
const Messages = { active: null, activeAvatar: null, _alive: false, _poll: null, lastId: 0, convoEl: null };

// نامِ کاربری قابلِ‌کلیک (هرجا: چت، ویس، گالری) → بازکردنِ پروفایل
function nameClick(name, node) {
  if (!name) return node;
  node.classList.add("clickable-name");
  node.style.cursor = "pointer";
  node.addEventListener("click", (e) => { e.stopPropagation(); openProfile(name); });
  return node;
}

async function openProfile(username) {
  if (!username) return;
  if (isMe && isMe(username)) { /* خودِ کاربر */ }
  if (!(State.cfg && State.cfg.account_token && State.cfg.account_token.length)) {
    toast("برای دیدنِ پروفایل‌ها اول وارد حساب لانچر شو", "error"); return;
  }
  let p;
  try { p = await invoke("user_profile", { username }); }
  catch (e) { toast("خطا: " + e, "error"); return; }
  noteProCosmetics(p.username, p.color, p.ring, p.nameplate);
  const body = el("div", { class: "profile-modal" });
  body.appendChild(el("div", { class: "profile-top", style: "display:flex;gap:12px;align-items:center" },
    avatarEl(p.username, p.avatar, 64),
    el("div", {}, el("div", { style: "font-size:18px;font-weight:700" }, styledName(p.username)),
      el("div", { class: "muted", style: "font-size:12px;margin-top:3px",
        text: `${p.followers || 0} دنبال‌کننده • ${p.following || 0} دنبال‌شده` }))));
  if (p.bio) body.appendChild(el("p", { class: "muted", style: "margin:10px 0 0", text: p.bio }));
  const dlg = modal({ title: "پروفایل", body, actions: [] });
  body.appendChild(btn("مشاهده‌ی پروفایلِ کامل", "user", "btn btn-sm", { style: "margin-top:10px", onclick: () => { dlg.close(); ProfileTarget = p.is_me ? null : username; go("profile"); } }));
  if (p.is_me) return;
  const reopen = () => { dlg.close(); openProfile(username); };
  const wrapBtn = (fn) => async () => { try { await fn(); } catch (e) { toast(String(e), "error"); } };

  // ردیفِ دوستی
  const fr = el("div", { class: "profile-btns", style: "display:flex;gap:8px;flex-wrap:wrap;margin-top:14px" });
  const fs = p.friend_status;
  if (fs === "friends") {
    fr.appendChild(btn("دوست ✓", "check", "btn btn-sm", { disabled: true }));
    fr.appendChild(btn("حذفِ دوست", null, "btn btn-sm btn-ghost", { onclick: wrapBtn(async () => { await invoke("friend_remove", { username }); toast("از دوستان حذف شد"); reopen(); }) }));
  } else if (fs === "out") {
    fr.appendChild(btn("درخواست فرستاده شد", "clock", "btn btn-sm", { disabled: true }));
    fr.appendChild(btn("لغوِ درخواست", null, "btn btn-sm btn-ghost", { onclick: wrapBtn(async () => { await invoke("friend_remove", { username }); reopen(); }) }));
  } else if (fs === "in") {
    fr.appendChild(btn("قبولِ دوستی", "check", "btn btn-sm btn-primary", { onclick: wrapBtn(async () => { await invoke("friend_request", { username }); toast("حالا دوستید! 🎉"); reopen(); }) }));
    fr.appendChild(btn("رد", null, "btn btn-sm btn-ghost", { onclick: wrapBtn(async () => { await invoke("friend_respond", { username, accept: false }); reopen(); }) }));
  } else {
    fr.appendChild(btn("درخواست دوستی", "userPlus", "btn btn-sm btn-primary", { onclick: wrapBtn(async () => { await invoke("friend_request", { username }); toast("درخواستِ دوستی فرستاده شد"); reopen(); }) }));
  }
  body.appendChild(fr);

  // ردیفِ پیام/تماس/دنبال‌کردن
  const r2 = el("div", { class: "profile-btns", style: "display:flex;gap:8px;flex-wrap:wrap;margin-top:8px" });
  r2.appendChild(btn("پیام", "messageSquare", "btn btn-sm", { onclick: () => { dlg.close(); Messages.active = username; Messages.activeAvatar = p.avatar; go("messages"); } }));
  r2.appendChild(btn("تماسِ عادی", "phone", "btn btn-sm", { onclick: () => { dlg.close(); startDmCall(username); } }));
  r2.appendChild(btn(p.is_following ? "دنبال‌شده ✓" : "دنبال‌کردن", "userPlus", "btn btn-sm btn-ghost", { onclick: wrapBtn(async () => { await invoke("follow_user", { username }); reopen(); }) }));
  body.appendChild(r2);
  // دکمه‌ی بلاک/آنبلاک — endpointِ block_user خودش toggle است، پس بر اساسِ وضعیتِ فعلی
  // (i_blocked) برچسب و پیام را عوض می‌کنیم تا کاربر بتواند از همین‌جا آنبلاک هم بکند.
  body.appendChild(btn(p.i_blocked ? "آنبلاک" : "بلاک", p.i_blocked ? "check" : null, "btn btn-sm btn-ghost", { style: "margin-top:6px;color:var(--danger)", onclick: wrapBtn(async () => { await invoke("block_user", { username }); toast(p.i_blocked ? "آنبلاک شد" : "بلاک شد"); dlg.close(); }) }));
}

// تماسِ عادیِ ۲نفره از داخلِ دایرکت: یک رومِ خصوصی می‌سازد و کدش را برای طرف پیام می‌کند.
async function startDmCall(username) {
  try {
    go("voice");
    await voiceEnsureConnected();
    const prev = (Voice.room && Voice.room.code) || null;
    voiceSend({ t: "create", name: `تماس با ${username}`, private: true });
    toast("در حال ساختِ تماس…", "info");
    for (let i = 0; i < 30; i++) {
      await new Promise((r) => setTimeout(r, 200));
      const code = Voice.room && Voice.room.code;
      if (code && code !== prev) {
        await invoke("dm_send", { to: username, text: `[[call:${code}]]` });
        toast(`لینکِ تماس برای ${username} فرستاده شد 📞`, "success");
        return;
      }
    }
    toast("روم ساخته نشد — دوباره امتحان کن", "error");
  } catch (e) { toast("تماس ناموفق: " + e, "error"); }
}
async function joinDmCall(code) {
  try { go("voice"); await voiceEnsureConnected(); voiceSend({ t: "join", code }); }
  catch (_) { toast("اتصال به سرور صدا ناموفق بود", "error"); }
}

function dmCallMatch(text) { return /^\s*\[\[call:([A-Za-z0-9_-]{1,32})\]\]\s*$/.exec(text || ""); }
function renderDmReactions(m) {
  const bar = el("div", { class: "gc-reactions" });
  const groups = {};
  (m.reactions || []).forEach((r) => {
    if (!groups[r.emoji]) groups[r.emoji] = { count: 0, mine: false };
    groups[r.emoji].count++;
    if (r.mine) groups[r.emoji].mine = true;
  });
  Object.keys(groups).forEach((emoji) => bar.appendChild(el("button", {
    class: "gc-reaction" + (groups[emoji].mine ? " mine" : ""),
    onclick: () => dmReact(m, emoji),
  }, el("span", { text: emoji }), el("b", { text: String(groups[emoji].count) }))));
  return bar;
}
function dmReplaceLine(m) {
  const row = Messages.convoEl && Messages.convoEl.querySelector(`[data-mid="${m.id}"]`);
  if (row) row.replaceWith(renderDmLine(m));
}
async function dmReact(m, emoji) {
  try {
    const res = await invoke("dm_react", { messageId: m.id, emoji });
    m.reactions = (m.reactions || []).filter((r) => !r.mine);
    if (res.active) m.reactions.push({ mine: true, emoji: res.emoji });
    dmReplaceLine(m);
  } catch (e) { toast("ثبت نشد: " + e, "error"); }
}
function dmReactionPicker(m) {
  const emojis = ["👍", "❤️", "😂", "😮", "😢", "🙏"];
  const body = el("div", { class: "gc-emoji-grid" });
  const dlg = modal({ title: "واکنش", body, actions: [] });
  emojis.forEach((emoji) => body.appendChild(el("button", { class: "gc-emoji-btn", text: emoji, onclick: () => { dmReact(m, emoji); dlg.close(); } })));
}
function dmEditMessage(m) {
  const input = el("textarea", { class: "input", rows: "3", maxlength: "2000" });
  input.value = m.text;
  const dlg = modal({ title: "ویرایشِ پیام", body: input, actions: [
    btn("ذخیره", "check", "btn btn-primary", { onclick: async () => {
      const text = input.value.trim();
      if (!text) return toast("متن نمی‌تواند خالی باشد.", "error");
      try {
        const res = await invoke("dm_edit", { messageId: m.id, text });
        m.text = text; m.edited_at = res.edited_at;
        dmReplaceLine(m); dlg.close();
      } catch (e) { toast("ویرایش نشد: " + e, "error"); }
    } }),
    btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
  ] });
  setTimeout(() => input.focus(), 60);
}
function dmDeleteMessage(m) {
  const actions = [];
  if (m.mine) {
    actions.push(btn("حذف برایِ همه", "trash", "btn btn-danger", { onclick: async () => {
      try {
        await invoke("dm_delete", { messageId: m.id, forEveryone: true });
        m.deleted = true; m.text = ""; dmReplaceLine(m); dlg.close();
      } catch (e) { toast("حذف نشد: " + e, "error"); }
    } }));
  }
  actions.push(btn("حذف فقط برایِ من", null, "btn btn-ghost", { onclick: async () => {
    try {
      await invoke("dm_delete", { messageId: m.id, forEveryone: false });
      const row = Messages.convoEl && Messages.convoEl.querySelector(`[data-mid="${m.id}"]`);
      if (row) row.remove();
      dlg.close();
    } catch (e) { toast("حذف نشد: " + e, "error"); }
  } }));
  actions.push(btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }));
  const dlg = modal({ title: "حذفِ پیام", body: el("p", { text: "این پیام چطور حذف شود؟" }), actions });
}

function renderDmLine(m) {
  const self = !!m.mine;
  const fromName = self ? ((State.cfg && State.cfg.account_username) || "خودم") : Messages.active;
  const row = el("div", { class: "gc-msg" + (self ? " mine" : ""), "data-mid": String(m.id || "") });
  const av = avatarEl(fromName, self ? State.myAvatar : Messages.activeAvatar, 30);
  if (!self) nameClick(fromName, av);
  row.appendChild(av);
  const bub = el("div", { class: "gc-bubble" });
  const from = el("div", { class: "gc-from" }, styledName(fromName, "", self ? " (تو)" : ""));
  bub.appendChild(self ? from : nameClick(fromName, from));
  if (m.deleted) {
    bub.appendChild(el("div", { class: "gc-text muted", style: "font-style:italic", text: "این پیام حذف شد" }));
    row.appendChild(bub);
    if (m.created_at) row.appendChild(el("div", { class: "gc-time", text: fmtChatTime(m.created_at) }));
    return row;
  }
  // نقلِ پیامِ پاسخ‌داده‌شده — کلیک‌پذیر: می‌بره سراغِ پیامِ اصلی
  if (m.reply) bub.appendChild(el("div", { class: "gc-reply-quote", style: "cursor:pointer", onclick: () => scrollToMessage(Messages.convoEl, m.reply.to) },
    el("span", { class: "gc-reply-from", text: m.reply.from || "" }),
    el("span", { class: "gc-reply-text", text: filterProfanity(m.reply.text || "") })));
  if (m.forwarded_from) bub.appendChild(el("div", { class: "gc-fwd-tag" }, icon("share", 11), el("span", { text: "فوروارد شده از " + m.forwarded_from })));
  const cm = dmCallMatch(m.text);
  if (m.kind === "voice") {
    // پیامِ صوتی: URLِ نسبیِ /media/.. را کامل کن و در <audio> پخش کن
    const src = (m.text && m.text.startsWith("/")) ? (socialBase() + m.text) : m.text;
    const audio = el("audio", { controls: "", preload: "none", style: "max-width:200px;height:34px;vertical-align:middle" });
    audio.src = src;
    bub.appendChild(el("div", { class: "gc-voice", style: "display:flex;align-items:center;gap:6px" }, icon("mic", 15), audio));
  } else if (cm) {
    bub.appendChild(el("div", { class: "gc-text", text: "📞 تماسِ عادی" }));
    bub.appendChild(btn("پیوستن به تماس", "phone", "btn btn-sm btn-primary", { style: "margin-top:5px", onclick: () => joinDmCall(cm[1]) }));
  } else {
    bub.appendChild(el("div", { class: "gc-text", text: filterProfanity(m.text) }));
  }
  if (m.edited_at) bub.appendChild(el("span", { class: "muted", style: "font-size:10px", text: " (ویرایش‌شده)" }));
  const reactions = renderDmReactions(m); if (reactions.childElementCount) bub.appendChild(reactions);
  row.appendChild(bub);
  const timeRow = el("div", { class: "gc-time" });
  if (m.created_at) timeRow.appendChild(el("span", { text: fmtChatTime(m.created_at) }));
  if (self) timeRow.appendChild(el("span", { class: "gc-read-tick", style: "margin-inline-start:3px;color:" + (m.read ? "var(--accent)" : "var(--text-3)"), text: m.read ? "✓✓" : "✓" }));
  row.appendChild(timeRow);
  if (!cm) row.appendChild(el("div", { class: "gc-acts" },
    btn(null, "reply", "btn btn-sm btn-icon gc-copy", { title: "پاسخ", onclick: () => setDmReply(m) }),
    el("button", { class: "btn btn-sm btn-icon gc-copy", title: "واکنش", text: "☺", onclick: () => dmReactionPicker(m) }),
    btn(null, "share", "btn btn-sm btn-icon gc-copy", { title: "فوروارد", onclick: () => dmForwardDialog(m) }),
    (m.kind === "voice" ? el("span") : chatCopyBtn(m.text)),
    (self && m.kind !== "voice" && m.kind !== "post") ? btn(null, "pencil", "btn btn-sm btn-icon gc-copy", { title: "ویرایش", onclick: () => dmEditMessage(m) }) : el("span"),
    btn(null, "trash", "btn btn-sm btn-icon gc-copy", { title: "حذف", onclick: () => dmDeleteMessage(m) })));
  return row;
}
function setDmReply(m) {
  Messages.replyTo = { id: m.id, from: (m.mine ? "خودم" : Messages.active), text: (m.kind === "voice" ? "🎤 پیامِ صوتی" : (m.text || "")).slice(0, 120) };
  const bar = Messages.replyBarEl; if (!bar) return;
  bar.innerHTML = "";
  bar.appendChild(el("div", { class: "gc-reply-bar-in" },
    el("span", { class: "gc-reply-ico" }, icon("reply", 14)),
    el("div", { style: "flex:1;min-width:0" },
      el("div", { class: "gc-reply-from", text: "پاسخ به " + Messages.replyTo.from }),
      el("div", { class: "gc-reply-text", text: filterProfanity(Messages.replyTo.text) })),
    btn(null, "x", "btn btn-sm btn-icon", { title: "لغو", onclick: clearDmReply })));
  bar.style.display = "";
  try { Messages.inputEl && Messages.inputEl.focus(); } catch (_) {}
}
function clearDmReply() {
  Messages.replyTo = null;
  const bar = Messages.replyBarEl; if (bar) { bar.innerHTML = ""; bar.style.display = "none"; }
}

// دیالوگِ فوروارد — همان الگویِ feedShareDialog (جست‌وجوی کاربر → ارسال با یک کلیک)
function dmForwardDialog(m) {
  if (m.kind === "voice" || m.kind === "post") return toast("این نوع پیام هنوز قابلِ فوروارد نیست.", "error");
  const search = el("input", { class: "input", placeholder: "جستجوی کاربر…" });
  const results = el("div", { class: "dm-search-res" });
  const dlg = modal({
    title: "فوروارد پیام",
    body: el("div", {}, search, results),
    actions: [btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() })],
  });
  let st = null;
  search.addEventListener("input", () => {
    clearTimeout(st);
    st = setTimeout(async () => {
      const q = search.value.trim(); results.innerHTML = "";
      if (!q) return;
      try {
        const res = await invoke("dm_users", { q });
        ((res && res.users) || []).slice(0, 6).forEach((u) => {
          const row = el("div", { class: "dm-thread", style: "cursor:pointer" },
            avatarEl(u.username, u.avatar, 32), el("div", { class: "dm-name", text: u.username }));
          row.addEventListener("click", async () => {
            try {
              const r = await invoke("dm_forward", { messageId: m.id, to: u.username });
              if (Messages.appendMsg) Messages.appendMsg(u.username, r && r.message);
              toast(`پیام برای ${u.username} فوروارد شد`, "success");
              dlg.close();
            } catch (e) { toast("فوروارد نشد: " + e, "error"); }
          });
          results.appendChild(row);
        });
      } catch (_) {}
    }, 300);
  });
  setTimeout(() => search.focus(), 60);
}

Messages.stopPoll = () => { if (Messages._poll) { clearVisibleInterval(Messages._poll); Messages._poll = null; } };

Messages.renderConvo = async (root, username) => {
  Messages.active = username;
  root.style.display = "flex"; root.style.flexDirection = "column"; root.style.height = "100%";
  const page = el("div", { class: "chat-page" });
  // آواتارِ هدر را با مرجعِ پایدار نگه می‌داریم تا وقتی آواتارِ واقعیِ طرف از سرور رسید جایگزینش کنیم
  const headAv = el("span", { class: "gc-head-av" }, avatarEl(username, Messages.activeAvatar, 32));
  const head = el("div", { class: "gc-head card" },
    el("div", { class: "gc-head-l", style: "display:flex;gap:8px;align-items:center" },
      btn(null, "arrowRight", "btn btn-sm btn-icon", { title: "برگشت", onclick: () => { Messages.active = null; Messages.stopPoll(); go("messages"); } }),
      headAv,
      nameClick(username, el("div", { class: "gc-title", text: username }))),
    el("div", { class: "gc-head-r" }, btn("تماس", "phone", "btn btn-sm", { onclick: () => startDmCall(username) })));
  page.appendChild(head);
  const list = el("div", { class: "gc-list card" }); Messages.convoEl = list;
  list.appendChild(el("div", { class: "muted gc-empty", text: "در حال بارگذاری…" }));
  page.appendChild(list);
  const input = el("input", { class: "input gc-input", placeholder: "پیامت را بنویس…", maxlength: "1000" });
  Messages.inputEl = input; Messages.replyTo = null;
  const replyBar = el("div", { class: "gc-reply-bar", style: "display:none" }); Messages.replyBarEl = replyBar;
  const sendBtn = btn(null, "send", "btn btn-primary btn-icon");
  const appendMsg = (msg) => { if (msg) { Messages.lastId = Math.max(Messages.lastId, msg.id || 0); list.appendChild(renderDmLine(msg)); list.scrollTop = list.scrollHeight; } };
  const doSend = async () => {
    const t = input.value.trim(); if (!t) return;
    const replyTo = (Messages.replyTo && Messages.replyTo.id) || 0;
    input.value = ""; clearDmReply(); input.focus();
    try {
      const res = await invoke("dm_send", { to: username, text: t, replyTo });
      appendMsg(res && res.message);
    } catch (e) { toast("ارسال نشد: " + e, "error"); input.value = t; }
  };
  sendBtn.addEventListener("click", doSend);
  input.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); doSend(); } });
  // ── ضبط و ارسالِ پیامِ صوتی (MediaRecorder → webm/opus) ──
  const recBtn = btn(null, "mic", "btn btn-icon", { title: "پیامِ صوتی — بزن تا شروع/ارسال شود" });
  let _rec = null, _chunks = [], _recStart = 0, _recTimer = null;
  const resetRecBtn = () => { recBtn.classList.remove("btn-danger"); recBtn.innerHTML = ""; recBtn.appendChild(icon("mic", 18)); recBtn.title = "پیامِ صوتی — بزن تا شروع/ارسال شود"; };
  const stopAndSend = async () => {
    const rec = _rec; if (!rec) return; _rec = null;
    if (_recTimer) { clearInterval(_recTimer); _recTimer = null; }
    resetRecBtn();
    await new Promise((res) => { rec.onstop = res; try { rec.stop(); } catch (_) { res(); } });
    try { rec._stream && rec._stream.getTracks().forEach((t) => t.stop()); } catch (_) {}
    const dur = Math.max(1, Math.round((Date.now() - _recStart) / 1000));
    if (!_chunks.length) return;
    const blob = new Blob(_chunks, { type: _chunks[0].type || "audio/webm" });
    if (blob.size < 200) return;
    const replyTo = (Messages.replyTo && Messages.replyTo.id) || 0;
    const b64 = await new Promise((res) => { const fr = new FileReader(); fr.onload = () => res(String(fr.result)); fr.readAsDataURL(blob); });
    clearDmReply();
    try { const res = await invoke("dm_send", { to: username, audio: b64, vdur: dur, replyTo }); appendMsg(res && res.message); }
    catch (e) { toast("ارسالِ صدا نشد: " + e, "error"); }
  };
  recBtn.addEventListener("click", async () => {
    if (_rec) return stopAndSend();
    if (typeof MediaRecorder === "undefined") return toast("مرورگر ضبطِ صدا را پشتیبانی نمی‌کند.", "error");
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      _chunks = []; _recStart = Date.now();
      const mr = new MediaRecorder(stream); _rec = mr; mr._stream = stream;
      mr.ondataavailable = (e) => { if (e.data && e.data.size) _chunks.push(e.data); };
      mr.start();
      recBtn.classList.add("btn-danger"); recBtn.innerHTML = ""; recBtn.appendChild(icon("square", 16));
      _recTimer = setInterval(() => { const s = Math.round((Date.now() - _recStart) / 1000); recBtn.title = `در حال ضبط ${s}s — بزن تا بفرستی`; if (s >= 120) stopAndSend(); }, 500);
      toast("در حال ضبط… دوباره روی دکمه بزن تا بفرستی 🎤", "");
    } catch (e) { toast(micErrorMessage(e), "error"); }
  });
  onPageLeave(() => { if (_rec) { try { _rec._stream && _rec._stream.getTracks().forEach((t) => t.stop()); _rec.stop(); } catch (_) {} _rec = null; } if (_recTimer) clearInterval(_recTimer); });
  page.appendChild(el("div", { class: "gc-form-wrap" }, replyBar, el("div", { class: "gc-form card" }, recBtn, input, sendBtn)));
  root.appendChild(page);

  const load = async (initial) => {
    try {
      const res = await invoke("dm_history", { withUser: username, after: initial ? 0 : Messages.lastId });
      // آواتارِ واقعیِ طرفِ گفتگو از سرور — هم در هدر، هم در حباب‌های بعدی استفاده می‌شود
      if (res && res.avatar && res.avatar !== Messages.activeAvatar) {
        Messages.activeAvatar = res.avatar;
        headAv.innerHTML = ""; headAv.appendChild(avatarEl(username, Messages.activeAvatar, 32));
      }
      const msgs = (res && res.messages) || [];
      if (initial) { list.innerHTML = ""; if (!msgs.length) list.appendChild(el("div", { class: "muted gc-empty", text: "هنوز پیامی نیست — اولین پیام را بفرست!" })); }
      msgs.forEach((m) => { if ((m.id || 0) > Messages.lastId || initial) { if (initial && list.querySelector(".gc-empty")) list.innerHTML = ""; list.appendChild(renderDmLine(m)); } });
      if (msgs.length) { Messages.lastId = Math.max(Messages.lastId, ...msgs.map((m) => m.id || 0)); list.scrollTop = list.scrollHeight; }
    } catch (e) { if (initial) { list.innerHTML = ""; list.appendChild(el("div", { class: "muted gc-empty", text: "خطا در بارگذاری پیام‌ها" })); } }
  };
  Messages.lastId = 0;
  await load(true);
  Messages.stopPoll();
  Messages._poll = setIntervalWhenVisible(() => { if (Messages.active === username && Messages._alive) load(false); }, 8000);
  setTimeout(() => input.focus(), 60);
};

Messages.renderList = async (root) => {
  const page = el("div", {});
  page.appendChild(secTitle("پیام‌ها", "messageSquare"));
  // جستجوی کاربر برای شروعِ گفتگوی جدید
  const search = el("input", { class: "input", placeholder: "جستجوی کاربر برای پیام دادن…", style: "margin:8px 0" });
  const results = el("div", { class: "dm-search-res" });
  let st = null;
  search.addEventListener("input", () => {
    clearTimeout(st);
    st = setTimeout(async () => {
      const q = search.value.trim(); results.innerHTML = "";
      if (q.length < 2) return;
      try {
        const res = await invoke("dm_users", { q });
        ((res && res.users) || []).slice(0, 3).forEach((u) => {
          const rowEl = el("div", { class: "dm-thread", style: "cursor:pointer" },
            avatarEl(u.username, u.avatar, 32), el("div", { class: "dm-name", text: u.username }));
          rowEl.addEventListener("click", () => { Messages.active = u.username; Messages.activeAvatar = u.avatar; go("messages"); });
          results.appendChild(rowEl);
        });
      } catch (_) {}
    }, 300);
  });
  page.appendChild(search); page.appendChild(results);

  // ── سه تب به‌جای بارگذاریِ هم‌زمانِ هر سه بخش (سریع‌تر: فقط تبِ فعال fetch می‌کند) ──
  const followRow = (u) => {
    const row = el("div", { class: "dm-thread", style: "cursor:pointer" },
      avatarEl(u.username, u.avatar, 32), el("div", { class: "dm-name", text: u.username }),
      btn("پیام", "messageSquare", "btn btn-sm btn-ghost", { style: "margin-inline-start:auto", onclick: (e) => { e.stopPropagation(); Messages.active = u.username; Messages.activeAvatar = u.avatar; go("messages"); } }));
    row.addEventListener("click", () => openProfile(u.username));
    return row;
  };

  // درخواست‌های دوستی + لیستِ دوستان
  function buildFriends() {
    const fl = el("div", { class: "card", style: "padding:10px" });
    fl.appendChild(el("div", { class: "muted", text: "در حال بارگذاری دوستان…" }));
    invoke("friend_list").then((res) => {
      fl.innerHTML = "";
      const inc = (res && res.incoming) || [], fri = (res && res.friends) || [];
      if (inc.length) {
        fl.appendChild(el("div", { style: "font-weight:700;margin-bottom:6px", text: `درخواست‌های دوستی (${inc.length})` }));
        inc.forEach((u) => {
          const row = el("div", { class: "dm-thread" }, nameClick(u.username, avatarEl(u.username, u.avatar, 32)),
            nameClick(u.username, el("div", { class: "dm-name", text: u.username })),
            el("div", { style: "margin-inline-start:auto;display:flex;gap:6px" },
              btn("قبول", "check", "btn btn-sm btn-primary", { onclick: async () => { try { await invoke("friend_request", { username: u.username }); toast("دوست شدید!"); go("messages"); } catch (e) { toast(e, "error"); } } }),
              btn("رد", null, "btn btn-sm btn-ghost", { onclick: async () => { try { await invoke("friend_respond", { username: u.username, accept: false }); go("messages"); } catch (e) { toast(e, "error"); } } })));
          fl.appendChild(row);
        });
      }
      fl.appendChild(el("div", { style: "font-weight:700;margin:8px 0 6px", text: `دوستان (${fri.length})` }));
      if (!fri.length) fl.appendChild(el("div", { class: "muted", text: "هنوز دوستی نداری — رو پروفایلِ کسی بزن و درخواست بده." }));
      fri.forEach((u) => {
        const row = el("div", { class: "dm-thread", style: "cursor:pointer" },
          avatarEl(u.username, u.avatar, 32), el("div", { class: "dm-name", text: u.username }),
          btn("پیام", "messageSquare", "btn btn-sm btn-ghost", { style: "margin-inline-start:auto", onclick: (e) => { e.stopPropagation(); Messages.active = u.username; Messages.activeAvatar = u.avatar; go("messages"); } }));
        row.addEventListener("click", () => { Messages.active = u.username; Messages.activeAvatar = u.avatar; go("messages"); });
        fl.appendChild(row);
      });
    }).catch(() => { fl.innerHTML = ""; fl.appendChild(el("div", { class: "muted", text: "خطا در بارگذاری دوستان" })); });
    return fl;
  }

  // دنبال‌شده‌ها و دنبال‌کننده‌ها
  function buildFollow() {
    const flw = el("div", { class: "card", style: "padding:10px" });
    flw.appendChild(el("div", { class: "muted", text: "در حال بارگذاری دنبال‌کننده‌ها…" }));
    invoke("follow_list").then((res) => {
      flw.innerHTML = "";
      const fo = (res && res.following) || [], fr = (res && res.followers) || [];
      flw.appendChild(el("div", { style: "font-weight:700;margin-bottom:6px", text: `دنبال‌شده‌ها (${fo.length})` }));
      if (!fo.length) flw.appendChild(el("div", { class: "muted", style: "font-size:12px", text: "هنوز کسی را دنبال نکرده‌ای." }));
      fo.forEach((u) => flw.appendChild(followRow(u)));
      flw.appendChild(el("div", { style: "font-weight:700;margin:10px 0 6px", text: `دنبال‌کننده‌ها (${fr.length})` }));
      if (!fr.length) flw.appendChild(el("div", { class: "muted", style: "font-size:12px", text: "هنوز کسی دنبالت نکرده." }));
      fr.forEach((u) => flw.appendChild(followRow(u)));
    }).catch(() => { flw.innerHTML = ""; flw.appendChild(el("div", { class: "muted", text: "خطا در بارگذاری دنبال‌کننده‌ها" })); });
    return flw;
  }

  // گفتگوهای اخیر
  function buildThreads() {
    const threads = el("div", { class: "card", style: "padding:10px" });
    threads.appendChild(el("div", { class: "muted", text: "در حال بارگذاری گفتگوها…" }));
    invoke("dm_threads").then((res) => {
      threads.innerHTML = "";
      const list = (res && res.threads) || [];
      if (!list.length) { threads.appendChild(el("div", { class: "muted", text: "هنوز گفتگویی نداری." })); return; }
      list.forEach((t) => {
        const row = el("div", { class: "dm-thread", style: "cursor:pointer" },
          avatarEl(t.username, t.avatar, 38),
          el("div", { style: "min-width:0;flex:1" },
            el("div", { class: "dm-name", text: t.username }),
            el("div", { class: "muted", style: "font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis", text: (t.last_mine ? "تو: " : "") + (dmCallMatch(t.last_text) ? "📞 تماسِ صوتی" : (t.last_text || "")) })),
          t.unread ? el("span", { class: "dm-unread", text: String(t.unread) }) : el("span", {}));
        row.addEventListener("click", () => { Messages.active = t.username; Messages.activeAvatar = t.avatar; go("messages"); });
        threads.appendChild(row);
      });
    }).catch(() => { threads.innerHTML = ""; threads.appendChild(el("div", { class: "muted", text: "خطا در بارگذاری گفتگوها" })); });
    return threads;
  }

  const builders = { threads: buildThreads, friends: buildFriends, follow: buildFollow };
  const TABS = [["threads", "گفتگوها", "messageSquare"], ["friends", "دوستان و درخواست‌ها", "users"], ["follow", "دنبال‌کننده/شده", "userPlus"]];
  const built = {};   // کش: هر تب فقط یک‌بار fetch می‌شود
  const chipEls = {};
  const tabBar = el("div", { class: "chips", style: "margin:12px 0" });
  const content = el("div", {});
  function show(t) {
    Object.entries(chipEls).forEach(([k, c]) => c.classList.toggle("active", k === t));
    content.innerHTML = "";
    if (!built[t]) built[t] = builders[t]();
    content.appendChild(built[t]);
  }
  TABS.forEach(([id, label, ic]) => {
    const c = el("div", { class: "chip chip-ic" }, icon(ic, 14), el("span", { text: label }));
    c.addEventListener("click", () => show(id));
    chipEls[id] = c; tabBar.appendChild(c);
  });
  page.appendChild(tabBar); page.appendChild(content);
  show("threads");   // فقط تبِ پیش‌فرض لود می‌شود

  root.appendChild(page);
};

Pages.messages = async (root) => {
  const info = await invoke("chat_info");
  if (!info || !info.logged_in) {
    root.appendChild(el("div", { class: "card" }, secTitle("پیام‌ها", "messageSquare"),
      el("p", { class: "muted", text: "برای پیامِ خصوصی و دوستی، اول وارد حساب لانچر شو (ثبت‌نام یا ورود)." })));
    root.appendChild(launcherAccountCard());
    return;
  }
  Messages._alive = true;
  onPageLeave(() => { Messages._alive = false; Messages.stopPoll(); });
  if (Messages.active) await Messages.renderConvo(root, Messages.active);
  else await Messages.renderList(root);
};

async function chatPickAndUpload(captionInput) {
  if (!chatCanPost()) return toast("در کانال فقط مدیران می‌توانند فایل بفرستند.", "error");
  const file = await pickFile("*/*");
  if (!file) return;
  const lower = file.name.toLowerCase();
  const isVideo = file.type.startsWith("video/") || /\.(mp4|webm)$/.test(lower);
  const isImage = file.type.startsWith("image/") && !/\.gif$/i.test(lower);
  const kind = isVideo ? "video" : (isImage ? "image" : "file");
  const limit = isVideo ? 20 * 1024 * 1024 : (isImage ? 6 * 1024 * 1024 : 25 * 1024 * 1024);
  if (file.size > limit) return toast(`حجم فایل زیاد است (حداکثر ${Math.round(limit / 1024 / 1024)} مگابایت).`, "error");
  const caption = captionInput ? captionInput.value.trim().slice(0, 300) : "";
  toast("در حال آپلود…", "info");
  try {
    const data = await blobToDataUrl(file);
    const uploaded = await invoke("chat_upload", { data, kind, name: file.name });
    const payload = { t: "msg", kind: uploaded.type || kind, media: uploaded.url,
      media_name: file.name, media_size: uploaded.size || file.size, text: caption };
    if (Chat.replyTo && Chat.replyTo.id) payload.reply_to = Chat.replyTo.id;
    chatSend(payload); clearChatReply();
    if (captionInput) { captionInput.value = ""; captionInput.dispatchEvent(new Event("input")); }
    toast("فایل ارسال شد", "success");
  } catch (e) { toast("آپلود ناموفق: " + moderationText(e), "error"); }
}

function chatEmojiDialog(input) {
  const emojis = ["😀","😂","😍","😎","🥳","😭","😡","🤔","👍","👎","❤️","🔥","✨","🎉","💀","👀","🙏","💪","🎮","⛏️"];
  const grid = el("div", { class: "gc-emoji-grid" });
  const dlg = modal({ title: "ایموجی", body: grid, actions: [] });
  emojis.forEach((emoji) => grid.appendChild(el("button", { class: "gc-emoji-btn", type: "button", text: emoji, onclick: () => {
    const start = Number.isFinite(input.selectionStart) ? input.selectionStart : input.value.length;
    const end = Number.isFinite(input.selectionEnd) ? input.selectionEnd : start;
    input.setRangeText(emoji, start, end, "end");
    input.dispatchEvent(new Event("input")); input.focus(); dlg.close();
  } })));
}

// ── سوییچِ موقتِ گیف/استیکر/ایموجی ──────────────────────────────────────────
// موقتاً از رابطِ کاربری برداشته شده تا گیتِ تعدیلِ محتوا برایشان مستقر شود. هیچ
// کدی حذف نشده: openGifPicker و chatEmojiDialog و مسیرِ add_gif/save_gif همگی
// دست‌نخورده‌اند و با true شدنِ همین یک ثابت، دکمه‌ها دقیقاً برمی‌گردند.
// نکته: نسخه‌ی اندروید و پیام‌هایِ گیف/استیکرِ قبلی همچنان نمایش داده می‌شوند —
// این فقط جلویِ *فرستادنِ* تازه را از این لانچر می‌گیرد.
const STICKERS_ENABLED = false;

// GIF و استیکر هر دو از یک مکانیزم می‌آیند (کتابخانهٔ مشترکِ سرور + همان تب‌ها)؛ فقط
// نوعِ فایل و ظاهرِ پیام فرق می‌کند، پس یک Picker با پارامترِ kind کافی است.
const GIF_PICKER_KINDS = {
  gif: {
    title: "GIF", label: "GIF", accept: "image/gif,.gif", maxSize: 6 * 1024 * 1024,
    extRe: /\.gif$/i, extHint: "یک GIF حداکثر ۶ مگابایتی انتخاب کن.",
    denied: "در کانال فقط مدیران می‌توانند GIF بفرستند.",
  },
  sticker: {
    title: "استیکر", label: "استیکر", accept: "image/png,image/webp,image/gif,.png,.webp,.gif",
    maxSize: 3 * 1024 * 1024, extRe: /\.(png|webp|gif)$/i,
    extHint: "استیکر باید PNG یا WebP یا GIF و حداکثر ۳ مگابایتی باشد (ترجیحاً پس‌زمینه‌شفاف).",
    denied: "در کانال فقط مدیران می‌توانند استیکر بفرستند.",
  },
};

function openGifPicker(kind = "gif") {
  const spec = GIF_PICKER_KINDS[kind] || GIF_PICKER_KINDS.gif;
  if (!chatCanPost()) return toast(spec.denied, "error");
  const search = el("input", { class: "input gc-gif-search", placeholder: `جستجو در ${spec.label}‌ها…`, maxlength: "60" });
  const list = el("div", { class: "gc-gif-grid" + (kind === "sticker" ? " is-sticker" : "") },
    el("div", { class: "muted gc-gif-empty", text: "در حال بارگذاری…" }));
  let scope = "popular", debounce = null;
  const tabs = [
    { key: "popular", el: el("button", { class: "chip active", text: "محبوب‌ترین‌ها" }) },
    { key: "recent", el: el("button", { class: "chip", text: "اخیر" }) },
    { key: "saved", el: el("button", { class: "chip", text: "ذخیره‌شده‌ها" }) },
  ];
  const request = () => chatSend({ t: "gifs", q: search.value.trim(), scope, kind, saved: scope === "saved" });
  const switchTab = (value) => {
    scope = value;
    tabs.forEach((tab) => tab.el.classList.toggle("active", tab.key === scope));
    list.innerHTML = `<div class="muted gc-gif-empty">در حال بارگذاری…</div>`;
    request();
  };
  tabs.forEach((tab) => { tab.el.onclick = () => switchTab(tab.key); });
  const addBtn = btn("افزودن به مجموعه", "plus", "btn btn-sm", { onclick: async () => {
    const file = await pickFile(spec.accept); if (!file) return;
    if (!spec.extRe.test(file.name) || file.size > spec.maxSize) return toast(spec.extHint, "error");
    try {
      toast(`در حال افزودن ${spec.label}…`, "info");
      const uploaded = await invoke("chat_upload", { data: await blobToDataUrl(file), kind: "gif", name: file.name });
      chatSend({ t: "add_gif", url: uploaded.url, kind, name: file.name.replace(/\.[a-z0-9]+$/i, "") });
    } catch (e) { toast(`افزودن ${spec.label} ناموفق بود: ` + moderationText(e), "error"); }
  } });
  const body = el("div", { class: "gc-gif-picker" },
    el("div", { class: "gc-gif-tools" }, search, addBtn),
    el("div", { class: "chips gc-gif-tabs" }, ...tabs.map((tab) => tab.el)), list);
  const dlg = modal({ title: spec.title, body, actions: [], onClose: () => { if (Chat.gifPicker && Chat.gifPicker.list === list) Chat.gifPicker = null; } });
  Chat.gifPicker = { list, kind, request, render(gifs) {
    list.innerHTML = "";
    if (!gifs.length) {
      list.appendChild(el("div", { class: "muted gc-gif-empty" },
        el("p", { text: scope === "saved" ? `هنوز ${spec.label} ذخیره‌شده نداری.` : `هنوز ${spec.label}ی در مجموعه نیست.` }),
        el("p", { text: `${spec.label} را فقط یک‌بار به مجموعه اضافه کن؛ بعد از اینجا مستقیم می‌فرستی.` })));
      return;
    }
    gifs.forEach((g, index) => {
      const card = el("div", { class: "gc-gif-card" });
      const img = el("img", { src: chatMediaUrl(g.url), alt: g.name || spec.label, loading: "lazy" });
      img.onclick = () => {
        const payload = { t: "msg", kind, media: g.url, media_name: g.name || spec.label };
        if (Chat.replyTo && Chat.replyTo.id) payload.reply_to = Chat.replyTo.id;
        chatSend(payload); clearChatReply(); Chat.gifPicker = null; dlg.close();
      };
      const star = el("button", { class: "gc-gif-save" + (g.saved ? " saved" : ""), title: g.saved ? "حذف از ذخیره‌ها" : `ذخیرهٔ ${spec.label}`, text: g.saved ? "★" : "☆", onclick: (e) => { e.stopPropagation(); chatSend({ t: "save_gif", url: g.url }); } });
      card.append(img, star);
      // نشانِ محبوبیت: تعدادِ کاربرانِ یکتایی که فرستاده‌اند (نه تعدادِ کلِ ارسال‌ها).
      const users = Number(g.users || 0);
      if (users > 0) card.appendChild(el("span", { class: "gc-gif-uses", title: `${users} کاربر از این ${spec.label} استفاده کرده‌اند` },
        el("span", { text: "👤" }), el("b", { text: String(users) })));
      if (scope === "popular" && index < 3) card.appendChild(el("span", { class: "gc-gif-rank", text: `#${index + 1}` }));
      list.appendChild(card);
    });
  } };
  search.addEventListener("input", () => { clearTimeout(debounce); debounce = setTimeout(request, 250); });
  request(); search.focus();
}

function chatPollDialog() {
  if (!chatCanPost()) return toast("در کانال فقط مدیران می‌توانند نظرسنجی بفرستند.", "error");
  const question = el("input", { class: "input", maxlength: "200", placeholder: "سؤال نظرسنجی" });
  const options = el("div", { class: "stack gc-poll-fields" });
  const addOption = (value = "") => {
    if (options.children.length >= 10) return;
    const input = el("input", { class: "input", maxlength: "80", placeholder: `گزینه ${options.children.length + 1}`, value });
    options.appendChild(input);
  };
  addOption(); addOption();
  const body = el("div", { class: "stack" },
    el("label", { class: "field" }, el("span", { text: "سؤال" }), question), options,
    btn("افزودن گزینه", "plus", "btn btn-sm", { onclick: () => addOption() }));
  const dlg = modal({ title: "ساخت نظرسنجی", body, actions: [
    btn("ارسال نظرسنجی", "send", "btn btn-primary", { onclick: () => {
      const q = question.value.trim(), values = Array.from(options.querySelectorAll("input")).map((x) => x.value.trim()).filter(Boolean);
      if (q.length < 2 || values.length < 2) return toast("سؤال و حداقل دو گزینه لازم است.", "error");
      chatSend({ t: "msg", kind: "poll", poll: { question: q, options: values } }); dlg.close();
    } }),
    btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
  ] });
  question.focus();
}


Pages.chat = async (root, options = {}) => {
  const info = options.info || await invoke("chat_info");
  // پوسته‌ی هابِ اجتماعی در موبایل نسخه‌ی خودش را دارد؛ این‌جا مستقیم روی root می‌نشینیم.
  const hubRoot = root;
  { const ad = adCard("chat_tab"); if (ad) hubRoot.appendChild(ad); }
  if (!info || !info.logged_in) {
    hubRoot.appendChild(el("div", { class: "card" }, secTitle("چت همگانی", "messageCircle"),
      el("p", { class: "muted", text: "برای چت با بقیه‌ی کاربرها اول وارد حساب لانچر شو (ثبت‌نام یا ورود)." })));
    hubRoot.appendChild(launcherAccountCard());
    return;
  }
  // اگر اتصالِ قبلی با حساب/توکنِ دیگری باز مانده، ببندش تا چت‌های قدیمی با پروفایلِ قبلی نمانند
  const tokenChanged = !!(Chat._wsToken && Chat._wsToken !== info.token);
  if (tokenChanged) chatTeardown();
  Chat.info = info; Chat._wsToken = info.token; Chat._alive = true;
  if (tokenChanged || !Chat.ws) { Chat._everConnected = false; Chat._authFail = 0; }
  if (tokenChanged) {
    Chat.username = null; Chat.avatar = null;
    Chat.groups = []; Chat.currentChannel = 0; Chat.currentGroup = null;
    Chat.msgs = []; Chat.seenIds = new Set(); Chat.oldestId = null; Chat.noMoreHistory = false;
  }

  // صفحه‌ی چت ارتفاعِ کامل می‌گیرد تا لیست اسکرول بخورد و فرم پایین بچسبد.
  hubRoot.style.display = "flex"; hubRoot.style.flexDirection = "column";
  const page = el("div", { class: "chat-page" });
  const main = el("div", { class: "gc-main" });

  // هدر: عنوان + شمارشِ آنلاین
  const dot = el("span", { class: "gc-dot" }); Chat.dotEl = dot;
  const onlineEl = el("span", { class: "gc-online", text: chatStatusText() }); Chat.onlineEl = onlineEl;
  const titleEl = el("div", { class: "gc-title", text: "گفتگوی زنده" });
  const subEl = el("div", { class: "gc-sub muted", text: "همه‌ی کاربرهای لانچر اینجا با هم گپ می‌زنند" });
  Chat.titleEl = titleEl; Chat.subEl = subEl;
  const manageBtn = btn(null, "settings", "btn btn-sm btn-icon", { title: "مدیریتِ گروه", style: "display:none",
    onclick: () => { const f = chatFindChannel(Chat.currentChannel); if (f) openGroupManageDialog(f.group); } });
  Chat.manageBtn = manageBtn;
  const head = el("div", { class: "gc-head card" },
    el("div", { class: "gc-head-l" },
      options.embedded ? btn(null, "arrowRight", "btn btn-sm btn-icon tg-channel-back", { title: "برگشت به گفتگوها", onclick: () => options.onBack && options.onBack() }) : null,
      el("span", { class: "sec-ico" }, icon("globe", 18)),
      el("div", {}, titleEl, subEl)),
    el("div", { class: "gc-head-r" }, manageBtn, dot, onlineEl));
  main.appendChild(head);
  const pinnedBar = el("div", { class: "gc-pinned-bar", style: "display:none" });
  Chat.pinnedBarEl = pinnedBar;
  main.appendChild(pinnedBar);
  const topicsBar = el("div", { class: "gc-topics-bar", style: "display:none" });
  Chat.topicsBarEl = topicsBar;
  main.appendChild(topicsBar);

  // لیستِ پیام‌ها
  const list = el("div", { class: "gc-list card" }); Chat.listEl = list;
  const jumpBtn = btn("آخرین پیام", "chevronDown", "btn btn-sm gc-jump", { title: "رفتن به آخرین پیام" });
  Chat.jumpEl = jumpBtn;
  jumpBtn.addEventListener("click", () => { list.scrollTop = list.scrollHeight; jumpBtn.classList.remove("show"); });
  list.appendChild(el("div", { class: "muted gc-empty", text: "در حال بارگذاری پیام‌ها…" }));
  // بارگذاریِ پیام‌های قدیمی‌تر با اسکرول به بالا
  list.addEventListener("scroll", () => {
    if (list.scrollTop < 40 && !Chat.loadingMore && Chat.oldestId && Chat.connected) {
      Chat.loadingMore = true; chatSend({ t: "history", before: Chat.oldestId });
    }
    const away = (list.scrollHeight - list.scrollTop - list.clientHeight) > 160;
    jumpBtn.classList.toggle("show", away);
  });
  main.appendChild(el("div", { class: "gc-chat-surface" }, list, jumpBtn));

  // فرمِ ارسال (+ نوارِ ریپلای بالای آن)
  const input = el("textarea", { class: "input gc-input", placeholder: "پیامت را بنویس…  (Enter برای ارسال، Shift+Enter برای خط جدید)", maxlength: "300", rows: "1" });
  Chat.inputEl = input;
  const counter = el("span", { class: "gc-char-count", text: "0 / 300" });
  const syncComposer = () => {
    input.style.height = "auto";
    input.style.height = Math.min(116, Math.max(42, input.scrollHeight)) + "px";
    counter.textContent = `${input.value.length} / 300`;
    counter.classList.toggle("near", input.value.length > 260);
  };
  input.addEventListener("input", syncComposer);
  const replyBar = el("div", { class: "gc-reply-bar", style: "display:none" }); Chat.replyBarEl = replyBar;
  const sendBtn = btn(null, "send", "btn btn-primary btn-icon");
  const doSend = () => {
    let t = input.value.trim();
    if (!t) return;
    if (!Chat.connected) return toast("هنوز به سرور چت وصل نشدی — کمی صبر کن.", "error");
    if (t.length > 300) t = t.slice(0, 300);
    // ضدِ اسپم: حداقل ۱.۵ ثانیه فاصله بینِ پیام‌ها
    const now = Date.now();
    if (Chat._lastSend && now - Chat._lastSend < 1500) {
      return toast("یواش‌تر! بینِ پیام‌ها کمی صبر کن.", "error");
    }
    Chat._lastSend = now;
    const payload = { t: "msg", text: t };
    if (Chat.replyTo && Chat.replyTo.id) payload.reply_to = Chat.replyTo.id;
    chatSend(payload);
    input.value = ""; syncComposer(); clearChatReply(); input.focus();
  };
  sendBtn.addEventListener("click", doSend);
  input.addEventListener("keydown", (e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); doSend(); } });
  const recBtn = btn(null, "mic", "btn btn-icon", { title: "پیام صوتی — برای شروع بزن" });
  let recorder = null, recChunks = [], recStarted = 0, recTimer = null;
  const resetRecorder = () => {
    recBtn.classList.remove("btn-danger"); recBtn.innerHTML = ""; recBtn.appendChild(icon("mic", 18));
    recBtn.title = "پیام صوتی — برای شروع بزن";
  };
  const stopVoice = async () => {
    const current = recorder; if (!current) return; recorder = null;
    if (recTimer) { clearInterval(recTimer); recTimer = null; }
    resetRecorder();
    await new Promise((resolve) => { current.onstop = resolve; try { current.stop(); } catch (_) { resolve(); } });
    try { current._stream && current._stream.getTracks().forEach((t) => t.stop()); } catch (_) {}
    const duration = Math.max(1, Math.round((Date.now() - recStarted) / 1000));
    if (!recChunks.length) return;
    const blob = new Blob(recChunks, { type: recChunks[0].type || "audio/webm" });
    if (blob.size < 200 || blob.size > 6 * 1024 * 1024) return toast("حجم پیام صوتی نامعتبر است.", "error");
    try {
      toast("در حال ارسال پیام صوتی…", "info");
      const data = await blobToDataUrl(blob);
      const uploaded = await invoke("chat_upload", { data, kind: "voice", name: "voice.webm" });
      const payload = { t: "msg", kind: "voice", media: uploaded.url, media_size: uploaded.size || blob.size, duration };
      if (Chat.replyTo && Chat.replyTo.id) payload.reply_to = Chat.replyTo.id;
      chatSend(payload); clearChatReply();
    } catch (e) { toast("ارسال پیام صوتی ناموفق بود: " + e, "error"); }
  };
  recBtn.addEventListener("click", async () => {
    if (!chatCanPost()) return toast("در کانال فقط مدیران می‌توانند پیام صوتی بفرستند.", "error");
    if (recorder) return stopVoice();
    if (typeof MediaRecorder === "undefined") return toast("ضبط صدا پشتیبانی نمی‌شود.", "error");
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      recChunks = []; recStarted = Date.now();
      const mr = new MediaRecorder(stream); recorder = mr; mr._stream = stream;
      mr.ondataavailable = (e) => { if (e.data && e.data.size) recChunks.push(e.data); };
      mr.start(); recBtn.classList.add("btn-danger"); recBtn.innerHTML = ""; recBtn.appendChild(icon("square", 16));
      recTimer = setInterval(() => { const sec = Math.round((Date.now() - recStarted) / 1000); recBtn.title = `در حال ضبط ${sec}s — برای ارسال بزن`; if (sec >= 120) stopVoice(); }, 500);
      toast("ضبط شروع شد؛ دوباره روی میکروفون بزن تا ارسال شود.", "info");
    } catch (e) { toast("دسترسی به میکروفون داده نشد: " + e, "error"); }
  });
  onPageLeave(() => {
    if (recorder) { try { recorder._stream && recorder._stream.getTracks().forEach((t) => t.stop()); recorder.stop(); } catch (_) {} recorder = null; }
    if (recTimer) clearInterval(recTimer);
  });
  const readonlyEl = el("div", { class: "gc-readonly", style: "display:none" }, icon("megaphone", 16), el("span", { text: "فقط مدیران این کانال می‌توانند پیام منتشر کنند" }));
  const attachBtn = btn(null, "paperclip", "btn btn-icon gc-tool", { title: "ارسال عکس، ویدیو یا فایل", onclick: () => chatPickAndUpload(input) });
  const gifBtn = el("button", { class: "btn btn-icon gc-tool gc-gif-trigger", type: "button", title: "ارسال GIF", text: "GIF", onclick: () => openGifPicker("gif") });
  const stickerBtn = el("button", { class: "btn btn-icon gc-tool gc-sticker-trigger", type: "button", title: "ارسال استیکر", text: "🗯", onclick: () => openGifPicker("sticker") });
  const emojiBtn = el("button", { class: "btn btn-icon gc-tool gc-emoji-trigger", type: "button", title: "ایموجی", text: "☺", onclick: () => chatEmojiDialog(input) });
  const pollBtn = btn(null, "list", "btn btn-icon gc-tool", { title: "ساخت نظرسنجی", onclick: chatPollDialog });
  // گیف/استیکر/ایموجی موقتاً از نوارِ ابزار برداشته شده‌اند (STICKERS_ENABLED).
  // خودِ دکمه‌ها بالا ساخته می‌شوند و دست‌نخورده‌اند؛ فقط به نوار اضافه نمی‌شوند.
  const stickerTools = STICKERS_ENABLED ? [gifBtn, stickerBtn, emojiBtn] : [];
  Chat.readonlyEl = readonlyEl;
  Chat.composerButtons = [recBtn, attachBtn, ...stickerTools, pollBtn, sendBtn];
  const tools = el("div", { class: "gc-composer-tools" }, attachBtn, ...stickerTools, pollBtn, recBtn);
  const composeRow = el("div", { class: "gc-compose-row" }, input,
    el("div", { class: "gc-compose-side" }, counter, sendBtn));
  main.appendChild(el("div", { class: "gc-form-wrap" }, replyBar, readonlyEl,
    el("div", { class: "gc-form gc-composer card" }, tools, composeRow)));
  syncComposer();
  chatRefreshComposer();

  // سایدبار: چتِ همگانی + گروه/کانال‌ها (renderChatSidebar پرش می‌کند).
  const sidebar = options.embedded ? null : el("div", { class: "gc-sidebar" });
  Chat.sidebarEl = sidebar;
  if (sidebar) {
    page.classList.add("has-sidebar");
    renderChatSidebar();
    page.appendChild(el("div", { class: "gc-shell" }, sidebar, main));
  } else {
    page.classList.add("is-embedded");
    page.appendChild(el("div", { class: "gc-shell" }, main));
  }
  hubRoot.appendChild(page);
  Chat.container = page;
  chatUpdateChannelHeader();
  renderTopicsBar();
  if (Chat.currentChannel && Chat.connected) chatSend({ t: "list_topics", channel: Chat.currentChannel });
  onPageLeave(chatDetachUi);

  // اتصال در پس‌زمینه. وقتی history (حتی خالی) برسد، chatOnHistory لیست را بازبنا می‌کند
  // و placeholder حذف می‌شود؛ اگر history خالی بود، پیامِ «اولین نفر باش» نشان می‌دهیم.
  chatConnect();
  if (Chat.msgs.length) chatOnHistory({ channel: Chat.currentChannel, messages: Chat.msgs }, false);
  setTimeout(() => {
    if (!Chat._alive || !Chat.listEl) return;
    if (!Chat.msgs.length) Chat.listEl.innerHTML =
      `<div class="muted gc-empty">${Chat.connected ? "هنوز پیامی نیست — اولین نفر باش!" : "در حال اتصال به سرور چت…"}</div>`;
  }, 1800);
};


// ── حمایتِ مالی (درگاهِ زیبال) ───────────────────────────────
const SUPPORT_PRESETS = [20000, 50000, 100000, 200000, 500000]; // تومان
const faNum = (n) => Number(n || 0).toLocaleString("fa-IR");
// ارقامِ فارسی/انگلیسی را برای پارس به انگلیسی تبدیل می‌کند (ورودیِ مبلغ را فارسی نشان می‌دهیم).
const toEn = (s) => String(s == null ? "" : s).replace(/[۰-۹]/g, (d) => "۰۱۲۳۴۵۶۷۸۹".indexOf(d)).replace(/[^0-9]/g, "");

// هدرِ «حمایت از میهن‌کرفت» در بالای خانه + دکمه‌ای که دیالوگِ انتخابِ مبلغ را باز می‌کند.
function supportBanner() {
  const b = el("div", { class: "support-banner" });
  b.appendChild(el("div", { class: "support-banner-ico" }, icon("heart", 22)));
  const txt = el("div", { class: "support-banner-txt" });
  txt.appendChild(el("div", { class: "support-banner-title", text: "از میهن‌کرفت حمایت کن 💙" }));
  txt.appendChild(el("div", { class: "support-banner-sub", text: "اگر دوست داشتی می‌تونی در هزینه‌های میهن‌کرفت ما رو حمایت کنی. هر مبلغی کمکِ بزرگیه!" }));
  b.appendChild(txt);
  b.appendChild(btn("حمایت", "heart", "btn btn-primary support-banner-btn", { onclick: () => openSupportDialog() }));
  return b;
}

function openSupportDialog() {
  const loggedIn = !!(State.cfg && State.cfg.account_token && State.cfg.account_token.length);
  if (!loggedIn) {
    toast("برای حمایت اول وارد حساب لانچر شو", "error");
    try { openAccountAuth("login"); } catch (_) {}
    return;
  }
  const uname = (State.cfg && State.cfg.account_username) || "";

  const body = el("div", { class: "support-dlg" });
  body.appendChild(el("p", { class: "muted", style: "line-height:2;margin:0 0 14px",
    text: "مبلغی که می‌خوای حمایت کنی رو انتخاب کن (به تومان). پرداخت از طریقِ درگاهِ امنِ زیبال در مرورگر انجام می‌شه و نامت به‌عنوانِ حامی ثبت می‌شه." }));

  let amount = SUPPORT_PRESETS[2]; // پیش‌فرض ۱۰۰٬۰۰۰ تومان
  const chipsWrap = el("div", { class: "support-chips" });
  const custom = el("input", { type: "text", inputmode: "numeric", dir: "rtl", class: "support-amount-input",
    placeholder: "مبلغِ دلخواه (تومان)", value: faNum(amount) });
  const chips = [];
  const syncChips = () => chips.forEach((c) => c.classList.toggle("active", Number(c.dataset.v) === amount));
  SUPPORT_PRESETS.forEach((v) => {
    const c = el("button", { class: "support-chip", "data-v": String(v) }, el("span", { text: faNum(v) + " تومان" }));
    c.addEventListener("click", () => { amount = v; custom.value = faNum(v); syncChips(); });
    chips.push(c); chipsWrap.appendChild(c);
  });
  body.appendChild(chipsWrap);
  custom.addEventListener("input", () => {
    amount = Math.max(0, parseInt(toEn(custom.value), 10) || 0);
    custom.value = amount ? faNum(amount) : ""; // نمایشِ زندهٔ فارسی
    syncChips();
  });
  body.appendChild(el("label", { class: "support-amount-row" },
    el("span", { class: "muted", text: "مبلغِ دلخواه:" }), custom));
  syncChips();

  // چک‌باکسِ نمایشِ نام در دیوارِ حامیان — پیش‌فرض تیک‌خورده؛ اگر برداشته شود در لیستِ اسکرولی نشان داده نمی‌شود.
  const showNameInput = el("input", { type: "checkbox" });
  showNameInput.checked = true;
  body.appendChild(el("label", { style: "display:flex;align-items:center;gap:8px;margin:2px 0 12px;cursor:pointer;font-size:13px" },
    showNameInput, el("span", { class: "muted", text: "نامم در دیوارِ حامیان نمایش داده شود" })));

  // ناحیه‌ی وضعیت (در حالِ انتظار / موفق / ناموفق) — ابتدا مخفی.
  const statusBox = el("div", { class: "support-status", style: "display:none" });
  body.appendChild(statusBox);

  // دیوارِ حامیان — مارکیِ راست‌به‌چپِ لوپ‌شونده از ۱۰ حامیِ آخر (بدونِ نمایشِ مجموع)
  const wall = el("div", { class: "support-wall" });
  wall.appendChild(el("div", { class: "support-wall-title", text: "حامیانِ میهن‌کرفت" }));
  const marquee = el("div", { class: "support-marquee" });
  const track = el("div", { class: "support-marquee-track" });
  marquee.appendChild(track);
  wall.appendChild(marquee);
  body.appendChild(wall);

  const buildItem = (s) => {
    const item = el("div", { class: "support-marquee-item" });
    item.appendChild(avatarEl(s.username, isMe(s.username) ? State.myAvatar : null, 24));
    item.appendChild(el("span", { class: "support-wall-name", text: s.username }));
    item.appendChild(el("span", { class: "support-wall-amt", text: faNum(s.amount) + " تومان" }));
    return item;
  };
  const loadWall = async () => {
    let res;
    try { res = await invoke("support_list"); } catch (_) { return; }
    // «۱۰ نفرِ آخر» = جدیدترین حامیان (سرور recent می‌دهد؛ اگر نبود از supporters)
    const recent = ((res && res.recent) || (res && res.supporters) || []).slice(0, 10);
    track.innerHTML = "";
    if (!recent.length) {
      track.classList.add("empty");
      track.style.animation = "none";
      track.appendChild(el("div", { class: "muted", style: "font-size:13px;padding:6px", text: "هنوز حامی‌ای ثبت نشده — اولین نفر باش!" }));
      return;
    }
    track.classList.remove("empty");
    // دو نسخهٔ پشتِ‌سرِهم تا لوپ بی‌درز باشد
    recent.forEach((s) => track.appendChild(buildItem(s)));
    recent.forEach((s) => track.appendChild(buildItem(s)));
    const dur = Math.max(14, recent.length * 3.5);
    track.style.animation = `support-marquee-scroll ${dur}s linear infinite`;
  };
  loadWall();
  // به‌روزرسانیِ خودکار تا حامیانِ جدید بیایند؛ خودش وقتی دیالوگ بسته شد متوقف می‌شود.
  const wallTimer = setIntervalWhenVisible(() => {
    if (!document.body.contains(marquee)) { clearVisibleInterval(wallTimer); return; }
    loadWall();
  }, 20000);

  const payBtn = btn("حمایت و پرداخت", "heart", "btn btn-primary", { onclick: () => startPay() });
  const dlg = modal({
    title: "حمایت از میهن‌کرفت",
    body,
    actions: [payBtn, btn("بستن", null, "btn btn-ghost", { onclick: () => dlg.close() })],
  });

  let polling = false;
  async function startPay() {
    if (polling) return;
    const amt = parseInt(toEn(custom.value), 10) || amount;
    if (!(amt >= 5000)) { toast("حداقل مبلغِ حمایت ۵٬۰۰۰ تومان است", "error"); return; }
    if (amt > 999000) { toast("حداکثر مبلغِ حمایت ۹۹۹٬۰۰۰ تومان است", "error"); return; }
    payBtn.disabled = true;
    statusBox.style.display = "";
    statusBox.className = "support-status pending";
    statusBox.innerHTML = "";
    statusBox.appendChild(el("div", { class: "support-spinner" }));
    statusBox.appendChild(el("div", { text: "در حال بازکردنِ درگاهِ پرداخت..." }));
    let res;
    try {
      res = await invoke("support_create", { amount: amt, publicName: showNameInput.checked });
    } catch (e) {
      statusBox.className = "support-status fail";
      statusBox.innerHTML = "";
      statusBox.appendChild(el("div", { text: String(e || "خطا در ساختِ پرداخت") }));
      payBtn.disabled = false;
      return;
    }
    const trackId = res && res.trackId;
    statusBox.className = "support-status pending";
    statusBox.innerHTML = "";
    statusBox.appendChild(el("div", { class: "support-spinner" }));
    statusBox.appendChild(el("div", { html: "پرداخت را در <b>مرورگر</b> کامل کن، بعد به همین‌جا برگرد — نتیجه خودکار بررسی می‌شود." }));
    // اگر مرورگر باز نشد، لینک را دستی بده.
    if (res && res.url) {
      const a = el("a", { class: "support-link", href: res.url, target: "_blank", text: "اگر صفحه باز نشد، اینجا کلیک کن" });
      statusBox.appendChild(a);
    }
    // poll وضعیت تا ~۵ دقیقه
    polling = true;
    const started = Date.now();
    const tick = async () => {
      if (Date.now() - started > 5 * 60 * 1000) { polling = false; payBtn.disabled = false; return; }
      let s;
      try { s = await invoke("support_status", { trackId }); } catch (_) { setTimeout(tick, 3500); return; }
      const st = s && s.status;
      if (st === "paid") {
        polling = false;
        statusBox.className = "support-status ok";
        statusBox.innerHTML = "";
        statusBox.appendChild(el("div", { class: "support-check", text: "✓" }));
        statusBox.appendChild(el("div", { html: `ممنون ${uname ? "<b>" + uname + "</b> " : ""}عزیز! مبلغِ ${faNum((s && s.amount) || amt)} تومان دریافت شد. 💙` }));
        toast("پرداخت موفق بود — ممنون از حمایتت! 💙", "success");
        loadWall();
        return;
      }
      if (st === "failed") {
        polling = false;
        statusBox.className = "support-status fail";
        statusBox.innerHTML = "";
        statusBox.appendChild(el("div", { text: "پرداخت کامل نشد یا لغو شد. اگر مبلغی کم شده طیِ ۷۲ ساعت برمی‌گردد." }));
        payBtn.disabled = false;
        return;
      }
      setTimeout(tick, 3500);
    };
    setTimeout(tick, 3500);
  }
}

Pages.home = async (root) => {
  // صفحه‌ی خانه ستونی با ارتفاعِ معیّن تا «کنسولِ فعالیت» فضای پایین را پر کند و
  // با زیادشدنِ متن، خودش داخلش اسکرول بخورد (نه اینکه کِش بیاید و صفحه را بزرگ کند).
  // روی صفحه‌های کوتاه (موبایل) این طرح جواب نمی‌دهد: کارتِ خوش‌آمد+اخبار به‌تنهایی
  // تقریباً کلِ ارتفاع را می‌گیرد و برای کنسول تقریباً هیچ‌چیز نمی‌ماند. آنجا کل صفحه
  // را عادی اسکرول‌پذیر می‌کنیم و به کنسول یک ارتفاعِ ثابتِ قابلِ‌استفاده می‌دهیم.
  const shortViewport = window.matchMedia("(max-width: 820px)").matches;
  if (shortViewport) { root.style.display = "block"; }
  else { root.style.display = "flex"; root.style.flexDirection = "column"; root.style.height = "100%"; }
  const homeGen0 = activeGen;
  // تبِ خانه باید «فوری» بیاید: شِل را همگام (sync) با داده‌های کش‌شده بساز، بعد ۳ فراخوانیِ
  // IPC را موازی در پس‌زمینه بگیر و فقط بخش‌های وابسته (دراپ‌داونِ پروفایل + آمار) را آپدیت کن.
  let profiles = Array.isArray(State.profiles) ? State.profiles : [];
  let servers = Array.isArray(State.servers) ? State.servers : [];
  const acc = State.selected;
  const lastVer = State.cfg.selected_version || State.cfg.last_played || "";

  const hero = el("div", { class: "hero" });
  const h2 = el("h2", {}, el("span", { text: acc ? `سلام ${acc.username}!` : "به لانچر خوش آمدی!" }));
  hero.appendChild(h2);
  hero.appendChild(el("p", { class: "muted", text: acc ? "آماده‌ی پرتاب به دنیای ماینکرفت؟" : "برای شروع، یک حساب بساز و نسخه‌ات را از بخش پروفایل‌ها نصب کن." }));

  const launchRow = el("div", { class: "row", style: "margin-top:22px; gap:14px;" });

  // پروفایل‌محور: «ماینکرفت اصلی» حذف شده — هر نسخه یک پروفایل است و فقط از روی پروفایل اجرا می‌شود
  // (profiles بالاتر موازی گرفته شد)
  const profOptions = profiles.length
    ? profiles.map((p) => ({ value: p.id, label: p.name }))
    : [{ value: "", label: "هنوز پروفایلی نساخته‌ای" }];
  const curProf = (State.cfg.last_profile && profiles.some((p) => p.id === State.cfg.last_profile))
    ? State.cfg.last_profile : (profiles[0] ? profiles[0].id : "");
  if (curProf && curProf !== State.cfg.last_profile) setCfg("last_profile", curProf);
  const profSelect = dropdown({ options: profOptions, value: curProf, placeholder: "انتخاب پروفایل", maxWidth: "260px", onChange: (v) => setCfg("last_profile", v) });

  const playBtn = btn("اجرای بازی", "play", "btn btn-primary btn-lg");
  playBtn.addEventListener("click", () => {
    const pid = profSelect.getValue();
    if (!pid) { toast("از بخش پروفایل‌ها یک نسخه نصب کن", "error"); go("instances"); return; }
    launchProfile(playBtn, pid);
  });

  launchRow.appendChild(playBtn);
  launchRow.appendChild(profSelect);
  // account chip — opens the Minecraft account manager popup (add/select/rename/delete)
  const accBtn = btn(acc ? acc.username : "افزودن حساب", "user", "btn", { title: "مدیریت حساب‌های ماینکرفت", onclick: () => openAccountManager() });
  launchRow.appendChild(accBtn);
  hero.appendChild(launchRow);

  // اخبار و اطلاعیه‌ها — کارتِ کوچک، بالا کنارِ hero. برای اینکه «دیرتر از بقیه» نیاید،
  // آخرین خبرِ کش‌شده فوری (هم‌زمان با بقیه‌ی صفحه) رندر می‌شود و بعد در پس‌زمینه تازه می‌گردد.
  const homeGen = activeGen;
  const newsSide = el("div", { class: "news-side" });
  const newsWrap = el("div", { class: "news-wrap" });
  newsSide.appendChild(newsWrap);
  { const a = adCard("home_news"); if (a) newsSide.appendChild(a); }   // تبلیغِ کنارِ اخبار
  const newsSig = (it) => JSON.stringify([it.id, it.created_at, it.body, it.media]);
  let _newsCache = null;
  try { _newsCache = JSON.parse(localStorage.getItem("newsCache") || "null"); } catch (_) {}
  if (_newsCache && _newsCache.item) {
    newsWrap._sig = newsSig(_newsCache.item);
    newsWrap.appendChild(newsItemEl(_newsCache.item, _newsCache.base || socialBase()));
  } else if (!newsSide.querySelector(".ad-slot")) {
    newsSide.style.display = "none";   // نه خبری هست نه تبلیغی → جا اشغال نکن
  }
  root.appendChild(el("div", { class: "hero-row" }, hero, newsSide));

  // ── هیدراتاسیونِ پس‌زمینه: داده‌های واقعی را بگیر و فقط بخش‌های وابسته را آپدیت کن ──
  Promise.all([
    invoke("list_installed").catch(() => []),
    invoke("instance_list").catch(() => []),
    invoke("server_list").catch(() => []),
  ]).then(([installed, profs, srvs]) => {
    if (pageStale(homeGen0)) return;
    State.installed = installed; State.profiles = profs; State.servers = srvs;
    profiles = profs; servers = srvs;
    // دراپ‌داونِ پروفایل را با فهرستِ تازه به‌روز کن (اگر چیزی عوض شده)
    try {
      const opts = profs.length ? profs.map((p) => ({ value: p.id, label: p.name })) : [{ value: "", label: "هنوز پروفایلی نساخته‌ای" }];
      const cur = (State.cfg.last_profile && profs.some((p) => p.id === State.cfg.last_profile)) ? State.cfg.last_profile : (profs[0] ? profs[0].id : "");
      if (cur && cur !== State.cfg.last_profile) setCfg("last_profile", cur);
      if (profSelect && profSelect.setOptions) { profSelect.setOptions(opts); if (cur) profSelect.setValue(cur); }
    } catch (_) {}
  });

  const loadNews = async () => {
    let res;
    try { res = await invoke("news_list"); } catch (_) { return; }
    if (pageStale(homeGen)) return;
    const items = (res && res.news) || [];
    const base = socialBase();
    if (!items.length) { newsSide.style.display = "none"; try { localStorage.removeItem("newsCache"); } catch (_) {} return; }
    // فقط آخرین مطلبِ منتشرشده را نشان بده
    const latest = items.slice().sort((a, b) => (b.created_at - a.created_at) || (b.id - a.id))[0];
    try { localStorage.setItem("newsCache", JSON.stringify({ item: latest, base })); } catch (_) {}
    // اگر همان مطلبِ قبلی است، دوباره نساز تا پخشِ ویدیو/اسلایدشو قطع نشود
    const sig = newsSig(latest);
    if (newsWrap._sig === sig) { newsSide.style.display = ""; return; }
    newsWrap._sig = sig;
    newsWrap.innerHTML = "";
    newsWrap.appendChild(newsItemEl(latest, base));
    newsSide.style.display = "";
  };
  loadNews();
  const newsTimer = setIntervalWhenVisible(() => { if (!pageStale(homeGen)) loadNews(); }, 25000);
  onPageLeave(() => clearVisibleInterval(newsTimer));

  // install progress card (hidden until used)
  const prog = el("div", { class: "card", id: "homeProgress", style: "display:none" },
    el("div", { class: "row spread" }, el("span", { id: "homeProgLabel", class: "muted", text: "در حال نصب..." }), el("span", { id: "homeProgPct", class: "dim", text: "" })),
    el("div", { class: "progress", style: "margin-top:10px" }, el("div", { id: "homeProgBar" })));
  root.appendChild(prog);

  // activity console — روی دسکتاپ فضای خالیِ پایینِ صفحه را پر می‌کند؛ روی موبایل
  // (صفحه‌ی کوتاه، root=display:block) ارتفاعِ ثابتِ خودش را دارد و خودِ صفحه اسکرول می‌خورد.
  const conCard = el("div", { class: "card", style: shortViewport ? "" : "flex:1;display:flex;flex-direction:column;min-height:0" });
  conCard.appendChild(el("div", { class: "row spread", style: "margin-bottom:8px" }, secTitle("کنسول فعالیت", "terminal"),
    el("div", { class: "row", style: "gap:6px" },
      btn(null, "copy", "btn btn-sm btn-icon", { title: "کپی", onclick: () => { const c = $("#homeConsole"); if (c) { navigator.clipboard.writeText(c.innerText); toast("لاگ کپی شد", "success"); } } }),
      btn(null, "trash", "btn btn-sm btn-icon", { title: "پاک کردن", onclick: () => { activityLog.length = 0; const c = $("#homeConsole"); if (c) c.innerHTML = ""; } }))));
  conCard.querySelector(".section-title").style.margin = "0";
  const con = el("div", { class: "console", id: "homeConsole", style: shortViewport ? "height:240px" : "flex:1 1 0;min-height:0;height:auto" });
  activityLog.forEach((a) => con.appendChild(el("div", { class: a.type ? "log-" + a.type : "", text: a.line })));
  if (activityLog.length === 0) con.appendChild(el("div", { class: "dim", text: "فعالیت‌های لانچر اینجا نمایش داده می‌شوند..." }));
  conCard.appendChild(con);
  root.appendChild(conCard);
  con.scrollTop = con.scrollHeight;
};

// Pencil in home now opens the full account manager popup.
function editUsername() { openAccountManager(); }

// Popup menu to add / select / rename / delete Minecraft accounts — lives in Home
// (next to the version selector) instead of a separate nav page.
function openAccountManager() {
  const body = el("div", {});
  const dlg = modal({
    title: "حساب‌های ماینکرفت",
    body,
    actions: [],   // بستن از دکمه‌ی X بالای پنجره انجام می‌شود
  });
  async function rebuild() {
    body.innerHTML = "";
    // add row
    const addRow = el("div", { class: "row", style: "margin-bottom:14px" },
      btn("حساب آفلاین", "user", "btn", { onclick: () => addOfflineThen(reloadAndRebuild) }),
      btn("ورود با مایکروسافت", "key", "btn btn-primary", { onclick: () => addMicrosoftThen(reloadAndRebuild) }));
    body.appendChild(addRow);
    if (!State.accounts.length) {
      body.appendChild(el("div", { class: "empty" }, el("div", { class: "big" }, icon("user", 38)), el("div", { text: "هنوز حسابی نساخته‌ای" })));
      return;
    }
    // لیست را داخل یک کادرِ اسکرول‌دارِ مستقل بگذار تا خودِ پنجره دراز نشود و
    // اسکرول‌بار نازک و داخلِ کادر بماند (نه چسبیده به لبه‌ی گردِ پنجره).
    const list = el("div", { class: "acc-scroll" });
    body.appendChild(list);
    State.accounts.forEach((a) => {
      const isSel = State.selected && State.selected.uuid === a.uuid;
      const item = el("div", { class: "list-item" },
        accAvatarElFromSkin(a),
        el("div", { style: "flex:1" },
          el("div", { style: "font-weight:700", text: a.username }),
          el("div", { class: "dim", text: a.type === "microsoft" ? "مایکروسافت" : "آفلاین" })),
        isSel ? tag("فعال", "tag green", "check")
          : btn("انتخاب", null, "btn btn-sm", { onclick: async () => { await invoke("select_account", { uuid: a.uuid }); await reloadAndRebuild(); } }),
        btn(null, "palette", "btn btn-sm btn-icon", { title: "اسکینِ این حساب", onclick: () => openAccountSkin(a, reloadAndRebuild) }),
        a.type === "microsoft" ? el("span", {}) : btn(null, "pencil", "btn btn-sm btn-icon", { title: "تغییر نام", onclick: () => {
          promptInput("تغییر نام کاربری", "نام جدید (حداقل ۳ حرف)", async (v) => { await invoke("rename_account", { uuid: a.uuid, username: v }); await reloadAndRebuild(); toast("نام تغییر کرد", "success"); }, a.username);
        } }),
        btn(null, "trash", "btn btn-sm btn-icon danger", { title: "حذف", onclick: () => confirmDialog("حذف حساب", `«${a.username}» حذف شود؟`, async () => { await invoke("remove_account", { uuid: a.uuid }); await reloadAndRebuild(); }) }));
      list.appendChild(item);
    });
  }
  async function reloadAndRebuild() { await refreshConfig(); await rebuild(); if (activePage === "home") go("home"); }
  rebuild();
}

// اسکین و شنلِ مخصوصِ یک حسابِ ماینکرفت — جداگانه روی سرور ثبت می‌شوند و فقط برای همان
// حساب داخلِ بازی دیده می‌شوند. یکپارچه با ۲ تب (اسکین/شنل) که هرکدام «انتخاب از فایل»
// و بعدش لیست (گالری) دارد — قبلاً اسکین فقط فایل داشت (بدونِ گالری) و شنل دکمه‌ی جدا
// با مودالِ جدا بود؛ الان مثلِ بخشِ یکپارچه‌ی صفحه‌ی «حساب‌ها» یک‌دست شده.
function openAccountSkin(a, after) {
  let chosen = a.skin_data || "";
  const prev = el("canvas", { width: 96, height: 96, style: "image-rendering:pixelated;background:var(--panel-2);border-radius:12px" });
  const pctx = prev.getContext("2d"); pctx.imageSmoothingEnabled = false;
  const drawPrev = () => {
    pctx.clearRect(0, 0, 96, 96);
    if (!chosen) return;
    loadImg(chosen).then((img) => { pctx.imageSmoothingEnabled = false; pctx.drawImage(img, 8, 8, 8, 8, 0, 0, 96, 96); try { pctx.drawImage(img, 40, 8, 8, 8, 0, 0, 96, 96); } catch (_) {} }).catch(() => {});
  };
  drawPrev();
  const modelChk = el("input", { type: "checkbox" }); modelChk.checked = (a.skin_model === "slim");
  const fileBtn = btn("انتخابِ فایلِ اسکین", "upload", "btn btn-sm", { onclick: async () => {
    const f = await pickImageFile(); if (!f) return;
    try {
      const img = await loadImageFromFile(f);
      // قبلاً فقط دقیقاً ۶۴×۶۴/۶۴×۳۲ قبول می‌شد، یعنی مشترکِ طلایی روی گوشی هیچ‌وقت
      // نمی‌توانست اسکینِ HD بگذارد. حالا همان قاعده‌ی دسکتاپ: هر مضربِ معتبر مجاز است،
      // و بزرگ‌تر از ۱× فقط برای اشتراکِ طلایی.
      if (!hdGateOk(skinScaleOf(img.naturalWidth, img.naturalHeight), "اسکین")) return;
      const c = document.createElement("canvas"); c.width = img.naturalWidth; c.height = img.naturalHeight;
      const x = c.getContext("2d"); x.imageSmoothingEnabled = false; x.drawImage(img, 0, 0);
      chosen = c.toDataURL("image/png"); drawPrev();
    } catch (e) { toast("خطا: " + e, "error"); }
  } });
  const skinGallery = el("div", { class: "sk-pick-grid", style: "margin-top:8px;max-height:280px;overflow:auto" });
  skinGallery.appendChild(el("div", { class: "dim", style: "grid-column:1/-1;padding:10px", text: "در حال بارگذاری..." }));
  invokeCached("skin_gallery").then((res) => {
    skinGallery.innerHTML = "";
    const skins = (res && res.skins) || [];
    if (!skins.length) { skinGallery.appendChild(el("div", { class: "dim", style: "grid-column:1/-1;padding:10px", text: "هنوز اسکینی نیست." })); return; }
    const skinCells = [];
    skins.slice(0, 100).forEach((item) => {
      const cell = el("div", { class: "sk-pick-cell", style: "cursor:pointer;padding:6px;text-align:center" });
      const holder = el("div", { style: "width:92px;height:150px;margin:0 auto;display:flex;align-items:center;justify-content:center;background:linear-gradient(180deg,#20293a,#161d29);border-radius:10px;overflow:hidden" });
      cell.appendChild(holder);
      cell._render3d = () => { if (cell._done) return; cell._done = true; holder.appendChild(makeSkin3dThumb(item.data || item.url, item.model || "classic", "skin-thumb")); };
      cell.addEventListener("click", async () => { const img = await resolveSkinData(item.data || item.url); if (img) { chosen = img; drawPrev(); } });
      skinCells.push(cell);
      skinGallery.appendChild(cell);
    });
    if (skinCells.length) {
      if ("IntersectionObserver" in window) {
        const io = new IntersectionObserver((ents) => { ents.forEach((e) => { if (e.isIntersecting) { io.unobserve(e.target); if (e.target._render3d) e.target._render3d(); } }); }, { root: skinGallery, rootMargin: "200px" });
        skinCells.forEach((c) => io.observe(c));
      } else { skinCells.forEach((c) => { if (c._render3d) c._render3d(); }); }
    }
  }).catch(() => { skinGallery.innerHTML = ""; skinGallery.appendChild(el("div", { class: "dim", style: "grid-column:1/-1;padding:10px", text: "بارگذاریِ گالری ناموفق بود." })); });
  const skinTabBody = el("div", {},
    el("div", { class: "row", style: "gap:14px;align-items:flex-start;flex-wrap:wrap" }, prev,
      el("div", { style: "flex:1;min-width:170px" },
        el("label", { class: "row", style: "gap:8px" }, modelChk, el("span", { class: "muted", text: "مدلِ لاغر (Alex/slim)" })),
        el("div", { class: "row", style: "gap:8px;margin-top:10px;flex-wrap:wrap" }, fileBtn))),
    skinGallery);

  // ── شنلِ مخصوصِ همین حساب ──────────────────────────────────
  const oneAcc = [{ name: a.username, uuid: a.uuid }];
  let chosenCape = a.cape_url || "";
  const capePrev = el("canvas", { width: 60, height: 96, style: "image-rendering:pixelated;background:var(--panel-2);border-radius:10px" });
  if (chosenCape) loadImg(chosenCape).then((img) => drawCapeFront(capePrev, img, 6)).catch(() => {});
  const capeFileBtn = btn("انتخابِ فایلِ شنل", "upload", "btn btn-sm", { onclick: async () => {
    const f = await pickImageFile(); if (!f) return;
    try {
      const img = await loadImageFromFile(f);
      // این‌جا هیچ اعتبارسنجی‌ای نبود: هر تصویری با هر ابعادی قبول می‌شد و بعد یا سرور
      // ۴۰۳ می‌داد یا شنل کج رندر می‌شد. همان گیتِ دسکتاپ اعمال می‌شود.
      if (!hdGateOk(capeScaleOf(img.naturalWidth, img.naturalHeight), "شنل")) return;
      const c = document.createElement("canvas"); c.width = img.naturalWidth; c.height = img.naturalHeight;
      const x = c.getContext("2d"); x.imageSmoothingEnabled = false; x.drawImage(img, 0, 0);
      chosenCape = c.toDataURL("image/png");
      capePrev.getContext("2d").clearRect(0, 0, 60, 96);
      loadImg(chosenCape).then((im) => drawCapeFront(capePrev, im, 6)).catch(() => {});
    } catch (e) { toast("خطا: " + e, "error"); }
  } });
  const capeClear = btn(null, "trash", "btn btn-sm btn-icon danger", { title: "برداشتنِ شنلِ این حساب", onclick: async (e) => {
    const b = e.currentTarget; b.disabled = true;
    try { await invoke("cape_remove", { accounts: oneAcc }); chosenCape = ""; capePrev.getContext("2d").clearRect(0, 0, 60, 96); toast("شنلِ این حساب برداشته شد", "success"); }
    catch (err) { toast("خطا: " + err, "error"); }
    b.disabled = false;
  } });
  const capeGallery = el("div", { class: "cape-grid", style: "margin-top:8px;max-height:220px;overflow:auto" });
  capeGallery.appendChild(el("div", { class: "dim", style: "grid-column:1/-1;padding:10px", text: "در حال بارگذاری..." }));
  invokeCached("cape_gallery").then((res) => {
    capeGallery.innerHTML = "";
    const capes = (res && res.capes) || [];
    if (!capes.length) { capeGallery.appendChild(el("div", { class: "dim", style: "grid-column:1/-1;padding:10px", text: "هنوز شنلی نیست." })); return; }
    capes.slice(0, 100).forEach((item) => {
      const label = item.builtin ? item.name : (item.owner || item.name || "شنل");
      const thumb = el("canvas", { class: "cape-thumb", style: "image-rendering:pixelated" });
      loadImg(item.url).then((img) => drawCapeFront(thumb, img, 6)).catch(() => {});
      const cell = el("div", { class: "cape-cell", title: label }, thumb, el("div", { class: "cape-cell-name", text: label }));
      cell.addEventListener("click", () => {
        chosenCape = item.url;
        capePrev.getContext("2d").clearRect(0, 0, 60, 96);
        loadImg(item.url).then((img) => drawCapeFront(capePrev, img, 6)).catch(() => {});
      });
      capeGallery.appendChild(cell);
    });
  }).catch(() => { capeGallery.innerHTML = ""; capeGallery.appendChild(el("div", { class: "dim", style: "grid-column:1/-1;padding:10px", text: "بارگذاریِ گالری ناموفق بود." })); });
  const capeTabBody = el("div", {},
    el("div", { class: "row", style: "gap:14px;align-items:flex-start;flex-wrap:wrap" }, capePrev,
      el("div", { style: "flex:1;min-width:170px" },
        el("div", { class: "row", style: "gap:8px;margin-top:0;flex-wrap:wrap" }, capeFileBtn, capeClear))),
    capeGallery);

  // ── تب‌ها ──
  const tabSkin = el("div", { class: "seg-btn active", text: "اسکین" });
  const tabCape = el("div", { class: "seg-btn", text: "شنل" });
  const seg = el("div", { class: "seg", style: "margin-bottom:12px" }, tabSkin, tabCape);
  capeTabBody.style.display = "none";
  tabSkin.addEventListener("click", () => { tabSkin.classList.add("active"); tabCape.classList.remove("active"); skinTabBody.style.display = ""; capeTabBody.style.display = "none"; });
  tabCape.addEventListener("click", () => { tabCape.classList.add("active"); tabSkin.classList.remove("active"); capeTabBody.style.display = ""; skinTabBody.style.display = "none"; });

  const dlg = modal({
    title: `اسکین و شنلِ «${a.username}»`,
    body: el("div", {}, seg, skinTabBody, capeTabBody),
    actions: [
      btn("ثبت", "check", "btn btn-primary", { onclick: async (e) => {
        const b = e.currentTarget; const old = b.innerHTML; b.disabled = true; b.innerHTML = '<span class="spinner"></span>';
        try {
          if (chosen) await invoke("account_set_skin", { uuid: a.uuid, image: chosen, model: modelChk.checked ? "slim" : "classic" });
          if (chosenCape && chosenCape !== a.cape_url) await invoke("cape_select", { url: chosenCape, accounts: oneAcc });
          dlg.close(); if (after) await after(); toast("ثبت شد — داخلِ بازی دیده می‌شود", "success");
        } catch (err) { toast("ثبت ناموفق: " + err, "error"); b.disabled = false; b.innerHTML = old; }
      } }),
      btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
    ],
  });
}

// Variants of addOffline/addMicrosoft that run a callback instead of navigating.
function addOfflineThen(after) {
  const input = el("input", { class: "input", placeholder: "نام کاربری (حداقل ۳ حرف)" });
  const dlg = modal({
    title: "حساب آفلاین",
    body: el("label", { class: "field" }, el("span", { text: "نام کاربری" }), input),
    actions: [
      btn("ساخت", "check", "btn btn-primary", { onclick: async () => {
        const u = input.value.trim();
        const create = async () => { try { await invoke("add_offline_account", { username: u }); dlg.close(); await after(); toast("حساب ساخته شد", "success"); } catch (e) { toast(e, "error"); } };
        if (!/^[A-Za-z0-9_]{3,16}$/.test(u)) { confirmDialog("نام غیراستاندارد", `نام «${u}» با قانون نام کاربری ماینکرفت فرق دارد. باز هم ساخته شود؟`, create); return; }
        create();
      } }),
      btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
    ],
  });
  input.focus();
}
// Shared Microsoft sign-in. تنها یک مسیر: پنجره‌ی ورودِ خودکار روی صفحه‌ی رسمیِ
// مایکروسافت. Resolves with the account, rejects with an error string
// (or "لغو شد" if cancelled).
function msLogin() {
  return new Promise((resolve, reject) => {
    const body = el("div", {});
    const dlg = modal({ title: "ورود با مایکروسافت", body, actions: [] });
    // ── ورودِ درون‌برنامه‌ای — تنها روش (خودکار). نه لینکِ دستی، نه Azure. ──
    function showWindowError(msg) {
      const m = String(msg);
      body.innerHTML = "";
      const cancelled = m.includes("لغو");
      body.appendChild(el("p", { class: "dim", text: cancelled ? "ورود کامل نشد یا پنجره بسته شد." : "خطا در ورود: " + m }));
      body.appendChild(btn("تلاش دوباره", "refresh", "btn btn-primary", { style: "width:100%;margin-top:8px", onclick: startWindow }));
      body.appendChild(btn("انصراف", null, "btn btn-ghost", { style: "width:100%;margin-top:8px", onclick: () => { invoke("close_ms_window").catch(() => {}); dlg.close(); reject("لغو شد"); } }));
    }

    // پنجره‌ی in-app روی صفحه‌ی واقعیِ مایکروسافت باز می‌شود؛ بعد از ورود خودکار
    // برمی‌گردد. هیچ Client ID یا تنظیمِ Azure لازم نیست (فلوِ legacy).
    function startWindow() {
      body.innerHTML = "";
      body.appendChild(el("div", { class: "row", style: "justify-content:center;padding:6px" },
        el("span", { class: "spinner" }), el("span", { text: "  پنجره‌ی ورودِ مایکروسافت باز شد..." })));
      body.appendChild(el("p", { class: "muted", style: "margin-top:10px", text: "در پنجره‌ای که باز شد وارد حسابِ مایکروسافتت شو. بعد از ورود، خودکار برمی‌گردی و حساب اضافه می‌شود. (در ایران معمولاً به فیلترشکن نیاز است.)" }));
      const actions = el("div", { class: "row", style: "gap:8px;justify-content:center;margin-top:12px;flex-wrap:wrap" });
      const cancelBtn = el("button", { class: "btn btn-ghost btn-sm", text: "انصراف", onclick: () => { dlg.close(); reject("لغو شد"); } });
      actions.appendChild(cancelBtn);
      body.appendChild(actions);

      invoke("ms_login_window")
        .then((acc) => { dlg.close(); resolve(acc); })
        .catch((e) => showWindowError(e));
    }

    startWindow();
  });
}

async function addMicrosoftThen(after) {
  try {
    const acc = await msLogin();
    await after();
    try { ensureBackgroundChat(); } catch (_) {}   // بعد از ورود، سوکتِ چت را بالا بیاور
    toast("خوش آمدی " + acc.username + "!", "success");
  } catch (e) { if (e !== "لغو شد") toast("ورود ناموفق: " + e, "error"); }
}

async function launchProfile(btnEl, id) {
  if (!State.selected) { toast("اول یک حساب انتخاب کن", "error"); go("mcaccount"); return; }
  const old = btnEl.innerHTML;
  btnEl.disabled = true; btnEl.innerHTML = '<span class="spinner"></span> در حال اجرا...';
  setStatus("در حال اجرای پروفایل...");
  try { const pid = await invoke("instance_launch", { id }); toast("پروفایل اجرا شد! (pid " + pid + ")", "success"); setStatus("بازی در حال اجرا"); }
  catch (e) { toast("خطا: " + e, "error"); setStatus("آماده"); }
  finally { btnEl.disabled = false; btnEl.innerHTML = old; }
}

async function launchGame(btnEl, version) {
  if (!State.selected) { toast("اول یک حساب انتخاب کن (تب حساب کاربری)", "error"); go("mcaccount"); return; }
  if (!version) { toast("از بخش پروفایل‌ها یک نسخه نصب و انتخاب کن", "error"); go("instances"); return; }
  const old = btnEl.innerHTML;
  btnEl.disabled = true; btnEl.innerHTML = '<span class="spinner"></span> در حال اجرا...';
  setStatus("در حال اجرای بازی...");
  try {
    const pid = await invoke("launch_game", { versionId: version });
    toast("بازی اجرا شد! (pid " + pid + ")", "success");
    setStatus("بازی در حال اجرا");
  } catch (e) {
    toast("خطا: " + e, "error");
    setStatus("آماده");
  } finally {
    btnEl.disabled = false; btnEl.innerHTML = old;
  }
}

// ── Instances (Prism-style) ───────────────────────────────
const INSTANCE_ICONS = ["cube", "boxes", "package", "puzzle", "gift", "layers", "server", "globe"];

// ═══════════════════════════════════════════════════════════
//  کلاینت پی وی پی (MihanPvP) — کلاینت بدلاین‌مانندِ ۱.۸.۹ که همراهِ
//  لانچر باندل شده. بارِ اول روی یک پروفایلِ Forge 1.8.9 نصب می‌شود و
//  بعد فقط با یک دکمه‌ی «اجرا» بالا می‌آید.
// ═══════════════════════════════════════════════════════════
// وضعِ سراسری و ماندگارِ آماده‌سازیِ کلاینت — تا با سوییچِ تب نوارِ پیشرفت نپرد/ریست نشود.
let _pvpRunning = false;
let _pvpProgListener = null;   // یک لیسنرِ یک‌بارثبت‌شده روی توکنِ pvp-setup
State.pvpSetup = State.pvpSetup || { running: false, label: "", pct: null };
function _renderPvpProgress() {
  const wrap = document.getElementById("pvpProgWrap");
  if (!wrap) return;   // صفحه‌ی pvp mount نیست — state حفظ می‌شود تا بعداً نشان داده شود
  const bar = document.getElementById("pvpProgBar");
  const lbl = document.getElementById("pvpProgLabel");
  const s = State.pvpSetup;
  wrap.style.display = (s.running || s.pct === 100) ? "" : "none";
  if (lbl) lbl.textContent = s.label || "";
  if (bar) bar.style.width = (s.pct != null ? s.pct : 0) + "%";
}
async function ensurePvpProgressListener() {
  if (_pvpProgListener) return;
  try {
    _pvpProgListener = await listen("update://progress", (e) => {
      const p = e.payload; if (!p || p.token !== "pvp-setup") return;
      if (p.label != null) State.pvpSetup.label = p.label;
      if (p.pct != null) State.pvpSetup.pct = p.pct;
      _renderPvpProgress();
    });
  } catch (_) {}
}

async function setupAndLaunchPvp(statusEl, runBtn) {
  const setS = (t) => { if (statusEl) statusEl.textContent = t; };
  if (!State.selected) { toast("اول یک حساب ماینکرفت بساز یا انتخاب کن", "error"); openAccountManager(); return; }
  if (clientUpdateBlocks()) { setS("برای اجرا، اول کلاینت را آپدیت کن."); return; }   // آپدیتِ اجباریِ کلاینت
  if (_pvpRunning) { setS("آماده‌سازیِ کلاینت در جریان است..."); return; }   // جلوگیری از اجرای هم‌زمانِ دوباره
  _pvpRunning = true;
  State.pvpSetup = { running: true, label: "در حال آماده‌سازی کلاینت...", pct: 0 };
  await ensurePvpProgressListener();   // لیسنرِ سراسری تا پیشرفت با سوییچِ تب هم به‌روز بماند
  _renderPvpProgress();
  runBtn.disabled = true; runBtn.innerHTML = '<span class="spinner"></span> در حال آماده‌سازی...';
  setS("در حال آماده‌سازی کلاینت...");
  try {
    // بارِ اول، پکِ کلاینت و جاوا ۸ از CDN دانلود می‌شوند (با نوار پیشرفت)؛ دفعاتِ بعد فوری.
    const pid = await invoke("pvp_launch");
    State.clientPid = pid;                 // برای آمارِ «آنلاین در کلاینت» تا وقتی پروسه زنده است
    try { invoke("presence_ping", { kind: "client" }); } catch (_) {}
    toast("کلاینت پی وی پی اجرا شد! (pid " + pid + ")", "success");
    State.pvpSetup.label = "کلاینت پی وی پی در حال اجراست ✓"; State.pvpSetup.pct = 100;
    setS("کلاینت پی وی پی در حال اجراست ✓");
  } catch (e) {
    toast("خطا: " + e, "error"); setS("خطا: " + e); State.pvpSetup.label = "خطا: " + e;
  } finally {
    _pvpRunning = false; State.pvpSetup.running = false; _renderPvpProgress();
    // دکمه ممکن است بعد از سوییچِ تب detach شده باشد؛ فقط اگر هنوز در DOM است بازنشانی کن
    if (runBtn && runBtn.isConnected) { runBtn.disabled = false; runBtn.innerHTML = ""; runBtn.appendChild(icon("play", 16)); runBtn.appendChild(el("span", { text: "اجرای کلاینت پی وی پی" })); }
  }
}

Pages.pvp = async (root) => {
  const card = el("div", { class: "card" });
  card.appendChild(secTitle("کلاینت پی وی پی — میهن‌کرفت", "gamepad"));
  card.appendChild(el("p", { class: "muted", text: "کلاینت 1.8.9 اختصاصی میهن کرفت + اف پی اس بالا + 50 ماژول" }));

  const statusEl = el("div", { class: "dim", style: "min-height:20px;margin:10px 0" });
  const runBtn = btn("اجرای کلاینت پی وی پی", "play", "btn btn-primary btn-lg", { onclick: () => setupAndLaunchPvp(statusEl, runBtn) });
  card.appendChild(el("div", { class: "row", style: "gap:10px;margin-top:6px" }, runBtn));
  card.appendChild(statusEl);
  // نوارِ پیشرفتِ ماندگارِ دانلودِ کلاینت (با سوییچِ تب هم ادامه دارد و ریست نمی‌شود)
  card.appendChild(el("div", { id: "pvpProgWrap", style: "display:none;margin-top:12px" },
    el("div", { id: "pvpProgLabel", class: "muted", style: "margin-bottom:8px" }),
    el("div", { class: "progress" }, el("div", { id: "pvpProgBar" }))));
  root.appendChild(card);

  // اگر آماده‌سازی هنگامِ ورود به تب در جریان است، وضعِ زنده را بازتاب بده
  await ensurePvpProgressListener();
  _renderPvpProgress();
  if (State.pvpSetup && State.pvpSetup.running) {
    runBtn.disabled = true; runBtn.innerHTML = '<span class="spinner"></span> در حال آماده‌سازی...';
    statusEl.textContent = State.pvpSetup.label || "";
  }

  // اگر کلاینت همراهِ این نسخه‌ی لانچر باندل نشده، هشدار بده
  const ok = await invoke("pvp_available").catch(() => false);
  if (!ok && !(State.pvpSetup && State.pvpSetup.running)) {
    statusEl.textContent = "⚠ فایلِ کلاینت پی وی پی همراهِ این نسخه‌ی لانچر پیدا نشد.";
    runBtn.disabled = true;
  }
};

// ── نسخه‌ها ────────────────────────────────────────────────────────────────
// این صفحه روی اندروید نبود و go("versions") به «پروفایل‌ها» تغییرِ مسیر داده می‌شد، با این
// توجیه که «هر نسخه داخلِ یک پروفایل نصب می‌شود». آن ادعا نیمی از ماجرا بود: ساختِ پروفایل
// واقعاً نسخه را نصب می‌کند، ولی کاربر هیچ راهی نداشت ببیند چه نسخه‌هایی روی دستگاهش نصب
// شده‌اند یا یکی را پاک کند — و نسخه‌ها گیگابایت جا می‌گیرند. مرورگرِ نسخه‌ها هم نبود: تنها
// راهِ دیدنِ فهرست، بازکردنِ دیالوگِ «نصب نسخه» بود که یک دراپ‌داون است، نه فهرستی که بشود
// در آن گشت. حالا همان صفحه‌ی دسکتاپ این‌جاست، با این تفاوت‌ها برای گوشی:
//   • فهرست اسکرولِ داخلی ندارد (یک محورِ اسکرول برای کلِ صفحه — روی لمس، اسکرولِ تودرتو گیر می‌کند)
//   • هر نصب حتماً پروفایل می‌سازد، چون روی اندروید اجرای بازی فقط از راهِ پروفایل ممکن است
Pages.versions = async (root) => {
  { const _nb = netAdviceBanner(); if (_nb) root.appendChild(_nb); }
  root.appendChild(downloadSourceCard());

  // ── نصب‌شده‌ها ──
  const insCard = el("div", { class: "card" });
  insCard.appendChild(secTitle("نسخه‌های نصب‌شده", "package"));
  const insBox = el("div", {});
  insCard.appendChild(insBox);
  root.appendChild(insCard);

  let installed = [];
  async function loadInstalled() {
    insBox.innerHTML = "";
    insBox.appendChild(el("div", { class: "row", style: "justify-content:center;padding:16px" }, el("span", { class: "spinner" })));
    installed = await invoke("list_installed").catch(() => []);
    State.installed = installed;
    insBox.innerHTML = "";
    if (!installed.length) { insBox.appendChild(el("div", { class: "dim", text: "هنوز نسخه‌ای نصب نشده." })); return; }
    collapsibleList(insBox, installed.map((v) => el("div", { class: "list-item" },
      el("span", { class: "li-ico" }, icon(/optifine/i.test(v) ? "sparkles" : "package", 18)),
      el("span", { style: "flex:1;font-weight:600;min-width:0;overflow-wrap:anywhere", text: v }),
      btn(null, "trash", "btn btn-sm btn-icon danger", { title: "حذف", onclick: () => confirmDialog("حذف نسخه", `${v} حذف شود؟`, async () => {
        try { await invoke("delete_version", { versionId: v }); toast("حذف شد", "success"); loadInstalled(); }
        catch (e) { toast(String(e), "error"); }
      }) }))), 4);
  }

  // ── نصب نسخه‌ی جدید ──
  const avCard = el("div", { class: "card" });
  avCard.appendChild(secTitle("نصب نسخه‌ی جدید", "download"));

  let selLoader = "vanilla";
  const LOADERS = srcLoaders([["vanilla", "وانیلا", "cube"], ["fabric", "Fabric", "puzzle"], ["quilt", "Quilt", "puzzle"], ["forge", "Forge", "boxes"], ["neoforge", "NeoForge", "boxes"], ["optifine", "OptiFine", "sparkles"]]);
  const loaderChips = el("div", { class: "chips", style: "margin-bottom:12px" });
  const chipEls = {};
  LOADERS.forEach(([id, label, ic]) => {
    const c = el("div", { class: "chip chip-ic" + (id === selLoader ? " active" : "") }, icon(ic, 14), el("span", { text: label }));
    c.addEventListener("click", () => { if (selLoader === id) return; selLoader = id; Object.values(chipEls).forEach((x) => x.classList.remove("active")); c.classList.add("active"); loadVersions(); });
    chipEls[id] = c; loaderChips.appendChild(c);
  });
  avCard.appendChild(loaderChips);
  avCard.appendChild(el("p", { class: "dim", style: "margin:-4px 0 12px", text: "با انتخاب Fabric، Quilt، Forge یا NeoForge، نسخه‌ی پایه و لودر هر دو نصب می‌شوند. (Forge/NeoForge با نصب‌کننده‌ی رسمی نصب می‌شوند و کمی بیشتر طول می‌کشد.)" }));

  const filters = el("div", { class: "row", style: "margin-bottom:12px;flex-wrap:wrap;gap:10px" });
  const snap = el("input", { type: "checkbox" });
  filters.appendChild(el("label", { class: "row", style: "gap:6px" }, snap, el("span", { class: "muted", text: "نسخه‌های آزمایشی" })));
  const loadBtn = btn("بارگذاری لیست", "refresh", "btn btn-sm");
  filters.appendChild(loadBtn);
  avCard.appendChild(filters);
  // بدونِ max-height/overflow: روی لمس، یک لیستِ اسکرول‌شونده داخلِ صفحه‌ی اسکرول‌شونده یعنی
  // کاربر نمی‌تواند از وسطِ لیست صفحه را بالا/پایین ببرد.
  const listBox = el("div", {});
  avCard.appendChild(listBox);
  root.appendChild(avCard);

  const rowFor = (label, tagEl, installBtn, ic) => el("div", { class: "list-item" },
    ic ? el("span", { class: "li-ico" }, icon(ic, 18)) : null,
    el("span", { style: "flex:1;font-weight:600;min-width:0;overflow-wrap:anywhere", text: label }),
    tagEl, installBtn);

  async function loadVersions() {
    listBox.innerHTML = "";
    listBox.appendChild(el("div", { class: "row", style: "justify-content:center;padding:20px" }, el("span", { class: "spinner" })));
    if (usingIran()) await loadIranIndex();   // فیلترِ «فقط موجود روی سرورِ ایران»
    try {
      // آپتی‌فاین لودرِ Modrinth-وار نیست — نسخه‌ها از ایندکسِ خودمان (میررِ سرورِ ایران) می‌آیند.
      if (selLoader === "optifine") {
        let supported;
        try { supported = await invoke("optifine_versions"); }
        catch (e) { listBox.innerHTML = ""; listBox.appendChild(el("div", { class: "dim", text: "آپتی‌فاین در دسترس نیست: " + e })); return; }
        supported = supported.slice().sort((a, b) => cmpVer(b, a));   // جدیدترین اول
        listBox.innerHTML = "";
        listBox.appendChild(el("div", { class: "dim", style: "padding:6px 10px 10px", text: "آپتی‌فاین کاملاً آفلاین از سرورِ ایران نصب می‌شود — نیازی به اینترنتِ خارجی نیست." }));
        if (!supported.length) { listBox.appendChild(el("div", { class: "dim", style: "padding:14px", text: "آپتی‌فاین موجود نیست." })); return; }
        const frag = document.createDocumentFragment();
        supported.forEach((v) => frag.appendChild(rowFor(v, tag("OptiFine", "tag gray"),
          installBtnFor("lver:optifine:" + v, (e) => installLoaderVersion(v, "optifine", e.currentTarget)), "sparkles")));
        listBox.appendChild(frag);
        return;
      }
      // برای یک مادلودر، فقط نسخه‌هایی که آن لودر واقعاً پشتیبانی می‌کند
      if (selLoader !== "vanilla") {
        let supported = await invoke("loader_game_versions", { loader: selLoader, showSnapshots: snap.checked, showOld: true });
        supported = supported.filter((v) => iranHasVersion(selLoader, v));
        listBox.innerHTML = "";
        if (selLoader === "forge") listBox.appendChild(el("div", { class: "dim", style: "padding:6px 10px 10px", text: "فورج نسخه‌ی آزمایشی/اسنپ‌شات ندارد — همه‌ی نسخه‌های فورج پایدارند." }));
        else if (selLoader === "neoforge" && !snap.checked) listBox.appendChild(el("div", { class: "dim", style: "padding:6px 10px 10px", text: "برای دیدن نسخه‌های آزمایشی/جدیدِ نئوفورج تیک «نسخه‌های آزمایشی» را بزن." }));
        if (!supported.length) { listBox.appendChild(el("div", { class: "dim", style: "padding:14px", text: usingIran() ? "این لودر روی سرورِ ایران نسخه‌ای ندارد." : "نسخه‌ای برای این لودر پیدا نشد — اینترنت/فیلترشکن را بررسی کن." })); return; }
        const frag = document.createDocumentFragment();
        supported.slice(0, 300).forEach((v) => frag.appendChild(rowFor(v, tag(selLoader, "tag gray"),
          installBtnFor("lver:" + selLoader + ":" + v, (e) => installLoaderVersion(v, selLoader, e.currentTarget)))));
        listBox.appendChild(frag);
        return;
      }
      let all = await invoke("list_versions", { showSnapshots: snap.checked, showOld: true });
      all = all.filter((v) => iranHasVersion("vanilla", v.id));
      listBox.innerHTML = "";
      const frag = document.createDocumentFragment();
      all.slice(0, 300).forEach((v) => {
        const isIns = installed.includes(v.id);
        frag.appendChild(rowFor(v.id, tag(v.type, "tag gray"),
          isIns ? tag("نصب‌شده", "tag green", "check") : installBtnFor("ver:" + v.id, (e) => installVersion(v.id, e.currentTarget))));
      });
      listBox.appendChild(frag);
    } catch (e) { listBox.innerHTML = ""; listBox.appendChild(el("div", { class: "dim", text: "خطا: " + e })); }
  }
  loadBtn.addEventListener("click", loadVersions);
  // تیکِ «آزمایشی» هم لیستِ وانیلا و هم لیستِ لودرها را زنده فیلتر می‌کند؛ نسخه‌های قدیمی همیشه دیده می‌شوند
  snap.addEventListener("change", loadVersions);
  await loadInstalled();
  loadVersions();
};

// نصبِ نسخه‌ی وانیلا: همیشه هم نسخه را نصب می‌کند و هم پروفایلش را می‌سازد — روی اندروید
// اجرای بازی فقط از راهِ پروفایل ممکن است، پس نسخه‌ی بی‌پروفایل چیزی است که نمی‌شود اجرا کرد.
async function installVersion(id, btnEl) {
  const old = btnEl.innerHTML;
  const token = "dl-" + (++_dlSeq) + "-" + Date.now();
  // نوار پیشرفتِ هدر (به‌جای مودال) تا کاربر بتواند بین تب‌ها جابه‌جا شود
  Install.start("نصب نسخه " + id, token);
  _installingIds.add("ver:" + id);
  let unsub = null;
  try { unsub = await listen("download://status", (e) => { const p = e.payload; if (!p || p.token !== token) return; if (p.label != null) Install.label(p.label); if (p.pct != null) Install.pct(p.pct); }); } catch (_) {}
  btnEl.disabled = true; btnEl.innerHTML = '<span class="spinner"></span>';
  setStatus("نصب " + id + "...");
  try {
    await invoke("install_version", { versionId: id, makeProfile: true, token });
    setStatus("آماده");
    toast(`نسخه ${id} نصب و پروفایلش ساخته شد`, "success");
    refreshDownloadQuota().catch(() => {});
    go("instances");
  } catch (e) {
    setStatus("آماده");
    btnEl.disabled = false; btnEl.innerHTML = old;
    if (String(e).includes("لغو")) toast("دانلود لغو شد", "");
    else toast("خطا در نصب: " + e, "error");
  } finally {
    _installingIds.delete("ver:" + id);
    try { unsub && unsub(); } catch (_) {}
    Install.end();
  }
}

async function installLoaderVersion(mcVersion, loader, btnEl) {
  const makeProfile = true;   // هر نصب همیشه یک پروفایل می‌سازد
  const old = btnEl.innerHTML;
  const _k = "lver:" + loader + ":" + mcVersion;
  btnEl.disabled = true; btnEl.innerHTML = '<span class="spinner"></span>';
  _installingIds.add(_k);
  setStatus(`نصب ${loader} برای ${mcVersion}...`);
  try {
    if (loader === "forge" || loader === "neoforge") {
      // با نصب‌کننده‌ی رسمی: نوار پیشرفتِ زنده در هدر
      const cmd = loader === "forge" ? "install_forge" : "install_neoforge";
      const id = await installWithProgress(`نصب ${loader} برای ماینکرفت ${mcVersion}`, cmd, { mcVersion, makeProfile });
      setStatus("آماده");
      if (id === null) { btnEl.disabled = false; btnEl.innerHTML = old; return; } // لغو شد
      toast(`${loader} نصب و پروفایلش ساخته شد: ${id}`, "success");
      go("instances");
      return;
    }
    if (loader === "optifine") {
      const id = await installWithProgress(`نصب OptiFine برای ماینکرفت ${mcVersion}`, "install_optifine", { mcVersion, makeProfile });
      setStatus("آماده");
      if (id === null) { btnEl.disabled = false; btnEl.innerHTML = old; return; } // لغو شد
      toast(`OptiFine نصب و پروفایلش ساخته شد: ${id}`, "success");
      go("instances");
      return;
    }
    Install.start(`نصب ${loader} برای ماینکرفت ${mcVersion}`);
    try {
      const loadersCmd = loader === "quilt" ? "quilt_loaders" : "fabric_loaders";
      const installCmd = loader === "quilt" ? "install_quilt" : "install_fabric";
      const loaders = await invoke(loadersCmd, { mcVersion });
      const lv = (loaders[0] && (loaders[0].loader?.version || loaders[0].version)) || "";
      if (!lv) throw new Error(`لودر ${loader} برای ${mcVersion} موجود نیست`);
      const id = await invoke(installCmd, { mcVersion, loaderVersion: lv, makeProfile });
      toast(`${loader} نصب و پروفایلش ساخته شد: ${id}`, "success");
      go("instances");
    } finally { Install.end(); }
  } catch (e) {
    toast("خطا در نصب لودر: " + e, "error");
    btnEl.disabled = false; btnEl.innerHTML = old;
  } finally { _installingIds.delete(_k); }
  setStatus("آماده");
}

Pages.instances = async (root) => {
  const head = el("div", { class: "card" });
  const ch = el("div", { class: "row spread" }, secTitle("پروفایل‌ها", "boxes"),
    btn("نصب نسخه", "download", "btn btn-primary btn-sm", { onclick: openCreateInstance }));
  ch.querySelector(".section-title").style.margin = "0";
  head.appendChild(ch);
  head.appendChild(el("p", { class: "muted", style: "margin-top:10px", text: "هر نسخه داخل یک پروفایل نصب می‌شود؛ لودر، نسخه، حافظه و تنظیماتش را همین‌جا انتخاب و مدیریت کن." }));
  root.appendChild(head);
  // منبعِ دانلود (ایران/خارج) — قبلاً فقط صفحه‌ی «نسخه‌ها» این تاگل را داشت و صفحه‌ی پروفایل‌ها
  // نداشت، پس ساختِ پروفایل به منبعِ ایران احترام نمی‌گذاشت. حالا این‌جا هم هست.
  root.appendChild(downloadSourceCard());

  // اگه یه نصب‌کننده‌ی بیرونی (مثلاً نصب‌کننده‌ی رسمیِ Fabric/OptiFine) مستقیم روی پوشه‌ی خودِ
  // لانچر نصب کرده باشه ولی از داخلِ لانچر نصب نکرده باشیم، پروفایلی براش نداریم — این‌ها رو پیدا
  // کن و پیشنهادِ ساختِ پروفایل بده.
  invoke("scan_orphaned_versions").then((orphans) => {
    if (!orphans || !orphans.length) return;
    const banner = el("div", { class: "card", style: "margin-bottom:14px;border:1px solid var(--accent-soft)" },
      el("div", { class: "row spread", style: "align-items:center" },
        el("div", { class: "row", style: "gap:8px;align-items:center" }, icon("info", 18),
          el("span", { text: `${faNum(orphans.length)} نسخه‌ی نصب‌شده بدونِ پروفایل پیدا شد (احتمالاً با یک نصب‌کننده‌ی بیرونی نصب شده).` })),
        btn("ساختِ پروفایل برای همه", "plus", "btn btn-sm btn-primary", { onclick: async (e) => {
          e.currentTarget.disabled = true; e.currentTarget.innerHTML = '<span class="spinner"></span>';
          for (const o of orphans) { try { await invoke("import_orphaned_version", { versionId: o.id, loader: o.loader }); } catch (_) {} }
          toast("پروفایل‌ها ساخته شدند", "success"); go("instances");
        } })));
    root.insertBefore(banner, root.children[1] || null);
  }).catch(() => {});

  const grid = el("div", { class: "inst-grid" });
  root.appendChild(grid);
  grid.appendChild(el("div", { class: "row", style: "justify-content:center;padding:24px;grid-column:1/-1" }, el("span", { class: "spinner" })));
  const list = await invoke("instance_list").catch(() => []);
  grid.innerHTML = "";
  if (list.length === 0) {
    grid.appendChild(el("div", { class: "empty", style: "grid-column:1/-1" }, el("div", { class: "big" }, icon("boxes", 42)), el("div", { text: "هنوز پروفایلی نساخته‌ای" }),
      el("div", { class: "dim", style: "margin-top:6px", text: "اولین نسخه را نصب کن؛ پروفایلش خودکار ساخته می‌شود." }),
      el("div", { style: "margin-top:14px" }, btn("نصب اولین نسخه", "download", "btn btn-primary", { onclick: openCreateInstance }))));
    return;
  }
  list.forEach((inst) => grid.appendChild(instanceCard(inst)));
};

// برچسبِ لودر برای نمایش. آپتی‌فاین روی اندروید روی پایه‌ی فورج نصب می‌شود (جارش داخلِ
// mods می‌رود)، پس loaderِ واقعی "forge" است و باید هم بماند — ولی نشان‌دادنِ «forge» به
// کسی که «OptiFine» را انتخاب کرده، شبیهِ نصبِ اشتباه به‌نظر می‌رسد و همان‌طور هم گزارش شد.
// polyfill پرچمِ optifine را از markerِ کنارِ version.json می‌آورد (ر.ک. instanceIsOptifine).
function loaderLabel(p) {
  if (!p) return "";
  if (p.optifine) return "OptiFine (روی Forge)";
  return p.loader === "vanilla" ? "وانیلا" : p.loader;
}
function instanceCard(inst) {
  const ic = INSTANCE_ICONS.includes(inst.icon) ? inst.icon : "cube";
  const card = el("div", { class: "card inst-card", onclick: () => openInstancePanel(inst) },
    el("div", { class: "inst-thumb" }, icon(ic, 30)),
    el("div", { class: "inst-name", text: inst.name }),
    el("div", { class: "inst-meta dim", text: `${loaderLabel(inst)} · ${inst.base_version || inst.version}` }),
    el("div", { class: "row inst-play", style: "gap:6px" },
      btn("اجرا", "play", "btn btn-sm btn-success", { style: "flex:1", onclick: (e) => { e.stopPropagation(); launchInstance(inst, e.currentTarget); } }),
      btn("مدیریت", "sliders", "btn btn-sm", { title: "ورود به فضای مدیریت پروفایل", onclick: (e) => { e.stopPropagation(); openInstancePanel(inst); } })));
  return card;
}

async function launchInstance(inst, btnEl) {
  if (!State.selected) { toast("اول یک حساب انتخاب کن", "error"); go("mcaccount"); return; }
  const old = btnEl.innerHTML; btnEl.disabled = true; btnEl.innerHTML = '<span class="spinner"></span>';
  setStatus("اجرای " + inst.name + "...");
  try { await invoke("instance_launch", { id: inst.id }); toast("پروفایل اجرا شد", "success"); setStatus("بازی در حال اجرا"); }
  catch (e) { toast("خطا: " + e, "error"); setStatus("آماده"); }
  btnEl.disabled = false; btnEl.innerHTML = old;
}

async function openCreateInstance() {
  const name = el("input", { class: "input", placeholder: "نام پروفایل" });
  let selLoader = "vanilla";
  const LOADERS = srcLoaders([["vanilla", "وانیلا", "cube"], ["fabric", "Fabric", "puzzle"], ["quilt", "Quilt", "puzzle"], ["forge", "Forge", "boxes"], ["neoforge", "NeoForge", "boxes"], ["optifine", "OptiFine", "sparkles"]]);
  const version = dropdown({ options: [{ value: "", label: "در حال بارگذاری..." }], placeholder: "نسخه" });
  // بارگذاری نسخه‌ها بر اساس لودرِ انتخابی: وانیلا → همه‌ی نسخه‌ها؛ Fabric/Quilt/Forge/NeoForge
  // → فقط نسخه‌هایی که آن لودر پشتیبانی می‌کند (مثل صفحه‌ی نسخه‌ها)
  async function loadVersionsForLoader() {
    version.setOptions([{ value: "", label: "در حال بارگذاری..." }]);
    if (usingIran()) await loadIranIndex();   // تا فیلترِ «فقط موجود روی سرورِ ایران» اعمال شود
    try {
      if (selLoader === "vanilla") {
        let vs = await invoke("list_versions", { showSnapshots: false, showOld: true });
        vs = vs.filter((v) => iranHasVersion("vanilla", v.id));
        version.setOptions(vs.slice(0, 300).map((v) => ({ value: v.id, label: v.id })));
        if (vs[0]) version.setValue(vs[0].id);
      } else if (selLoader === "optifine") {
        // آپتی‌فاین لودرِ Modrinth-وار نیست — لیستِ نسخه‌ها از ایندکسِ خودمان (سرورِ ایران) می‌آید،
        // نه loader_game_versions (که فقط fabric/quilt/forge/neoforge را می‌شناسد).
        let vs;
        try { vs = await invoke("optifine_versions"); } catch (_) { vs = []; }
        vs = vs.slice().sort((a, b) => cmpVer(b, a));
        if (!vs.length) { version.setOptions([{ value: "", label: "آپتی‌فاین در دسترس نیست" }]); return; }
        version.setOptions(vs.map((v) => ({ value: v, label: v })));
        version.setValue(vs[0]);
      } else {
        let vs = await invoke("loader_game_versions", { loader: selLoader, showSnapshots: false, showOld: true });
        vs = vs.filter((v) => iranHasVersion(selLoader, v));
        if (!vs.length) { version.setOptions([{ value: "", label: usingIran() ? "این لودر روی سرورِ ایران نسخه‌ای ندارد" : "نسخه‌ای برای این لودر پیدا نشد — اینترنت/فیلترشکن را بررسی کن" }]); return; }
        version.setOptions(vs.slice(0, 300).map((v) => ({ value: v, label: v })));
        version.setValue(vs[0]);
      }
    } catch { version.setOptions([{ value: "", label: "خطا در بارگذاری" }]); }
  }
  const chips = el("div", { class: "chips" }); const chipEls = {};
  LOADERS.forEach(([id, label, ico]) => { const c = el("div", { class: "chip chip-ic" + (id === selLoader ? " active" : "") }, icon(ico, 14), el("span", { text: label })); c.addEventListener("click", () => { if (selLoader === id) return; selLoader = id; Object.values(chipEls).forEach((x) => x.classList.remove("active")); c.classList.add("active"); loadVersionsForLoader(); }); chipEls[id] = c; chips.appendChild(c); });
  const ram = el("input", { class: "input", type: "number", min: "0", max: "65536", placeholder: "اختیاری (مثلاً 4096)" });
  let selIcon = "cube";
  const iconRow = el("div", { class: "icon-pick" }); const iconEls = {};
  INSTANCE_ICONS.forEach((ic) => { const b = el("div", { class: "icon-pick-item" + (ic === selIcon ? " active" : "") }, icon(ic, 18)); b.addEventListener("click", () => { selIcon = ic; Object.values(iconEls).forEach((x) => x.classList.remove("active")); b.classList.add("active"); }); iconEls[ic] = b; iconRow.appendChild(b); });

  const body = el("div", { class: "grid", style: "gap:14px" },
    el("label", { class: "field" }, el("span", { text: "نام" }), name),
    el("div", {}, el("span", { class: "field-lbl", text: "لودر" }), chips),
    el("div", { class: "grid grid-2" }, el("label", { class: "field" }, el("span", { text: "نسخه ماینکرفت" }), version), el("label", { class: "field" }, el("span", { text: "RAM (MB)" }), ram)),
    el("div", {}, el("span", { class: "field-lbl", text: "آیکن" }), iconRow));

  loadVersionsForLoader();

  const dlg = modal({
    title: "نصب نسخه در پروفایل جدید", body, actions: [
      btn("نصب نسخه", "download", "btn btn-primary", { onclick: async (e) => {
        if (!name.value.trim()) { toast("نام را وارد کن", "error"); return; }
        if (!version.getValue()) { toast("نسخه‌ای برای نصب انتخاب کن", "error"); return; }
        const b = e.currentTarget; b.disabled = true; b.innerHTML = '<span class="spinner"></span> در حال نصب نسخه...';
        try {
          const inst = await invoke("instance_create", { opts: { name: name.value.trim(), base_version: version.getValue(), loader: selLoader, icon: selIcon, ram: clampRam(ram.value) } });
          dlg.close(); toast("پروفایل ساخته شد", "success"); openInstancePanel(inst);
        } catch (err) { toast("خطا: " + err, "error"); b.disabled = false; b.innerHTML = ""; b.appendChild(icon("download", 16)); b.appendChild(el("span", { text: "نصب نسخه" })); }
      } }),
      btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
    ],
  });
  name.focus();
}

async function openInstancePanel(inst) {
  disposeServerPanel();
  activePage = "instances";
  updateNavigationState("instances");
  const titleEl = $("#pageTitle"); titleEl.innerHTML = "";
  titleEl.appendChild(btn(null, "arrowRight", "btn btn-sm btn-icon", { title: "بازگشت به کتابخانه", onclick: () => go("instances") }));
  titleEl.appendChild(el("span", { class: "pt-ico" }, icon("boxes", 20)));
  titleEl.appendChild(el("span", { text: inst.name }));
  const area = $("#pageArea"); area.innerHTML = ""; const wrap = el("div", { class: "fade-in srv-panel" }); area.appendChild(wrap);

  let meta = inst;
  const ic = INSTANCE_ICONS.includes(meta.icon) ? meta.icon : "cube";
  const head = el("div", { class: "srv-head card" },
    el("div", { class: "srv-head-ico" }, icon(ic, 24)),
    el("div", { style: "flex:1;min-width:0" },
      el("div", { style: "font-weight:700;font-size:16px", text: meta.name }),
      el("div", { class: "dim", style: "margin-top:4px", text: `${loaderLabel(meta)} · ${meta.base_version || meta.version}` })),
    el("div", { class: "row" }, btn("اجرا", "play", "btn btn-success", { onclick: (e) => launchInstance(meta, e.currentTarget) })));
  wrap.appendChild(head);

  const TABS = [["overview", "نمای کلی", "activity"], ["mods", "محتوا", "puzzle"], ["worlds", "دنیاها", "globe"], ["files", "فایل‌ها", "folder"], ["settings", "تنظیمات", "settings"], ["delete", "حذف", "trash"]];
  let curTab = "overview";
  let instKind = "mod"; // content tab: mod / shader / resourcepack
  const tabBar = el("div", { class: "srv-tabs" }); const bodyBox = el("div", { class: "srv-body" }); const tabBtns = {};
  TABS.forEach(([id, label, ico2]) => { const b = el("div", { class: "srv-tab" + (id === curTab ? " active" : ""), onclick: () => switchTab(id) }, icon(ico2, 16), el("span", { text: label })); tabBtns[id] = b; tabBar.appendChild(b); });
  wrap.appendChild(tabBar); wrap.appendChild(bodyBox);
  function switchTab(id) { curTab = id; Object.entries(tabBtns).forEach(([k, b]) => b.classList.toggle("active", k === id)); renderTab(); }
  function renderTab() {
    bodyBox.innerHTML = "";
    fileDropHandler = null; // only the files tab accepts OS drag-drop
    if (curTab === "overview") renderOverview();
    else if (curTab === "mods") renderInstMods();
    else if (curTab === "worlds") renderInstWorlds();
    else if (curTab === "files") renderFileManager(bodyBox, { instance: meta.id });
    else if (curTab === "delete") renderInstDelete();
    else renderInstSettings();
  }

  function renderOverview() {
    bodyBox.innerHTML = "";
    const card = el("div", { class: "card" });
    card.appendChild(secTitle("اطلاعات پروفایل", "activity"));
    const rows = [["نام", meta.name], ["لودر", loaderLabel(meta)], ["نسخه پایه", meta.base_version || "—"], ["نسخه اجرا", meta.version || "—"], ["RAM", meta.ram ? meta.ram + " MB" : "پیش‌فرض لانچر"], ["آخرین اجرا", meta.last_played ? fmtDate(meta.last_played) : "—"]];
    rows.forEach(([k, v]) => card.appendChild(el("div", { class: "row spread info-row" }, el("span", { class: "muted", text: k }), el("span", { class: "dim", text: String(v) }))));
    card.appendChild(el("div", { class: "row", style: "margin-top:16px;gap:10px" },
      btn("اجرای بازی", "play", "btn btn-success", { onclick: (e) => launchInstance(meta, e.currentTarget) }),
      // ⚠ روی اندروید فایل‌منیجرِ سیستمی در دسترس نیست و open_in_explorer همیشه رد می‌شود
      // («باز کردن پوشه در فایل‌منیجرِ سیستم روی موبایل پشتیبانی نمی‌شود» — گزارش ۵۴۶۰ که
      // کاربر هفت بار پشتِ‌هم زد تا دنیایش را وارد کند). خودِ همین پنل تبِ «فایل‌ها» را
      // دارد که آپلود و پوشه‌ی جدید هم دارد، پس دکمه به همان‌جا می‌برد.
      btn("فایل‌های پروفایل", "folderOpen", "btn", { onclick: () => switchTab("files") })));
    bodyBox.appendChild(card);
  }

  function renderInstMods() {
    bodyBox.innerHTML = "";
    // Vanilla profiles have no mod loader, so mods and shaders cannot load — only
    // resource packs work. Restrict the category list (and force the selection)
    // accordingly so the user isn't offered content that will never run.
    const isVanilla = meta.loader === "vanilla";
    const ALL_CK = [["mod", "ماد‌ها", "puzzle"], ["shader", "شیدرها", "zap"], ["resourcepack", "ریسورس‌پک‌ها", "gift"]];
    const CK = isVanilla ? ALL_CK.filter((c) => c[0] === "resourcepack") : ALL_CK;
    if (isVanilla && instKind !== "resourcepack") instKind = "resourcepack";
    const ic = (CK.find((c) => c[0] === instKind) || CK[0])[2];

    // category chips (mod / shader / resourcepack)
    const top = el("div", { class: "card" });
    const chips = el("div", { class: "chips" });
    CK.forEach(([id, label, ic2]) => {
      const c = el("div", { class: "chip chip-ic" + (id === instKind ? " active" : "") }, icon(ic2, 14), el("span", { text: label }));
      c.addEventListener("click", () => { if (instKind === id) return; instKind = id; renderInstMods(); });
      chips.appendChild(c);
    });
    top.appendChild(chips);
    if (isVanilla) top.appendChild(el("p", { class: "muted", style: "margin-top:10px;display:flex;align-items:center;gap:6px" }, icon("info", 13),
      el("span", { text: "این پروفایل وانیلا است و لودر (Fabric/Forge/…) ندارد؛ پس ماد و شیدر روی آن اجرا نمی‌شود — فقط ریسورس‌پک. برای نصب ماد یا شیدر یک پروفایل با لودر بساز." })));
    bodyBox.appendChild(top);

    // installed list (for the chosen kind, inside this profile)
    const insCard = el("div", { class: "card" });
    const h = el("div", { class: "row spread" }, secTitle("نصب‌شده‌ها", ic), btn(null, "refresh", "btn btn-sm btn-icon", { onclick: renderInstMods }));
    h.querySelector(".section-title").style.margin = "0"; insCard.appendChild(h);
    bodyBox.appendChild(insCard);
    invoke("content_installed", { kind: instKind, instance: meta.id }).then((installed) => {
      if (!installed || installed.length === 0) insCard.appendChild(el("div", { class: "dim", style: "margin-top:8px", text: "چیزی نصب نشده." }));
      else collapsibleList(insCard, installed.map((m) => el("div", { class: "list-item" },
        el("span", { class: "li-ico" }, icon(ic, 18)),
        el("div", { style: "flex:1" }, el("div", { style: "font-weight:600", text: m.name.replace(".disabled", "") }), el("div", { class: "dim", text: fmtBytes(m.size) })),
        m.enabled ? tag("فعال", "tag green") : tag("غیرفعال", "tag gray"),
        btn(m.enabled ? "غیرفعال" : "فعال", m.enabled ? "x" : "check", "btn btn-sm", { onclick: async () => { await invoke("mods_toggle", { path: m.path, enabled: !m.enabled }); renderInstMods(); } }),
        btn(null, "trash", "btn btn-sm btn-icon danger", { title: "حذف", onclick: () => confirmDialog("حذف", m.name + " حذف شود؟", async () => { await invoke("mods_delete", { path: m.path }); renderInstMods(); }) }))), 3);
    }).catch(() => {});

    // search + install from online (Modrinth) straight into this profile
    const sCard = el("div", { class: "card" });
    sCard.appendChild(secTitle("نصب از آنلاین (Modrinth)", "search"));
    const q = el("input", { class: "input", style: "flex:1", placeholder: "نام..." });
    const goBtn = btn("جستجو", "search", "btn btn-primary");
    sCard.appendChild(el("div", { class: "row" }, q, goBtn));
    const results = el("div", { class: "mod-grid", style: "margin-top:14px" }); sCard.appendChild(results);
    bodyBox.appendChild(sCard);
    const loaderFacet = instKind === "mod" ? (meta.loader === "vanilla" ? "" : meta.loader) : "";
    const mcFacet = instKind === "mod" ? profileMcVersion(meta) : "";
    const search = setupInfiniteSearch({
      resultsEl: results,
      getParams: () => ({ query: q.value, mcVersion: mcFacet, loader: loaderFacet, category: "", projectType: instKind }),
      cardFn: (hh) => {
        const cats = (hh.categories || []).map(c => c.toLowerCase());
        const loaders = ["fabric", "forge", "quilt", "neoforge"].filter(l => cats.includes(l));
        const loaderText = loaders.length ? `لودر: ${loaders.join(", ")}` : "";
        return el("div", { class: "card mod-card" },
          el("div", { class: "mc-top" }, el("img", { src: hh.icon_url || "", loading: "lazy", decoding: "async", onerror: "this.style.visibility='hidden'" }), el("div", { class: "mc-title", text: hh.title })),
          el("div", { class: "mc-desc", text: hh.description || "" }),
          loaderText ? el("div", { class: "dim", style: "font-size:11px;margin-top:2px", text: loaderText }) : null,
          el("div", { class: "row spread" }, el("span", { class: "dim dl-count" }, icon("download", 13), el("span", { text: (hh.downloads || 0).toLocaleString("fa-IR") })),
            (_installedProj.has(hh.project_id || hh.slug) ? Object.assign(btn("نصب شد", "check", "btn btn-sm"), { disabled: true }) : btn("نصب", "download", "btn btn-sm btn-primary", { onclick: async (e) => { const bb = e.currentTarget; const old = bb.innerHTML; bb.disabled = true; bb.innerHTML = '<span class="spinner"></span>'; try { const res = await installWithProgress("نصب " + (hh.title || ""), "content_install", { projectId: hh.project_id || hh.slug, mcVersion: mcFacet, loader: loaderFacet, kind: instKind, instance: meta.id }); if (res === null) { bb.disabled = false; bb.innerHTML = old; return; } toast("نصب شد", "success"); _installedProj.add(hh.project_id || hh.slug); bb.innerHTML = ""; bb.appendChild(icon("check", 14)); bb.appendChild(el("span", { text: "نصب شد" })); renderInstMods(); } catch (err) { toast("خطا: " + err, "error"); bb.disabled = false; bb.innerHTML = old; } } }))));
      },
    });
    goBtn.addEventListener("click", search.reset); q.addEventListener("keydown", (e) => { if (e.key === "Enter") search.reset(); });
    q.addEventListener("input", debounce(() => search.reset(), 350));
    search.reset();
  }

  async function renderInstWorlds() {
    bodyBox.innerHTML = "";
    const card = el("div", { class: "card" });
    const h = el("div", { class: "row spread" }, secTitle("دنیاهای این پروفایل", "globe"), btn(null, "refresh", "btn btn-sm btn-icon", { onclick: renderInstWorlds }));
    h.querySelector(".section-title").style.margin = "0"; card.appendChild(h);
    const grid = el("div", { class: "world-grid", style: "margin-top:14px" }); card.appendChild(grid); bodyBox.appendChild(card);
    grid.appendChild(el("div", { class: "row", style: "justify-content:center;padding:18px;grid-column:1/-1" }, el("span", { class: "spinner" })));
    const ws = await invoke("instance_worlds", { id: meta.id }).catch(() => []);
    grid.innerHTML = "";
    if (ws.length === 0) { grid.appendChild(el("div", { class: "dim", style: "grid-column:1/-1;padding:10px", text: "هنوز دنیایی در این پروفایل نیست." })); return; }
    ws.forEach((w) => grid.appendChild(worldCard(w)));
  }

  function renderInstSettings() {
    bodyBox.innerHTML = "";
    const card = el("div", { class: "card" });
    card.appendChild(secTitle("تنظیمات پروفایل", "settings"));
    const ramIn = el("input", { class: "input", type: "number", min: "0", max: "65536", value: meta.ram ? String(meta.ram) : "", placeholder: "پیش‌فرض لانچر", style: "max-width:220px" });
    card.appendChild(el("label", { class: "field" }, el("span", { text: "RAM اختصاصی (MB)" }), ramIn));
    card.appendChild(el("div", { class: "row", style: "margin-top:12px" }, btn("ذخیره", "check", "btn btn-sm", { onclick: async () => { meta = await invoke("instance_update", { id: meta.id, patch: { ram: clampRam(ramIn.value) } }); toast("ذخیره شد", "success"); } })));
    bodyBox.appendChild(card);
  }

  function renderInstDelete() {
    bodyBox.innerHTML = "";
    const danger = el("div", { class: "card danger-card" });
    danger.appendChild(secTitle("حذف پروفایل", "warn"));
    danger.appendChild(el("p", { class: "dim", text: "کل پروفایل شامل دنیاها، مادها و تنظیماتش برای همیشه حذف می‌شود. این کار قابل بازگشت نیست." }));
    danger.appendChild(btn("حذف کامل پروفایل", "trash", "btn btn-danger", { style: "margin-top:12px", onclick: () => confirmDialog("حذف پروفایل", `«${meta.name}» حذف شود؟`, async () => { await invoke("instance_delete", { id: meta.id }); toast("حذف شد", "success"); go("instances"); }) }));
    // ── اشتراک‌گذاری پروفایل ──
    danger.appendChild(el("hr", { style: "margin:16px 0;border-color:var(--border)" }));
    danger.appendChild(secTitle("اشتراک‌گذاری پروفایل", "share"));
    danger.appendChild(el("p", { class: "dim", text: "پروفایل را به‌عنوان فایل zip خروجی بگیر تا دوستانت بتوانند وارد کنند." }));
    danger.appendChild(btn("ذخیره به‌صورت zip", "download", "btn btn-sm", { style: "margin-top:8px", onclick: async () => {
      try {
        const path = await T.dialog.save({ defaultPath: `${meta.name || "profile"}.zip`, filters: [{ name: "Zip", extensions: ["zip"] }] });
        if (!path) return;
        await invoke("instance_export", { id: meta.id, dest: path });
        toast("پروفایل ذخیره شد: " + path, "success");
      } catch (e) { toast("خطا: " + e, "error"); }
    } }));
    danger.appendChild(btn("ورود از فایل zip", "upload", "btn btn-sm", { style: "margin-top:8px", onclick: async () => {
      try {
        const path = await T.dialog.open({ filters: [{ name: "Zip", extensions: ["zip"] }], multiple: false });
        if (!path) return;
        const p = await invoke("instance_import", { zipPath: Array.isArray(path) ? path[0] : path });
        if (p && p.repair_ok === false) {
          toast("پروفایل وارد شد ولی نصبِ نسخه/لودر کامل نشد — موقعِ اجرا لانچر دوباره تلاش می‌کند.", "error");
        } else {
          toast("پروفایل وارد شد!", "success");
        }
        go("instances");
      } catch (e) { toast("خطا: " + e, "error"); }
    } }));
    bodyBox.appendChild(danger);
  }

  renderTab();
}

// ── Profiles / Accounts ───────────────────────────────────
// ── حساب لانچر (ثبت‌نام/ورود — اختیاری) ──────────────────────
function launcherAccountCard() {
  const cfg = State.cfg || {};
  const loggedIn = !!(cfg.account_token && cfg.account_token.length);
  const card = el("div", { class: "card" });
  card.appendChild(secTitle("حساب لانچر", "key"));
  if (loggedIn) {
    const u = cfg.account_username || "؟";
    const avatarBox = el("div", { class: "avatar-slot", style: "width:46px;height:46px" }, letterAvatar(u, 46));
    const setAvatarPreview = (path) => {
      avatarBox.innerHTML = "";
      avatarBox.appendChild(path ? avatarEl(u, path, 46) : letterAvatar(u, 46));
    };
    // عکس فعلی را از سرور بگیر و نمایش بده
    invoke("social_profile").then((p) => { if (p && p.avatar) setAvatarPreview(p.avatar); }).catch(() => {});
    card.appendChild(el("div", { class: "list-item" },
      avatarBox,
      el("div", { style: "flex:1" },
        el("div", { style: "font-weight:700", text: u }),
        el("div", { class: "dim", text: "وارد شده‌ای" })),
      btn("تغییر آواتار", "image", "btn btn-sm", { onclick: () => openAvatarPicker(setAvatarPreview) }),
      btn("تغییر رمز", "key", "btn btn-sm", { onclick: () => openChangePassword() }),
      btn("خروج", "power", "btn btn-sm btn-danger", { onclick: async () => {
        await invoke("account_logout"); await refreshConfig();
        document.querySelectorAll(".modal-backdrop").forEach((m) => m.remove());
        try { renderAccountCard(); } catch (_) {}
        enforceAccountGate();   // بعد از خروج، تا دوباره وارد نشود اجازه‌ی استفاده نده
        toast("از حساب لانچر خارج شدی", "success");
      } })));
  } else {
    card.appendChild(el("p", { class: "dim", style: "margin:2px 0 12px",
      text: "با نام کاربری و رمز ثبت‌نام یا ورود کن؛ یک اکانت بازیِ آفلاین با همان نام هم خودکار ساخته می‌شود." }));
    card.appendChild(el("div", { class: "row" },
      btn("ورود", "key", "btn btn-primary", { onclick: () => openAccountAuth("login") }),
      btn("ثبت‌نام", "plus", "btn", { onclick: () => openAccountAuth("register") })));
  }
  return card;
}

// تغییر رمزِ حسابِ لانچر از داخلِ پنل
function openChangePassword() {
  const oldIn = el("input", { class: "input", type: "password", placeholder: "رمز فعلی", autocomplete: "current-password" });
  const newIn = el("input", { class: "input", type: "password", placeholder: "رمز جدید (حداقل ۶ کاراکتر)", autocomplete: "new-password" });
  const new2In = el("input", { class: "input", type: "password", placeholder: "تکرار رمز جدید", autocomplete: "new-password" });
  const errLine = el("div", { class: "dim", style: "min-height:18px;color:#e5484d" });
  const body = el("div", {},
    el("label", { class: "field" }, el("span", { text: "رمز فعلی" }), oldIn),
    el("label", { class: "field" }, el("span", { text: "رمز جدید" }), newIn),
    el("label", { class: "field" }, el("span", { text: "تکرار رمز جدید" }), new2In),
    errLine);
  const actBtn = btn("تغییر رمز", "check", "btn btn-primary");
  const submit = async () => {
    errLine.textContent = "";
    const o = oldIn.value, n = newIn.value, n2 = new2In.value;
    if (!o || !n) { errLine.textContent = "همه‌ی فیلدها را پر کن."; return; }
    if (n.length < 6) { errLine.textContent = "رمز جدید باید حداقل ۶ کاراکتر باشد."; return; }
    if (n !== n2) { errLine.textContent = "رمز جدید و تکرارش یکی نیستند."; return; }
    actBtn.disabled = true;
    try {
      await invoke("change_password", { oldPassword: o, newPassword: n });
      dlg.close(); toast("رمز با موفقیت تغییر کرد", "success");
    } catch (e) { errLine.textContent = String(e); actBtn.disabled = false; }
  };
  actBtn.addEventListener("click", submit);
  new2In.addEventListener("keydown", (e) => { if (e.key === "Enter") submit(); });
  const dlg = modal({ title: "تغییر رمز عبور", body, actions: [actBtn, btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() })] });
  oldIn.focus();
}

// حساب لانچر از «تنظیمات» جدا شد و به کارتِ پایینِ نوار کناری منتقل شد؛ دکمه‌ی مداد
// این پنجره را باز می‌کند: اگر وارد نشده‌ای مستقیم فرم ورود، وگرنه آواتار/خروج
function openLauncherAccount() {
  const cfg = State.cfg || {};
  const loggedIn = !!(cfg.account_token && cfg.account_token.length);
  if (!loggedIn) { openAccountAuth("login"); return; }
  const dlg = modal({
    title: "حساب لانچر",
    body: launcherAccountCard(),
    actions: [btn("بستن", null, "btn btn-ghost", { onclick: () => dlg.close() })],
  });
}

function openAccountAuth(mode) {
  const isReg = mode === "register";
  const uIn = el("input", { class: "input", placeholder: "نام کاربری (۳ تا ۱۶ حرف انگلیسی/عدد/_)", autocomplete: "username", maxlength: "16" });
  const pIn = el("input", { class: "input", type: "password", placeholder: "رمز عبور (حداقل ۶ کاراکتر)", autocomplete: isReg ? "new-password" : "current-password" });
  const p2In = isReg ? el("input", { class: "input", type: "password", placeholder: "تکرار رمز عبور", autocomplete: "new-password" }) : null;
  const errLine = el("div", { class: "dim", style: "min-height:18px;color:#e5484d" });
  const fields = [
    el("label", { class: "field" }, el("span", { text: "نام کاربری" }), uIn),
    el("label", { class: "field" }, el("span", { text: "رمز عبور" }), pIn),
  ];
  if (p2In) fields.push(el("label", { class: "field" }, el("span", { text: "تکرار رمز" }), p2In));
  fields.push(errLine);
  fields.push(el("p", { class: "dim", style: "margin-top:4px", text: "بعد از ورود، یک اکانت بازیِ آفلاین با همین نام خودکار ساخته/انتخاب می‌شود." }));
  const body = el("div", {}, ...fields);

  const actBtn = btn(isReg ? "ثبت‌نام" : "ورود", "check", "btn btn-primary");
  const submit = async () => {
    const u = uIn.value.trim(), p = pIn.value;
    errLine.textContent = "";
    if (!u || !p) { errLine.textContent = "نام کاربری و رمز را وارد کن."; return; }
    if (isReg && !/^[A-Za-z0-9_]{3,16}$/.test(u)) { errLine.textContent = "نام کاربری باید ۳ تا ۱۶ حرف انگلیسی/عدد/_ باشد."; return; }
    if (isReg && p.length < 6) { errLine.textContent = "رمز باید حداقل ۶ کاراکتر باشد."; return; }
    if (isReg && p2In && p !== p2In.value) { errLine.textContent = "رمز و تکرارش یکی نیستند."; return; }
    actBtn.disabled = true;
    try {
      const res = await invoke(isReg ? "account_register" : "account_login", { username: u, password: p });
      // هنگام ثبت‌نام، یک آواتارِ رندوم از لیستِ آواتارهای آماده برای کاربر ست کن
      if (isReg) {
        try {
          const idx = Math.floor(Math.random() * AVATAR_HEADS.length);
          const data = await presetAvatarDataUrl(idx);
          if (data) { await invoke("set_avatar", { imageData: data }); State.myAvatar = null; }
        } catch (_) {}
      }
      dlg.close(); await refreshConfig(); go(activePage || "profiles");
      toast((isReg ? "ثبت‌نام انجام شد — خوش آمدی " : "خوش آمدی ") + (res.username || u) + "!", "success");
    } catch (e) {
      errLine.textContent = String(e); actBtn.disabled = false;
    }
  };
  actBtn.addEventListener("click", submit);
  (p2In || pIn).addEventListener("keydown", (e) => { if (e.key === "Enter") submit(); });

  const dlg = modal({
    title: isReg ? "ثبت‌نام در لانچر" : "ورود به حساب لانچر",
    body,
    actions: [
      actBtn,
      btn(isReg ? "حساب دارم؟ ورود" : "حساب نداری؟ ثبت‌نام", null, "btn btn-ghost", { onclick: () => { dlg.close(); openAccountAuth(isReg ? "login" : "register"); } }),
      btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
    ],
  });
  uIn.focus();
}

// ═══════════════════════════════════════════════════════════
//  آواتار — رندومِ پایدار بر اساس نام کاربری (هر کاربر یک رنگ ثابت)
// ═══════════════════════════════════════════════════════════
function socialBase() {
  const b = (State.cfg && State.cfg.account_base_url) || "";
  return (b || "https://auth.mihancraft.com").replace(/\/+$/, "");
}
function avatarUrl(p) {
  // `p` is a server-supplied avatar path. Only accept a same-origin relative
  // path ("/avatars/…") — reject absolute URLs (http:, //host, data:, javascript:)
  // so a compromised relay can't point an <img src> at an attacker host.
  if (!p || typeof p !== "string") return null;
  if (!p.startsWith("/") || p.startsWith("//")) return null;
  return socialBase() + p;
}

// ── اخبار/اطلاعیه‌های صفحه‌ی اصلی ──
function newsWhen(ts) {
  if (!ts) return "";
  const d = Date.now() / 1000 - ts;
  if (d < 60) return "همین الان";
  if (d < 3600) return Math.floor(d / 60) + " دقیقه پیش";
  if (d < 86400) return Math.floor(d / 3600) + " ساعت پیش";
  if (d < 2592000) return Math.floor(d / 86400) + " روز پیش";
  try { return new Date(ts * 1000).toLocaleDateString("fa-IR"); } catch (_) { return ""; }
}
function newsZoom(url) {
  const ov = el("div", { class: "news-zoom", onclick: () => ov.remove() },
    el("img", { src: url }));
  document.body.appendChild(ov);
}
const NEWS_IMG_SECS = 5;  // مدتِ نمایشِ هر عکس در اسلایدشو

// یک ویدیوی استانداردِ اخبار (بی‌صدا، بدون کنترل/عقب‌جلو). loop=true یعنی تک‌رسانه.
function newsVideoEl(url, loop) {
  const v = el("video", { class: "news-vid", src: url, preload: "auto", playsinline: "" });
  v.muted = true; v.controls = false; v.loop = !!loop;
  v.setAttribute("disablepictureinpicture", "");
  v.addEventListener("contextmenu", (e) => e.preventDefault());
  _adVideos.add(v);
  new MutationObserver(() => { if (!document.body.contains(v)) { _adVideos.delete(v); v.pause(); } }).observe(v.parentElement || document.body, { childList: true });
  if (!document.hidden) v.play().catch(() => {});
  return v;
}

// رسانه‌ی خبر: تک‌رسانه ساده، چندرسانه = اسلایدشوی خودکار.
// عکس‌ها با تایمر اسلاید می‌خورند؛ ویدیو تا پایان پخش می‌شود و بعد اسلاید می‌خورد.
function newsMediaEl(media, base) {
  const wrap = el("div", { class: "news-media" });
  if (media.length === 1) {
    const m = media[0], url = base + m.url;
    if (m.type === "video") {
      const v = newsVideoEl(url, true);            // تک‌ویدیو = لوپ
      v.play && v.play().catch(() => {});
      wrap.appendChild(v);
    } else {
      wrap.appendChild(el("img", { class: "news-img", src: url, loading: "lazy" }));
    }
    return wrap;
  }

  // اسلایدِ افقیِ اینستاگرامی (همه‌ی سلول‌ها کنار هم، حرکت با translateX)
  wrap.classList.add("slideshow");
  const viewport = el("div", { class: "news-viewport" });
  const track = el("div", { class: "news-track" });
  const cells = media.map((m) => {
    const cell = el("div", { class: "news-cell" });
    const url = base + m.url;
    if (m.type === "video") {
      const v = newsVideoEl(url, false);            // در اسلایدشو لوپ نکن
      v.addEventListener("ended", next);
      v.addEventListener("error", () => { clearT(); timer = setTimeout(next, NEWS_IMG_SECS * 1000); });
      cell._video = v;
      cell.appendChild(v);
    } else {
      cell.appendChild(el("img", { class: "news-img", src: url, loading: "lazy" }));
    }
    track.appendChild(cell);
    return cell;
  });
  viewport.appendChild(track);
  wrap.appendChild(viewport);

  let idx = 0, timer = null;
  const clearT = () => { if (timer) { clearTimeout(timer); timer = null; } };
  function next() { goto(idx + 1); }
  function goto(n) {
    clearT();
    if (!wrap.isConnected) return;                  // برگه عوض شده → توقف
    cells.forEach((c) => { if (c._video) { try { c._video.pause(); } catch (_) {} } });
    idx = ((n % media.length) + media.length) % media.length;
    track.style.transform = "translateX(-" + (idx * 100) + "%)";
    const cell = cells[idx];
    if (cell._video) {
      const v = cell._video;
      try { v.currentTime = 0; } catch (_) {}
      const p = v.play && v.play();
      if (p && p.catch) p.catch(() => { clearT(); timer = setTimeout(next, 6000); });
    } else {
      timer = setTimeout(next, NEWS_IMG_SECS * 1000);
    }
  }
  // یک tick صبر کن تا wrap به DOM اضافه شود (isConnected)، بعد اسلایدشو را شروع کن
  setTimeout(() => goto(0), 0);
  return wrap;
}

function newsItemEl(it, base) {
  // کارتِ کوچک: تصویر/رسانه بالا، بعد برچسب + عنوان + متن (مثل کارتِ نمونه)
  const item = el("div", { class: "news-item" });
  const media = (it.media || []).filter((m) => m && m.url);
  if (media.length) item.appendChild(newsMediaEl(media, base));
  const body = el("div", { class: "news-body" });
  body.appendChild(el("div", { class: "news-eyebrow", text: it.pinned ? "📌 سنجاق‌شده" : "اخبار جدید" }));
  if (it.title) body.appendChild(el("div", { class: "news-title", text: it.title }));
  if (it.body) {
    // متنِ بلند جمع‌وجور نشان داده می‌شود؛ با دکمه‌ی «ادامه» کامل باز می‌شود.
    const LONG = 320;
    const txt = el("div", { class: "news-text", text: it.body });
    body.appendChild(txt);
    if (it.body.length > LONG) {
      txt.classList.add("clamped");
      const more = el("button", { class: "news-more", text: "ادامهٔ متن ▾" });
      more.addEventListener("click", () => {
        const open = txt.classList.toggle("clamped");   // toggle: حالا اگر clamped برداشته شد یعنی باز است
        more.textContent = txt.classList.contains("clamped") ? "ادامهٔ متن ▾" : "بستن ▴";
      });
      body.appendChild(more);
    }
  }
  body.appendChild(el("div", { class: "news-when", text: newsWhen(it.created_at) }));
  item.appendChild(body);
  return item;
}
// مجموعه‌ای از آواتارهای گرادیانی که به‌صورت رندوم (اما پایدار) به هر کاربر داده می‌شود
const AVATAR_GRADIENTS = [
  "linear-gradient(135deg,#667eea,#764ba2)", "linear-gradient(135deg,#f093fb,#f5576c)",
  "linear-gradient(135deg,#4facfe,#00f2fe)", "linear-gradient(135deg,#43e97b,#38f9d7)",
  "linear-gradient(135deg,#fa709a,#fee140)", "linear-gradient(135deg,#30cfd0,#330867)",
  "linear-gradient(135deg,#a8edea,#fed6e3)", "linear-gradient(135deg,#ff9a9e,#fecfef)",
  "linear-gradient(135deg,#f6d365,#fda085)", "linear-gradient(135deg,#5ee7df,#b490ca)",
  "linear-gradient(135deg,#c79081,#dfa579)", "linear-gradient(135deg,#3a7bd5,#00d2ff)",
];
function avatarHash(s) { let h = 0; for (let i = 0; i < (s || "").length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0; return h; }
function letterAvatar(name, size = 40) {
  const g = AVATAR_GRADIENTS[avatarHash(name) % AVATAR_GRADIENTS.length];
  return el("div", { class: "avatar avatar-letter", style: `width:${size}px;height:${size}px;font-size:${Math.round(size * 0.42)}px;background:${g};color:#fff`, text: (name || "?")[0].toUpperCase() });
}
function avatarEl(name, path, size = 40) {
  const u = avatarUrl(path);
  if (u) {
    const img = el("img", { class: "avatar", src: u, alt: name || "", style: `width:${size}px;height:${size}px` });
    img.addEventListener("error", () => img.replaceWith(letterAvatar(name, size)));
    return wrapProRing(img, name, size);
  }
  return wrapProRing(letterAvatar(name, size), name, size);
}

// ═══════════════════════════════════════════════════════════
//  ۶۴ آواتارِ ماینکرفتی — سرِ اسکینِ واقعیِ ۶۴×۶۴ (رندرِ mc-heads.net)
//  نام‌های MHF (سرهای رسمیِ ماینکرفت: کریپر، اسکلت، زامبی و...) + اسکین
//  توسعه‌دهنده‌ها. هنگام انتخاب، PNG ۶۴×۶۴ گرفته و با set_avatar روی سرور
//  ذخیره می‌شود تا در چت/وویس/سوشال هم دیده شود. همگی تست‌شده و متفاوت‌اند.
// ═══════════════════════════════════════════════════════════
// آواتارهای پیش‌فرض از CDN ایران (به‌جای mc-heads.net خارجی) — ۱۲۸px، سایز با CSS تنظیم می‌شود.
const HEADS_BASE = "https://cdn.mihancraft.com/afzodaniha/avatars";
const AVATAR_HEADS = [
  "MHF_Steve", "MHF_Alex", "MHF_Creeper", "MHF_Skeleton", "MHF_Zombie", "MHF_PigZombie",
  "MHF_Spider", "MHF_CaveSpider", "MHF_Enderman", "MHF_Blaze", "MHF_Ghast", "MHF_Slime",
  "MHF_LavaSlime", "MHF_Pig", "MHF_Cow", "MHF_MushroomCow", "MHF_Sheep", "MHF_Chicken",
  "MHF_Squid", "MHF_Wolf", "MHF_Ocelot", "MHF_Villager", "MHF_Golem", "MHF_Herobrine",
  "MHF_Guardian", "MHF_Pumpkin", "MHF_Melon", "MHF_Cactus", "MHF_TNT", "MHF_TNT2",
  "MHF_Chest", "MHF_EnderChest", "MHF_Present1", "MHF_Present2", "MHF_ArrowUp", "MHF_ArrowDown",
  "MHF_ArrowLeft", "MHF_ArrowRight", "MHF_Exclamation", "MHF_Question", "MHF_Cake", "MHF_Coconut",
  "MHF_OakLog", "MHF_Apple", "MHF_SnowGolem", "MHF_Rabbit", "MHF_Vex", "MHF_Evoker",
  "MHF_Vindicator", "MHF_Husk", "MHF_Stray", "MHF_Bat", "MHF_Horse", "MHF_Witch",
  "MHF_Turtle", "MHF_Fox", "MHF_Panda", "MHF_Bee", "MHF_Parrot", "MHF_Pufferfish",
  "Notch", "jeb_", "Dinnerbone", "Grumm",
];
const AVATAR_COUNT = AVATAR_HEADS.length;

// size: رزولوشنِ هد (پیش‌فرض ۶۴×۶۴ — خواسته‌ی کاربر)
// آواتارها داخلِ خودِ APK هستند (avatars-embed.js). مسیرِ CDN فقط فال‌بک است — روی سرور
// منتشر نشده و ۴۰۳ می‌دهد، برای همین هر ۶۴ آواتار در اندروید شکسته نشان داده می‌شد (#4031).
function presetAvatarUrl(i, size) {
  const name = AVATAR_HEADS[i];
  const embedded = window.__MIHAN_AVATARS__ && window.__MIHAN_AVATARS__[name];
  if (embedded) return embedded;
  return `${HEADS_BASE}/${encodeURIComponent(name)}.png`;
}

// PNG ۶۴×۶۴ را می‌گیرد و به dataURL تبدیل می‌کند (برای آپلود به سرور)
async function presetAvatarDataUrl(i) {
  const u = presetAvatarUrl(i, 64);
  if (u.startsWith("data:")) return u;   // نسخه‌ی embed‌شده — نه شبکه لازم است نه fetch
  const r = await fetch(u);
  if (!r.ok) throw new Error("avatar fetch " + r.status);
  const blob = await r.blob();
  return await new Promise((res, rej) => {
    const fr = new FileReader();
    fr.onload = () => res(fr.result);
    fr.onerror = () => rej(new Error("خواندن تصویر ناموفق بود"));
    fr.readAsDataURL(blob);
  });
}

// ── آپلودِ آواتار از روی اسکینِ کاربر ──
// از فایلِ اسکینِ ماینکرفت (۶۴×۶۴ یا ۶۴×۳۲) ناحیه‌ی «سر» را برش می‌زند:
// صورت در (۸,۸) و لایه‌ی کلاه/مو در (۴۰,۸) — هرکدام ۸×۸ پیکسل.
function skinToHeadDataUrl(img) {
  const out = document.createElement("canvas");
  out.width = out.height = 64;
  const ctx = out.getContext("2d");
  ctx.imageSmoothingEnabled = false;      // نزدیک‌ترین‌همسایه → بلوکیِ تمیز
  ctx.drawImage(img, 8, 8, 8, 8, 0, 0, 64, 64);    // صورت
  ctx.drawImage(img, 40, 8, 8, 8, 0, 0, 64, 64);   // لایه‌ی روییِ سر (کلاه/مو)
  return out.toDataURL("image/png");
}

// انتخابِ فایل با input مخفی (در WebView بدون taint قابلِ خواندن است)
function pickImageFile() {
  return new Promise((resolve) => {
    const inp = el("input", { type: "file", accept: "image/png,image/*", style: "display:none" });
    inp.addEventListener("change", () => { resolve((inp.files && inp.files[0]) || null); inp.remove(); });
    document.body.appendChild(inp);
    inp.click();
  });
}
// نسخه‌ی عمومیِ انتخابِ فایل (مثلاً "video/*") که یک File برمی‌گرداند تا مرورگر بتواند بخواند.
function pickFile(accept) {
  return new Promise((resolve) => {
    const inp = el("input", { type: "file", accept: accept || "*/*", style: "display:none" });
    inp.addEventListener("change", () => { resolve((inp.files && inp.files[0]) || null); inp.remove(); });
    document.body.appendChild(inp);
    inp.click();
  });
}

function loadImageFromFile(file) {
  return new Promise((res, rej) => {
    const fr = new FileReader();
    fr.onload = () => {
      const im = new Image();
      im.onload = () => res(im);
      im.onerror = () => rej(new Error("بارگذاری تصویر ناموفق بود"));
      im.src = fr.result;
    };
    fr.onerror = () => rej(new Error("خواندن فایل ناموفق بود"));
    fr.readAsDataURL(file);
  });
}

async function uploadSkinAvatar(onPicked) {
  const file = await pickImageFile();
  if (!file) return;
  try {
    const img = await loadImageFromFile(file);
    if (img.naturalWidth < 48 || img.naturalHeight < 16) {
      toast("این فایل یک اسکینِ معتبرِ ماینکرفت نیست (باید ۶۴×۶۴ باشد).", "error");
      return;
    }
    const data = skinToHeadDataUrl(img);
    const res = await invoke("set_avatar", { imageData: data });
    setCfg("avatar_set", true);
    toast("آواتار از روی اسکینت ساخته شد ✔", "success");
    if (onPicked) onPicked((res && res.avatar) || null);
  } catch (e) {
    toast("خطا در ساختِ آواتار از اسکین: " + e, "error");
  }
}

// از یک منبعِ اسکین (dataURL یا URL) سرش را برش می‌زند و به‌عنوان آواتار ذخیره می‌کند.
async function avatarFromSkinSrc(src) {
  const img = await loadImg(src);
  const data = skinToHeadDataUrl(img);
  const res = await invoke("set_avatar", { imageData: data });
  setCfg("avatar_set", true);
  return (res && res.avatar) || null;
}

// ── کمدِ اسکین‌های شخصی (حداکثر ۱۰ تا، در config ذخیره می‌شود) ──
const MY_SKINS_MAX = 10;
function getMySkins() {
  return (State.cfg && Array.isArray(State.cfg.my_skins)) ? State.cfg.my_skins : [];
}
async function addMySkin(data, model) {
  let list = getMySkins().filter((s) => s.data !== data);   // تکراری را بالا بیاور، نه دوباره
  list.unshift({ data, model: model || "classic" });
  if (list.length > MY_SKINS_MAX) list = list.slice(0, MY_SKINS_MAX);
  await setCfg("my_skins", list);
}
async function removeMySkin(data) {
  await setCfg("my_skins", getMySkins().filter((s) => s.data !== data));
}

// ── کمدِ شنل‌های شخصی (حداکثر ۱۰ تا، در config ذخیره می‌شود) — مثلِ کمدِ اسکین ──
const MY_CAPES_MAX = 10;
function getMyCapes() {
  return (State.cfg && Array.isArray(State.cfg.my_capes)) ? State.cfg.my_capes : [];
}
async function addMyCape(data) {
  if (!data) return;
  let list = getMyCapes().filter((c) => c.data !== data);   // تکراری را بالا بیاور، نه دوباره
  list.unshift({ data });
  if (list.length > MY_CAPES_MAX) list = list.slice(0, MY_CAPES_MAX);
  await setCfg("my_capes", list);
}
async function removeMyCape(data) {
  await setCfg("my_capes", getMyCapes().filter((c) => c.data !== data));
}

// Modal grid of 64 avatars. onPicked(path) fires after a successful upload.
function openAvatarPicker(userOnPicked) {
  const loggedIn = !!(State.cfg && State.cfg.account_token && State.cfg.account_token.length);
  if (!loggedIn) { toast("برای انتخاب آواتار اول وارد حساب لانچر شو", "error"); return; }
  // every successful pick (preset / skin upload) flows through here, so update the
  // cached avatar and repaint the sidebar in one place for all surfaces
  const onPicked = (path) => { setMyAvatar(path); if (userOnPicked) userOnPicked(path); };

  const grid = el("div", { class: "avatar-pick-grid" });
  const hint = el("p", { class: "dim", style: "margin:0 0 12px", text: "یکی از این ۶۴ آواتار را انتخاب کن، یا اسکینِ خودت را آپلود کن تا سرش آواتارت شود (در چت، وویس و بخش اجتماعی دیده می‌شود)." });
  let busy = false;

  // دکمه‌ی آپلودِ اسکینِ شخصی
  const skinBtn = btn("آپلود اسکینِ خودم", "upload", "btn btn-sm btn-primary");
  skinBtn.addEventListener("click", () => {
    if (busy) return;
    uploadSkinAvatar((path) => { dlg.close(); if (onPicked) onPicked(path); });
  });
  const skinRow = el("div", { class: "row", style: "gap:10px;align-items:center;margin:0 0 14px;flex-wrap:wrap" },
    skinBtn,
    el("span", { class: "dim", style: "font-size:12px", text: "فایلِ اسکینِ ۶۴×۶۴ ماینکرفت (PNG)" }));

  for (let i = 0; i < AVATAR_COUNT; i++) {
    const img = el("img", { class: "avatar-pick-img", src: presetAvatarUrl(i, 128), alt: AVATAR_HEADS[i], loading: "lazy" });
    const b = el("button", { class: "avatar-pick-btn", type: "button", title: `آواتار ${i + 1}` }, img);
    b.addEventListener("click", async () => {
      if (busy) return;
      busy = true;
      b.classList.add("loading");
      try {
        const res = await invoke("set_avatar", { imageData: await presetAvatarDataUrl(i) });
        const path = (res && res.avatar) || null;
        setCfg("avatar_set", true);
        toast("آواتار انتخاب شد ✔", "success");
        dlg.close();
        if (onPicked) onPicked(path);
      } catch (e) {
        toast("خطا در ذخیره آواتار: " + e, "error");
        b.classList.remove("loading");
        busy = false;
      }
    });
    grid.appendChild(b);
  }

  const dlg = modal({
    title: "انتخاب آواتار",
    body: el("div", {}, hint, skinRow, grid),
    actions: [btn("بستن", null, "btn btn-ghost", { onclick: () => dlg.close() })],
  });
}
// gate: returns true if logged in, else renders a prompt
function accountGate(root, what) {
  if (State.selected) return true;
  root.appendChild(el("div", { class: "empty" },
    el("div", { class: "big" }, icon("user", 42)),
    el("div", { text: `برای استفاده از «${what}» اول یک حساب ماینکرفت بساز یا انتخاب کن.` }),
    btn("مدیریت حساب‌ها", "user", "btn btn-primary", { style: "margin-top:14px", onclick: () => openAccountManager() })));
  return false;
}

Pages.profiles = async (root) => {
  root.appendChild(launcherAccountCard());
};

// ── حساب کاربری (حساب‌های ماینکرفت/لانچر) ──
Pages.mcaccount = async (root) => {
  renderAccountManage(root);
};

// ── اجتماعی (تبِ مستقلِ سطح‌بالا: درخواست‌های دوستی + پیام‌ها + گفتگوها) ──
Pages.social = async (root) => {
  // گفتگوها داخلِ همان هابی رندر می‌شوند که فید/اکسپلور/پروفایل استفاده می‌کنند —
  // وگرنه رفتن به «اجتماعی» نوارِ تب‌ها را می‌بلعید و راهِ برگشتی به فید نمی‌ماند.
  const info = await invoke("chat_info").catch(() => null);
  const hubRoot = mountSocialHub(root, "social", info);
  await renderAccountSocial(hubRoot);
};

// مودالِ انتخابِ اسکین/شنل برای **یک حسابِ مشخص** — اول انتخاب از فایل، بعد لیست/گالری.
// جایگزینِ بخشِ جداگانه‌ی قبلی شد (که موقعِ هر انتخابِ حساب دوباره لود می‌شد و باعثِ چشمک/لگ بود).
function openCosmeticPicker(account, kind) {
  const isCape = kind === "cape";
  const body = el("div", {});
  body.appendChild(el("p", { class: "muted", style: "margin:0 0 10px", text: isCape ? "یک شنل از فایل انتخاب کن یا از گالریِ زیر یکی را بزن." : "یک اسکین (PNG ۶۴×۶۴) از فایل انتخاب کن یا از گالریِ زیر یکی را بزن." }));
  const applyFile = async () => {
    const f = await pickImageFile(); if (!f) return;
    try {
      const img = await loadImageFromFile(f);
      if (!isCape && !(img.naturalWidth === 64 && (img.naturalHeight === 64 || img.naturalHeight === 32))) { toast("اسکین باید PNG با ابعاد ۶۴×۶۴ باشد", "error"); return; }
      const c = document.createElement("canvas"); c.width = img.naturalWidth; c.height = img.naturalHeight;
      const x = c.getContext("2d"); x.imageSmoothingEnabled = false; x.drawImage(img, 0, 0);
      const dataUrl = c.toDataURL("image/png");
      if (isCape) await invoke("cape_select", { url: dataUrl, accounts: [account.uuid] });
      else await invoke("account_set_skin", { uuid: account.uuid, image: dataUrl, model: "classic" });
      toast(isCape ? "شنل ثبت شد" : "اسکین ثبت شد", "success"); dlg.close();
      await refreshConfig(); go("mcaccount"); // اواتارِ کنارِ نامِ حساب (که از روی اسکین ساخته می‌شود) فوری آپدیت شود
    } catch (e) { toast("خطا: " + e, "error"); }
  };
  body.appendChild(btn(isCape ? "انتخاب فایلِ شنل" : "انتخاب فایلِ اسکین", "upload", "btn btn-sm", { style: "margin-bottom:10px", onclick: applyFile }));
  const gallery = el("div", { class: isCape ? "cape-grid" : "sk-pick-grid", style: "max-height:360px;overflow:auto" });
  body.appendChild(gallery);
  gallery.appendChild(el("div", { class: "dim", style: "grid-column:1/-1;padding:14px", text: "در حال بارگذاری..." }));
  // اسکین: هم اسکین‌های خودِ کاربر (skin_gallery) و هم اسکین‌هایی که **کاربرانِ دیگر منتشر
  // کرده‌اند** (cosmetic_list با kind=skin — همان گالریِ کامیونیتی مثلِ شنل) را ادغام می‌کنیم.
  const loadItems = isCape
    ? invokeCached("cape_gallery").then((r) => ((r && r.capes) || []))
    : Promise.all([
        invokeCached("skin_gallery").then((r) => ((r && r.skins) || [])).catch(() => []),
        invoke("cosmetic_list", { kind: "skin", sort: "top" }).then((r) => ((r && r.items) || [])).catch(() => []),
      ]).then(([mine, community]) => {
        const seen = new Set(), out = [];
        for (const it of [...mine, ...community]) { const k = String(it.url || it.data || it.id || ""); if (!k || seen.has(k)) continue; seen.add(k); out.push(it); }
        return out;
      });
  loadItems.then((items) => {
    gallery.innerHTML = "";
    if (!items.length) { gallery.appendChild(el("div", { class: "dim", style: "grid-column:1/-1;padding:14px", text: isCape ? "هنوز شنلی نیست." : "هنوز اسکینی نیست." })); return; }
    const skinCells = [];
    items.slice(0, 120).forEach((item) => {
      if (isCape) {
        const thumb = el("canvas", { class: "cape-thumb", style: "image-rendering:pixelated" });
        loadImg(item.url).then((img) => drawCapeFront(thumb, img, 6)).catch(() => {});
        const cell = el("div", { class: "cape-cell", title: item.name || "" }, thumb, el("div", { class: "cape-cell-name", text: item.builtin ? item.name : (item.owner || item.name || "شنل") }));
        markHdLock(cell, item.url, "cape");
        cell.addEventListener("click", async () => { if (hdLockedClick(cell)) return; try { await invoke("cape_select", { url: item.url, accounts: [account.uuid] }); toast("شنل ثبت شد", "success"); dlg.close(); } catch (e) { toast("خطا: " + e, "error"); } });
        gallery.appendChild(cell);
      } else {
        // اسکین را سه‌بعدی «روی مدل» نشان بده (نه PNGِ تخت). رِندر تنبل است — فقط سلول‌هایی که
        // به دید می‌آیند رِندر می‌شوند تا هم لگ نکند هم به سرور فشار نیاید.
        const cell = el("div", { class: "sk-pick-cell", style: "cursor:pointer;padding:8px;text-align:center" });
        const holder = el("div", { style: "width:104px;height:168px;margin:0 auto;display:flex;align-items:center;justify-content:center;background:linear-gradient(180deg,#20293a,#161d29);border-radius:10px;overflow:hidden" });
        cell.appendChild(holder);
        cell._render3d = () => { if (cell._done) return; cell._done = true; holder.appendChild(makeSkin3dThumb(item.data || item.url, item.model || "classic", "skin-thumb")); };
        markHdLock(cell, item.data || item.url, "skin");
        cell.addEventListener("click", async () => {
          if (hdLockedClick(cell)) return;
          try {
            // URLِ CDN را اول به data-URL تبدیل کن؛ سرورِ اسکین، URLِ خام را «تصویر نامعتبر» رد می‌کند.
            const img = await resolveSkinData(item.data || item.url);
            if (!img) { toast("تصویرِ اسکین در دسترس نیست — دوباره امتحان کن", "error"); return; }
            await invoke("account_set_skin", { uuid: account.uuid, image: img, model: item.model || "classic" });
            toast("اسکین ثبت شد", "success"); dlg.close();
            await refreshConfig(); go("mcaccount");
          } catch (e) { toast("خطا: " + e, "error"); }
        });
        skinCells.push(cell);
        gallery.appendChild(cell);
      }
    });
    if (skinCells.length) {
      if ("IntersectionObserver" in window) {
        const io = new IntersectionObserver((ents) => { ents.forEach((e) => { if (e.isIntersecting) { io.unobserve(e.target); if (e.target._render3d) e.target._render3d(); } }); }, { root: gallery, rootMargin: "200px" });
        skinCells.forEach((c) => io.observe(c));
      } else {
        skinCells.forEach((c) => { if (c._render3d) c._render3d(); });
      }
    }
  }).catch(() => { gallery.innerHTML = ""; gallery.appendChild(el("div", { class: "dim", style: "grid-column:1/-1;padding:14px", text: "بارگذاری ناموفق." })); });
  const dlg = modal({ title: `${isCape ? "انتخابِ شنل" : "انتخابِ اسکین"} — ${account.username}`, body,
    actions: [btn("بستن", null, "btn btn-ghost", { onclick: () => dlg.close() })] });
}

// زیربخشِ «حساب‌ها»: کارتِ حسابِ لانچر + افزودن/فهرستِ حساب‌های ماینکرفت
function renderAccountManage(root) {
  root.appendChild(launcherAccountCard());

  const card = el("div", { class: "card" });
  card.appendChild(secTitle("افزودن حساب ماینکرفت", "plus"));
  const row = el("div", { class: "row" });
  const offBtn = btn("حساب آفلاین", "user", "btn");
  const msBtn = btn("ورود با مایکروسافت", "key", "btn btn-primary");
  offBtn.addEventListener("click", addOffline);
  msBtn.addEventListener("click", addMicrosoft);
  row.appendChild(offBtn); row.appendChild(msBtn);
  card.appendChild(row);
  root.appendChild(card);

  const list = el("div", { class: "card" });
  list.appendChild(secTitle("حساب‌های ذخیره‌شده", "users"));
  if (State.accounts.length === 0) {
    list.appendChild(el("div", { class: "empty" }, el("div", { class: "big" }, icon("user", 42)), el("div", { text: "هنوز حسابی نساخته‌ای" })));
  } else {
    for (const a of State.accounts) {
      const isSel = State.selected && State.selected.uuid === a.uuid;
      const item = el("div", { class: "list-item" },
        accAvatarElFromSkin(a),
        el("div", { style: "flex:1" },
          el("div", { style: "font-weight:700", text: a.username }),
          el("div", { class: "dim", text: a.type === "microsoft" ? "مایکروسافت" : "آفلاین" })),
        isSel ? tag("فعال", "tag green", "check")
          : btn("انتخاب", null, "btn btn-sm", { onclick: async () => { await invoke("select_account", { uuid: a.uuid }); await refreshConfig(); go("mcaccount"); } }),
        btn(null, "palette", "btn btn-sm btn-icon", { title: "اسکین", onclick: () => openCosmeticPicker(a, "skin") }),
        btn(null, "cape", "btn btn-sm btn-icon", { title: "شنل", onclick: () => openCosmeticPicker(a, "cape") }),
        a.type === "microsoft" ? el("span", {}) : btn(null, "pencil", "btn btn-sm btn-icon", { title: "تغییر نام", onclick: () => {
          promptInput("تغییر نام کاربری", "نام جدید (حداقل ۳ حرف)", async (v) => { await invoke("rename_account", { uuid: a.uuid, username: v }); await refreshConfig(); go("mcaccount"); toast("نام تغییر کرد", "success"); }, a.username);
        } }),
        btn(null, "trash", "btn btn-sm btn-icon danger", { title: "حذف", onclick: () => confirmDialog("حذف حساب", `«${a.username}» حذف شود؟`, async () => { await invoke("remove_account", { uuid: a.uuid }); await refreshConfig(); go("mcaccount"); }) }));
      list.appendChild(item);
    }
  }
  root.appendChild(list);

}

// زیربخشِ «اجتماعی»: درخواست‌های دوستی + پیام‌ها + گفتگوها (همان محتوای صفحه‌ی پیام‌ها)
async function renderAccountSocial(root) {
  const info = await invoke("chat_info").catch(() => null);
  if (!info || !info.logged_in) {
    root.appendChild(el("div", { class: "card" }, secTitle("اجتماعی", "users"),
      el("p", { class: "muted", text: "برای پیامِ خصوصی و دوستی، اول وارد حساب لانچر شو (ثبت‌نام یا ورود)." })));
    root.appendChild(launcherAccountCard());
    return;
  }
  Messages._alive = true;
  onPageLeave(() => { Messages._alive = false; Messages.stopPoll(); });
  await Messages.renderList(root);
  renderBlockedList(root);
}

// فهرستِ کاربرانِ بلاک‌شده + دکمه‌ی آنبلاک برای هرکدام.
function renderBlockedList(root) {
  const card = el("div", { class: "card", style: "margin-top:14px" });
  card.appendChild(secTitle("کاربرانِ بلاک‌شده", "lock"));
  const box = el("div", { style: "margin-top:8px" });
  card.appendChild(box);
  box.appendChild(el("div", { class: "dim", style: "padding:8px", text: "در حال بارگذاری…" }));
  root.appendChild(card);
  invoke("block_list").then((res) => {
    box.innerHTML = "";
    const list = (res && res.blocked) || [];
    if (!list.length) { box.appendChild(el("div", { class: "dim", style: "padding:8px", text: "کسی را بلاک نکرده‌ای." })); return; }
    list.forEach((u) => {
      const item = el("div", { class: "list-item" },
        accAvatarEl(u.username),
        el("div", { style: "flex:1;font-weight:600", text: u.username }),
        btn("آنبلاک", "check", "btn btn-sm", { onclick: async (e) => {
          const b = e.currentTarget; b.disabled = true;
          try { await invoke("block_user", { username: u.username }); toast("آنبلاک شد", "success"); item.remove(); if (!box.children.length) box.appendChild(el("div", { class: "dim", style: "padding:8px", text: "کسی را بلاک نکرده‌ای." })); }
          catch (err) { toast("خطا: " + err, "error"); b.disabled = false; }
        } }));
      box.appendChild(item);
    });
  }).catch(() => { box.innerHTML = ""; box.appendChild(el("div", { class: "dim", style: "padding:8px", text: "بارگذاری ناموفق." })); });
}

function addOffline() {
  const input = el("input", { class: "input", placeholder: "نام کاربری (حداقل ۳ حرف)" });
  const dlg = modal({
    title: "حساب آفلاین",
    body: el("label", { class: "field" }, el("span", { text: "نام کاربری" }), input),
    actions: [
      btn("ساخت", "check", "btn btn-primary", { onclick: async () => {
        const u = input.value.trim();
        const create = async () => {
          try { await invoke("add_offline_account", { username: u }); dlg.close(); await refreshConfig(); go("mcaccount"); toast("حساب ساخته شد", "success"); }
          catch (e) { toast(e, "error"); }
        };
        // Minecraft username rule: 3–16 chars of a–z, 0–9, underscore
        if (!/^[A-Za-z0-9_]{3,16}$/.test(u)) {
          confirmDialog("نام غیراستاندارد",
            `نام «${u}» با قانون نام کاربری ماینکرفت (۳ تا ۱۶ حرف فقط شامل حروف انگلیسی، عدد و _ ) فرق دارد. ممکن است در بعضی سرورها نتوانی وارد شوی. باز هم ساخته شود؟`,
            create);
          return;
        }
        create();
      } }),
      btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
    ],
  });
  input.focus();
}

async function addMicrosoft() {
  try {
    const acc = await msLogin();
    await refreshConfig(); go("mcaccount");
    try { ensureBackgroundChat(); } catch (_) {}   // بعد از ورود، سوکتِ چت را بالا بیاور
    toast("خوش آمدی " + acc.username + "!", "success");
  } catch (e) { if (e !== "لغو شد") toast("ورود ناموفق: " + e, "error"); }
}

// ── Shared download source selector ───────────────────────
// انتخابِ منبعِ دانلود: «سرور ایران» (CDN داخلی، بدونِ فیلترشکن) یا «سرور خارج».
// داخلِ پروفایل‌ها و افزودنی‌ها استفاده می‌شود؛ انتخاب سراسری ذخیره می‌شود.
function downloadSourceCard() {
  const card = el("div", { class: "card", style: "margin-bottom:14px" });
  card.appendChild(secTitle("منبع دانلود", "download"));
  const isIran = () => !!(State.cfg && State.cfg.download_source === "iran");
  const irBtn = el("div", { class: "chip chip-ic" + (isIran() ? " active" : "") }, icon("home", 14), el("span", { text: "دانلود از سرور ایران" }));
  const exBtn = el("div", { class: "chip chip-ic" + (!isIran() ? " active" : "") }, icon("globe", 14), el("span", { text: "دانلود از سرور خارج" }));
  const note = el("div", { class: "muted", style: "margin-top:10px;line-height:1.8;font-size:12.5px" });
  const setNote = () => {
    note.textContent = isIran()
      ? "دانلود از سرورِ ایران (بدونِ نیاز به وی‌پی‌ان). فقط نسخه‌ها، لودرها و افزودنی‌هایی که روی سرورِ ایران موجودند نشان داده می‌شوند."
      : "🌐 دانلود از سرورِ خارج (ممکن است برای دانلود به وی‌پی‌ان نیاز داشته باشی). همه‌ی نسخه‌ها در دسترس‌اند.";
  };
  const pick = (iran) => {
    if (isIran() === iran) return;
    if (State.cfg) State.cfg.download_source = iran ? "iran" : "foreign";
    try { invoke("set_download_source", { iran }); } catch (_) {}
    if (iran) loadIranIndex();
    go(activePage); // فیلترها روی همین صفحه دوباره اعمال شوند
  };
  irBtn.addEventListener("click", () => pick(true));
  exBtn.addEventListener("click", () => pick(false));
  setNote();
  card.appendChild(el("div", { class: "row", style: "gap:8px;margin-top:6px;flex-wrap:wrap" }, irBtn, exBtn));
  card.appendChild(note);
  return card;
}

// بنرِ توصیه‌ی شبکه (با ضربدر بسته می‌شود و دیگر نمی‌آید) — بالای نصب نسخه.
function netAdviceBanner() {
  try { if (localStorage.getItem("hideNetAdvice") === "1") return null; } catch (_) {}
  const bar = el("div", { class: "net-advice card" });
  bar.appendChild(el("span", { class: "net-advice-ico" }, icon("info", 18)));
  bar.appendChild(el("span", { class: "net-advice-txt", text: "اگر در نصب نسخه‌ها یا افزودنی‌ها مشکل داری، از اینترنت همراه اول یا ایرانسل استفاده کن (مخابرات ممکن است مشکل‌ساز باشد)." }));
  bar.appendChild(btn(null, "x", "btn btn-sm btn-icon net-advice-x", { title: "بستن", onclick: () => { try { localStorage.setItem("hideNetAdvice", "1"); } catch (_) {} bar.remove(); } }));
  return bar;
}
// ── infinite-scroll Modrinth search (shared by mods + modpacks) ──
// نگاشتِ نوعِ پروژه‌ی Modrinth به کلیدِ ایندکسِ سرورِ ایران (modpack روی CDN نداریم → فیلتر نمی‌شود)
const IRAN_ADDON_KIND = { mod: "mods", shader: "shaders", resourcepack: "resourcepacks" };
function setupInfiniteSearch({ resultsEl, getParams, cardFn, cmd, itemsOf, totalOf }) {
  const LIMIT = 30;
  // پیش‌فرض = مادرینث (سازگاریِ عقب‌رو). برای CurseForge کافیه cmd/itemsOf/totalOf بدی.
  cmd = cmd || "mods_search";
  itemsOf = itemsOf || ((data) => data.hits || []);
  totalOf = totalOf || ((data) => (data.total_hits != null ? data.total_hits : Infinity));
  let offset = 0, loading = false, done = false, shown = 0;
  async function loadPage() {
    if (loading || done) return;
    loading = true;
    if (offset === 0) { resultsEl.innerHTML = '<div class="row" style="justify-content:center;padding:24px;grid-column:1/-1"><span class="spinner"></span></div>'; shown = 0; }
    const more = el("div", { class: "inf-more" }, el("span", { class: "spinner" }));
    if (offset > 0) resultsEl.appendChild(more);
    try {
      const p = getParams();
      const data = await invoke(cmd, { ...p, limit: LIMIT, offset });
      if (offset === 0) resultsEl.innerHTML = "";
      more.remove();
      const raw = itemsOf(data) || [];
      // این تابع فقط برای تبِ «سرور خارج» است — همیشه بدونِ فیلترِ ایران؛ مرورگرِ
      // سرورِ ایران تبِ جدای خودش را دارد (renderIranAddons)، پس اینجا فیلتر نمی‌کنیم.
      const hits = raw;
      hits.forEach((h) => resultsEl.appendChild(cardFn(h)));
      shown += hits.length;
      offset += raw.length;   // صفحه‌بندی با تعدادِ خامِ منبع جلو می‌رود
      const total = totalOf(data);
      if (raw.length < LIMIT || offset >= total) done = true;
      loading = false;
      // اگر زیرِ منبعِ ایران این صفحه پس از فیلتر کم/خالی شد ولی هنوز صفحه‌ی دیگری هست،
      // خودکار ادامه بده تا کاربر بدونِ اسکرول هم نتیجه ببیند (سقفِ معقول).
      if (usingIran() && ikind && !done && shown < 12) return loadPage();
      if (resultsEl.children.length === 0) resultsEl.appendChild(el("div", { class: "dim", style: "grid-column:1/-1;padding:14px;text-align:center", text: usingIran() ? "از این نوع، چیزی روی سرورِ ایران نداریم." : "نتیجه‌ای پیدا نشد." }));
      return;
    } catch (e) {
      more.remove();
      if (offset === 0) { resultsEl.innerHTML = ""; resultsEl.appendChild(el("div", { class: "dim", style: "grid-column:1/-1", text: "خطا: " + e })); }
    }
    loading = false;
  }
  function reset() { offset = 0; done = false; loadPage(); }
  const area = $("#pageArea");
  // rAF-guard: هر رویدادِ scroll، layout را نخواند (storm)؛ فقط یک‌بار در هر فریم
  let _scrollRaf = 0;
  area._scroll = () => {
    if (_scrollRaf) return;
    _scrollRaf = requestAnimationFrame(() => {
      _scrollRaf = 0;
      if (area.scrollTop + area.clientHeight >= area.scrollHeight - 400) loadPage();
    });
  };
  area.addEventListener("scroll", area._scroll);
  return { reset };
}

async function installModpack(h, btnEl) {
  const _k = "mp:" + (h.project_id || h.slug || h.title || "");
  promptInput("نصب مودپک", "نام پروفایل", async (name) => {
    const old = btnEl.innerHTML;
    btnEl.disabled = true; btnEl.innerHTML = '<span class="spinner"></span>';
    _installingIds.add(_k);
    setStatus("نصب مودپک...");
    try {
      // installWithProgress shows a live modal (detailed status + cancel button)
      const inst = await installWithProgress("نصب مودپک: " + (h.title || name), "modpack_install", { projectId: h.project_id || h.slug, name });
      setStatus("آماده");
      if (inst === null) { btnEl.disabled = false; btnEl.innerHTML = old; return; } // cancelled
      toast("مودپک نصب شد", "success"); openInstancePanel(inst);
    } catch (e) { toast("خطا: " + e, "error"); setStatus("آماده"); btnEl.disabled = false; btnEl.innerHTML = old; }
    finally { _installingIds.delete(_k); }
  }, h.title);
}

// ── Mods / Shaders / Resource packs ───────────────────────
const CONTENT_KINDS = [["mod", "ماد‌ها", "puzzle"], ["shader", "شیدرها", "zap"], ["resourcepack", "ریسورس‌پک‌ها", "gift"]];

// Derive the plain Minecraft version (e.g. "1.20.1" / "26.2") from a profile.
// A profile's `version` can be a loader id like "fabric-loader-0.19.3-26.2-pre-4";
// Modrinth needs the MC version, not that string, otherwise it returns no mods.
// ⚠ این دو تابع عمداً کپیِ عینِ نسخه‌ی دسکتاپ (src/app.js) هستند.
// دقیقاً همین باگ یک‌بار در دسکتاپ پیدا و رفع شده بود، ولی چون این فایل یک فورکِ جدا از
// app.jsِ دسکتاپ است، اصلاح هرگز به اندروید نرسید و کاربرانِ فورج/نئوفورج/کویلت ماه‌ها
// «هیچ افزودنی‌ای برای این نسخه نیست» می‌دیدند. هر تغییری اینجا باید در هر دو فایل انجام شود.
function stripLoaderFromVersion(s) {
  if (!s) return "";
  // fabric-loader-<loaderver>-<mcversion>  /  quilt-loader-<loaderver>-<mcversion>
  // نسخه‌ی لودر همیشه «رقم و نقطه» نیست: نسخه‌های Quilt همه شکلِ «0.20.0-beta.9» دارند و
  // فابریک هم pre/rc دارد. الگوی قبلی [\d.]+ فقط «0.20.0» را می‌گرفت و بقیه را نسخه‌ی بازی
  // می‌پنداشت → profVer می‌شد «beta.9-1.21.11»، که نه روی سرورِ ایران هست نه در مادرینث،
  // پس تبِ افزودنی‌ها برای هر پروفایلِ کویلت خالی درمی‌آمد. حالا به‌جای حدس‌زدنِ نسخه‌ی لودر،
  // نسخه‌ی بازی از **تهِ** شناسه گرفته می‌شود (رهاییِ ۱.۲۱.۱۱ / اسنپ‌شاتِ ۲۵w۱۴a / pre/rc).
  const MCV = String.raw`(?:\d+\.\d+(?:\.\d+)?|\d+w\d+[a-z]?)(?:[-_](?:pre|rc|snapshot)[\w.]*)?`;
  let m = s.match(new RegExp(String.raw`^(?:fabric|quilt)-loader-.+?-(${MCV})$`, "i"));
  if (m) return m[1];
  // forge/neoforge ids مثلِ "1.20.1-forge-47.2.0" یا "26.2-forge-65.0.3" → نسخه‌ی پیشرو
  m = s.match(/^(\d[\w.]*?)-(?:forge|neoforge)-/i);
  if (m) return m[1];
  m = s.match(/^(\d[\w.]*?)-(?:forge|neoforge)$/i);
  if (m) return m[1];
  // آپتی‌فاین idها مثلِ "1.21.11-OptiFine_HD_U_J9" → فقط نسخه‌ی بازیِ پیشرو. بدونِ این، جستجو/
  // لیستِ شیدر برای پروفایلِ آپتی‌فاین همیشه خالی بود (نسخه‌ای به‌اسمِ 1.21.11-OptiFine... وجود ندارد).
  m = s.match(/^(\d[\w.]*?)-OptiFine/i);
  if (m) return m[1];
  // NeoForge برخلافِ Forge پیشوندِ نسخه‌ی بازی ندارد: id مثلِ "neoforge-21.11.42" است و نسخه‌ی بازی
  // را در شماره‌ی بیلد کد می‌کند (A.B.C → MC 1.A.B، و اگر B==0 → 1.A). بدونِ این، profileMcVersion
  // برای هر پروفایلِ NeoForge رشته‌ی خالی برمی‌گرداند و جستجو/نصبِ ماد/شیدر با نسخه‌ی خالی خراب می‌شد
  // (مثلاً Iris/Sodiumِ نامتناسب نصب می‌شد → کرشِ «Iris requires Sodium»).
  m = s.match(/^neoforge-(\d+)\.(\d+)\.\d+/i);
  if (m) return m[2] === "0" ? `1.${m[1]}` : `1.${m[1]}.${m[2]}`;
  return /^\d/.test(s) ? s : "";
}
function profileMcVersion(prof) {
  if (!prof) return "";
  // base_version اسمش یعنی «خالص» ولی بعضی پروفایل‌ها (مثلاً فورج) همون شناسه‌ی ترکیبی رو
  // توش ذخیره کرده‌اند («26.2-forge-65.0.3»)؛ قبلاً اگر با رقم شروع می‌شد بدونِ‌ استریپ برگردانده
  // می‌شد → این شناسه‌ی ترکیبی مستقیم به‌عنوانِ «نسخه‌ی بازی» به مادرینث/CurseForge می‌رفت و چون
  // چنین نسخه‌ای اصلاً وجود ندارد، جستجو همیشه صفر نتیجه می‌داد.
  const fromBase = stripLoaderFromVersion(prof.base_version || "");
  if (fromBase) return fromBase;
  const v = String(prof.version || prof.base_version || "");
  let m = stripLoaderFromVersion(v);
  if (m) return m;
  return /^\d/.test(v) ? v : "";
}

Pages.mods = async (root) => {
  const profiles = await invoke("instance_list").catch(() => []);
  let kind = "mod";
  // The user's preferred category, independent of the temporary force-to-resourcepack
  // that a vanilla target imposes. Switching back to a loader profile restores this.
  let userKind = "mod";
  let subtab = "iran";

  const top = el("div", { class: "card" });
  const catChips = el("div", { class: "chips" });
  const catEls = {};
  CONTENT_KINDS.forEach(([id, label, ic]) => {
    const c = el("div", { class: "chip chip-ic" + (id === kind ? " active" : "") }, icon(ic, 14), el("span", { text: label }));
    c.addEventListener("click", () => { if (kind === id) return; kind = id; userKind = id; Object.values(catEls).forEach((x) => x.classList.remove("active")); c.classList.add("active"); renderSub(); });
    catEls[id] = c; catChips.appendChild(c);
  });
  top.appendChild(catChips);
  // مقصدِ نصب فقط پروفایل‌هاست (ماینکرفت اصلی حذف شده)
  const destOptions = profiles.length
    ? profiles.map((p) => ({ value: p.id, label: p.name }))
    : [{ value: "", label: "اول یک پروفایل بساز" }];
  // مقصدِ پیش‌فرض باید همان پروفایلی باشد که کاربر واقعاً با آن بازی می‌کند — همان
  // State.cfg.last_profile که دکمه‌ی «اجرای بازی» در صفحه‌ی خانه استفاده می‌کند.
  //
  // قبلاً روی profiles[0] قفل بود، و profiles[0] تقریباً همیشه همان پروفایلِ وانیلای
  // «Default» است که خودکار ساخته می‌شود و اولِ لیست می‌نشیند. چون مقصد وانیلا بود،
  // تب‌های «مادها» و «شیدرها» غیرفعال می‌شدند و فهرستِ سرور ایران هم روی نسخه‌ی همان
  // پروفایل (مثلاً ۱.۷.۱۰) فیلتر می‌شد — یعنی کاربری که پروفایلِ فورج/فبریکِ خودش را
  // داشت، صفحه را باز می‌کرد و ماد و شیدر اصلاً قابلِ انتخاب نبود. این دقیقاً همان
  // «نمی‌توانم ماد نصب کنم» است که گزارش می‌شد.
  //
  // اگر last_profile ست نشده بود، اولین پروفایلی که واقعاً لودر دارد را ترجیح می‌دهیم؛
  // وانیلا فقط آخرین انتخاب است.
  const _lastProf = State.cfg.last_profile && profiles.some((p) => p.id === State.cfg.last_profile)
    ? State.cfg.last_profile : "";
  const _loaderProf = (profiles.find((p) => p.loader && p.loader !== "vanilla") || {}).id || "";
  const destDefault = _lastProf || _loaderProf || (profiles[0] && profiles[0].id) || "";
  // changing the destination re-renders so the search prefills the profile's version/loader
  const destSel = dropdown({ options: destOptions, value: destDefault, placeholder: "انتخاب پروفایل", maxWidth: "340px", onChange: (v) => { if (v) setCfg("last_profile", v); renderSub(); } });
  top.appendChild(el("label", { class: "field", style: "margin-top:12px;max-width:340px" }, el("span", { text: "محل نصب" }), destSel));
  const subBar = el("div", { class: "srv-tabs", style: "margin-top:12px" });
  const subEls = {};
  // تبِ «سرور خارج (Modrinth)» فقط وقتی منبعِ دانلود روی «خارج» است نشان داده می‌شود؛ در حالتِ
  // ایران (پیش‌فرض) هیچ درخواستی به سایتِ خارجی زده نمی‌شود — فقط افزودنی‌های سرور ایران.
  const _subTabs = usingIran()
    ? [["iran", "سرور ایران", "home"], ["installed", "نصب‌شده‌ها", "check"]]
    : [["iran", "سرور ایران", "home"], ["search", "سرور خارج (Modrinth)", "search"], ["installed", "نصب‌شده‌ها", "check"]];
  _subTabs.forEach(([id, label, ic]) => {
    const b = el("div", { class: "srv-tab" + (id === subtab ? " active" : "") }, icon(ic, 16), el("span", { text: label }));
    b.addEventListener("click", () => { subtab = id; Object.values(subEls).forEach((x) => x.classList.remove("active")); b.classList.add("active"); renderSub(); });
    subEls[id] = b; subBar.appendChild(b);
  });
  top.appendChild(subBar);
  root.appendChild(top);

  const mbody = el("div", { class: "srv-body", style: "margin-top:14px" });
  root.appendChild(mbody);

  function renderSub() {
    const a = $("#pageArea"); if (a._scroll) { a.removeEventListener("scroll", a._scroll); a._scroll = null; }
    // Vanilla profiles cannot run mods/shaders (no loader) — only resource packs.
    // Disable those categories and force the selection when a vanilla profile is the target.
    const prof = profiles.find((p) => p.id === destSel.getValue());
    const vanilla = !!prof && prof.loader === "vanilla";
    // آپتی‌فاین یک مادلودرِ واقعی نیست (مثلِ Fabric/Forge) — ماد/جارِ معمولی روش نصب نمی‌شه، فقط
    // شیدر و ریسورس‌پک. قبلاً «optifine» به‌اشتباه به‌عنوانِ لودر برای جستجوی ماد فرستاده می‌شد که
    // چون مادرینث چنین دسته‌ای ندارد همیشه نتیجه‌ی خالی می‌داد.
    const optifine = !!prof && prof.loader === "optifine";
    CONTENT_KINDS.forEach(([id]) => {
      const elc = catEls[id];
      const blocked = (vanilla && id !== "resourcepack") || (optifine && id === "mod");
      elc.classList.toggle("disabled", blocked);
      elc.style.pointerEvents = blocked ? "none" : "";
      elc.style.opacity = blocked ? "0.4" : "";
    });
    // Vanilla → force resourcepack (only thing that runs). آپتی‌فاین → شیدر (چیزی که واقعاً
    // برایش نصب می‌کنی). Loader profile → restore the user's preferred category.
    kind = vanilla ? "resourcepack" : (optifine && userKind === "mod") ? "shader" : userKind;
    Object.entries(catEls).forEach(([k, x]) => x.classList.toggle("active", k === kind));
    mbody.innerHTML = "";
    if (vanilla) mbody.appendChild(el("p", { class: "muted", style: "margin-bottom:12px;display:flex;align-items:center;gap:6px" }, icon("info", 13),
      el("span", { text: "پروفایل مقصد وانیلا است و لودر ندارد؛ پس فقط ریسورس‌پک قابل نصب است. برای ماد یا شیدر یک پروفایل با لودر (Fabric/Forge/…) بساز." })));
    if (optifine) mbody.appendChild(el("p", { class: "muted", style: "margin-bottom:12px;display:flex;align-items:center;gap:6px" }, icon("info", 13),
      el("span", { text: "آپتی‌فاین خودش یک مادلودر نیست؛ فقط شیدر و ریسورس‌پک روش نصب می‌شه (نه مادِ معمولی)." })));
    if (subtab === "installed") renderInstalled();
    else if (subtab === "iran") {
      const prof = profiles.find((p) => p.id === destSel.getValue());
      const profVer = prof ? profileMcVersion(prof) : "";
      const profLoader = prof ? (prof.loader === "vanilla" ? "" : (prof.loader || "")) : "";
      renderIranAddons(mbody, kind, profVer, profLoader, destSel.getValue());
    }
    else renderSearch();
  }

  async function renderInstalled() {
    const ic = CONTENT_KINDS.find((c) => c[0] === kind)[2];
    const card = el("div", { class: "card" });
    card.appendChild(el("div", { class: "row spread" }, secTitle("نصب‌شده‌ها", ic), btn(null, "refresh", "btn btn-sm btn-icon", { onclick: renderInstalled })));
    card.querySelector(".section-title").style.margin = "0";
    mbody.appendChild(card);
    const list = await invoke("content_installed", { kind, instance: destSel.getValue() || null }).catch(() => []);
    if (list.length === 0) card.appendChild(el("div", { class: "dim", style: "margin-top:10px", text: "چیزی نصب نشده." }));
    else list.forEach((m) => card.appendChild(el("div", { class: "list-item" },
      el("span", { class: "li-ico" }, icon(ic, 18)),
      el("div", { style: "flex:1" }, el("div", { style: "font-weight:600", text: m.name.replace(".disabled", "") }), el("div", { class: "dim", text: fmtBytes(m.size) })),
      m.enabled ? tag("فعال", "tag green") : tag("غیرفعال", "tag gray"),
      btn(m.enabled ? "غیرفعال" : "فعال", m.enabled ? "x" : "check", "btn btn-sm", { onclick: async () => { await invoke("mods_toggle", { path: m.path, enabled: !m.enabled }); renderInstalled(); } }),
      btn("حذف", "trash", "btn btn-sm btn-danger", { onclick: () => confirmDialog("حذف", m.name + " حذف شود؟", async () => { await invoke("mods_delete", { path: m.path }); renderInstalled(); }) }))));
  }

  function renderSearch() {
    const sCard = el("div", { class: "card" });
    // منبعِ «سرورِ خارج»: مادرینث (پیش‌فرض) یا CurseForge — کاربر صریحاً خواسته CurseForge هم
    // به‌عنوان یک منبعِ دومِ کاملاً مجزا اضافه شود (نه جایگزینِ مادرینث).
    let source = "modrinth";
    const srcRow = el("div", { class: "chips", style: "margin-bottom:10px" });
    const srcM = el("div", { class: "chip chip-ic active" }, el("span", { text: "Modrinth" }));
    const srcC = el("div", { class: "chip chip-ic" }, el("span", { text: "CurseForge" }));
    srcRow.appendChild(srcM); srcRow.appendChild(srcC);
    sCard.appendChild(srcRow);
    const sRow = el("div", { class: "row" });
    // if installing into a profile, lock onto that profile's version + loader so only
    // compatible mods show; warn the user if they override it.
    const prof = profiles.find((p) => p.id === destSel.getValue());
    const profVer = prof ? profileMcVersion(prof) : "";
    const profLoader = prof ? (prof.loader === "vanilla" ? "" : (prof.loader || "")) : "";
    // این تابع فقط تبِ «سرور خارج» را رندر می‌کند؛ سرورِ ایران تبِ جدای خودش را دارد (renderIranAddons).
    const sv = State.cfg.selected_version || "";
    const cleanVer = prof ? profVer : (/^\d/.test(sv) ? sv : "");
    const q = el("input", { class: "input", style: "flex:1", placeholder: "جستجو..." });
    const mcv = el("input", { class: "input", style: "max-width:120px", placeholder: "نسخه", value: cleanVer });
    const loaderOpts = [["", "همه لودرها"], ["fabric", "Fabric"], ["forge", "Forge"], ["quilt", "Quilt"], ["neoforge", "NeoForge"]].map(([value, label]) => ({ value, label }));
    // «optifine» هیچ‌وقت دسته‌ی معتبری برای جستجوی مادرینث نیست (مادلودر نیست) — اگر پروفایل
    // آپتی‌فاین بود، فیلترِ لودر را خالی بگذار (نه اینکه یه دسته‌ی ناموجود به مادرینث بفرستیم که
    // همیشه نتیجه‌ی خالی می‌داد).
    const loader = dropdown({ options: loaderOpts, value: profLoader === "optifine" ? "" : profLoader, placeholder: "همه لودرها", maxWidth: "150px", onChange: () => { warnIfChanged(); liveSearch(); } });
    sRow.appendChild(q);
    // نسخه‌ی بازی برای همه‌ی انواع (ماد/شیدر/ریسورس‌پک) — چون همه بر اساسِ نسخه‌ی بازی
    // سازگاری دارند. لودر فقط برای ماد معنی دارد (شیدر/ریسورس‌پک وابسته به لودر نیستند).
    sRow.appendChild(mcv);
    if (kind === "mod") { sRow.appendChild(loader); }
    const goBtn = btn("جستجو", "search", "btn btn-primary"); sRow.appendChild(goBtn);
    sCard.appendChild(sRow);
    if (prof && kind === "mod") {
      const lbl = loaderLabel(prof);
      sCard.appendChild(el("p", { class: "muted", style: "margin-top:10px;display:flex;align-items:center;gap:6px" }, icon("info", 13),
        el("span", { text: `این پروفایل «${prof.name}» با ${lbl}${profVer ? " نسخه " + profVer : ""} است؛ فقط ماد‌های سازگار نمایش داده می‌شوند. اگر نسخه/لودر را تغییر دهی، ماد ممکن است ناسازگار باشد.` })));
    }
    let warned = false;
    function warnIfChanged() {
      if (!prof || warned) return;
      if ((loader.getValue() || "") !== profLoader || mcv.value !== profVer) {
        const lbl = loaderLabel(prof);
        toast(`هشدار: این پروفایل ${lbl}${profVer ? " " + profVer : ""} را پشتیبانی می‌کند — ماد ناسازگار ممکن است کار نکند`, "");
        warned = true;
      }
    }
    const results = el("div", { class: "mod-grid", style: "margin-top:14px" });
    sCard.appendChild(results);
    mbody.appendChild(sCard);
    function modrinthCard(h) {
      const cats = (h.categories || []).map(c => c.toLowerCase());
      const loaders = ["fabric", "forge", "quilt", "neoforge"].filter(l => cats.includes(l));
      // مادرینث «نسخه‌ی لودر» مجزا ندارد (فقط نام لودر + لیستِ نسخه‌های بازیِ پشتیبانی‌شده)؛
      // پس کنارِ نامِ لودر، بازه‌ی نسخه‌های بازیِ پشتیبانی‌شده را هم نشان می‌دهیم تا سازگاریِ
      // واقعی روشن‌تر باشد — قبلاً فقط نام لودر بدونِ هیچ نسخه‌ای نشان داده می‌شد.
      const vers = Array.isArray(h.versions) ? h.versions.filter((v) => /^\d/.test(v)) : [];
      const verRange = vers.length ? (vers.length > 1 ? `${vers[0]} – ${vers[vers.length - 1]}` : vers[0]) : "";
      const loaderText = loaders.length ? `لودر: ${loaders.join(", ")}` : "";
      const verText = verRange ? `نسخه‌های بازی: ${verRange}` : "";
      return el("div", { class: "card mod-card" },
        el("div", { class: "mc-top" }, contentThumb(h.icon_url, "puzzle"), el("div", { class: "mc-title", text: h.title })),
        el("div", { class: "mc-desc", text: h.description || "" }),
        (loaderText || verText) ? el("div", { class: "dim", style: "font-size:11px;margin-top:2px;display:flex;flex-direction:column;gap:1px" },
          loaderText ? el("span", { text: loaderText }) : null,
          verText ? el("span", { text: verText }) : null) : null,
        el("div", { class: "row spread" },
          el("span", { class: "dim dl-count" }, icon("download", 13), el("span", { text: (h.downloads || 0).toLocaleString("fa-IR") })),
          (() => {
            // اگر همین مورد از قبل در حال نصب است (کاربر تب را عوض کرده و کارت دوباره ساخته شده)
            // دکمه را در حالتِ «در حال نصب» و غیرفعال نشان بده تا لودینگ گم نشود.
            const installing = _installingIds.has(String(h.project_id || h.slug || ""));
            const b = btn(installing ? "در حال نصب…" : "نصب", installing ? null : "download", "btn btn-sm btn-primary",
              { onclick: (e) => installContent(h, e.currentTarget, kind, mcv.value, loader.getValue(), destSel.getValue()) });
            if (installing) { b.disabled = true; b.innerHTML = '<span class="spinner"></span>'; }
            return b;
          })()));
    }
    function curseforgeCard(m) {
      const icoUrl = m.logo && m.logo.thumbnailUrl ? m.logo.thumbnailUrl : "";
      const idx = Array.isArray(m.latestFilesIndexes) ? m.latestFilesIndexes : [];
      const gvs = [...new Set(idx.map((i) => i.gameVersion).filter((v) => /^\d/.test(v || "")))];
      const verText = gvs.length ? `نسخه‌های بازی: ${gvs.slice(0, 4).join(", ")}` : "";
      const key = "cf:" + String(m.id);
      return el("div", { class: "card mod-card" },
        el("div", { class: "mc-top" }, contentThumb(icoUrl, "puzzle"), el("div", { class: "mc-title", text: m.name })),
        el("div", { class: "mc-desc", text: m.summary || "" }),
        verText ? el("div", { class: "dim", style: "font-size:11px;margin-top:2px", text: verText }) : null,
        el("div", { class: "row spread" },
          el("span", { class: "dim dl-count" }, icon("download", 13), el("span", { text: Math.round(m.downloadCount || 0).toLocaleString("fa-IR") })),
          (() => {
            const installing = _installingIds.has(key);
            const b = btn(installing ? "در حال نصب…" : "نصب", installing ? null : "download", "btn btn-sm btn-primary",
              { onclick: (e) => installCurseforgeContent(m, e.currentTarget, kind, mcv.value, loader.getValue(), destSel.getValue()) });
            if (installing) { b.disabled = true; b.innerHTML = '<span class="spinner"></span>'; }
            return b;
          })()));
    }
    let search = null;
    function buildSearch() {
      results.innerHTML = "";
      if (source === "modrinth") {
        search = setupInfiniteSearch({
          resultsEl: results,
          getParams: () => ({ query: q.value, mcVersion: mcv.value, loader: kind === "mod" ? loader.getValue() : "", category: "", projectType: kind }),
          cardFn: modrinthCard,
        });
      } else {
        search = setupInfiniteSearch({
          resultsEl: results,
          cmd: "curseforge_search",
          itemsOf: (data) => data.data || [],
          totalOf: (data) => (data.pagination && data.pagination.totalCount != null) ? data.pagination.totalCount : Infinity,
          getParams: () => ({ query: q.value, mcVersion: mcv.value, loader: kind === "mod" ? loader.getValue() : "", kind }),
          cardFn: curseforgeCard,
        });
      }
      search.reset();
    }
    function switchSource(s) {
      if (source === s) return;
      source = s;
      srcM.classList.toggle("active", s === "modrinth");
      srcC.classList.toggle("active", s === "curseforge");
      buildSearch();
    }
    srcM.addEventListener("click", () => switchSource("modrinth"));
    srcC.addEventListener("click", () => switchSource("curseforge"));
    goBtn.addEventListener("click", () => search.reset());
    q.addEventListener("keydown", (e) => { if (e.key === "Enter") search.reset(); });
    const liveSearch = debounce(() => search.reset(), 350);
    q.addEventListener("input", liveSearch);
    mcv.addEventListener("input", () => { warnIfChanged(); liveSearch(); });
    buildSearch();
  }

  renderSub();
};

// Run a Modrinth install (mod/shader/resourcepack) showing a live progress modal
// with a real cancel button. Returns the result, or null if the user cancelled.
let _dlSeq = 0;
// نصب با نوار پیشرفتِ سراسری در هدر (به‌جای مودالِ مسدودکننده) — کاربر می‌تواند آزادانه
// بین تب‌ها جابه‌جا شود و همچنان ببیند چه چیزی در حال نصب است.
async function installWithProgress(title, cmd, args) {
  const token = "dl-" + (++_dlSeq) + "-" + Date.now();
  Install.start(title, token);
  // پیشرفتِ مخصوصِ این توکن (برای نصب‌های هم‌زمان) → نوار هدر
  let unsub = null;
  try { unsub = await listen("download://status", (e) => { const p = e.payload; if (!p || p.token !== token) return; if (p.label != null) Install.label(p.label); if (p.pct != null) Install.pct(p.pct); }); } catch (_) {}
  try {
    return await invoke(cmd, { ...args, token });
  } catch (e) {
    if (String(e).includes("لغو")) { toast("دانلود لغو شد", ""); return null; }
    throw e;
  } finally {
    try { unsub && unsub(); } catch (_) {}
    Install.end();
  }
}

// keyهای محتوایی که هم‌اکنون در حال نصب‌اند (نسخه/لودر/مودپک/ماد) — تا اگر کاربر تب را عوض
// کرد و کارت‌ها دوباره ساخته شدند، دکمه‌ی همان مورد باز هم «در حال نصب» و غیرفعال نشان داده
// شود (نه اینکه انگار نصب نمی‌شود و دوباره کلیک شود → نصبِ دوتایی).
const _installingIds = new Set();
// یک دکمه‌ی نصب که خودش وضعیتِ در-حال-نصب را از _installingIds می‌خواند. اگر آن key
// هم‌اکنون در حال نصب است، به‌جای «نصب» اسپینر + غیرفعال نشان می‌دهد.
function installBtnFor(key, onclick, label) {
  const inst = key && _installingIds.has(key);
  const b = btn(inst ? "در حال نصب…" : (label || "نصب"), inst ? null : "download", "btn btn-sm btn-primary", { onclick });
  if (inst) { b.disabled = true; b.innerHTML = '<span class="spinner"></span>'; }
  return b;
}
// نامِ ماد/لودرِ شیدر برای هر مادلودر — بدونِ آپتی‌فاین، شیدر فقط با یکی از این‌ها روی بازی
// اعمال می‌شود. Iris برای Fabric/Quilt، Oculus برای Forge/NeoForge (پورتِ نگه‌داشته‌شده‌ی Iris).
const SHADER_LOADER_MOD = {
  fabric: { slug: "iris", name: "Iris" },
  quilt: { slug: "iris", name: "Iris" },
  forge: { slug: "oculus", name: "Oculus" },
  neoforge: { slug: "oculus", name: "Oculus" },
};
// اگه پروفایل آپتی‌فاین نیست، قبل از نصبِ شیدر یادآوری کن که ماد بارگذاریِ شیدر هم لازمه — با
// یه پاپ‌آپِ ۲ تبی (سرور ایران پیش‌فرض / سرور خارج) که فقط مادهای هم‌نسخه/هم‌لودر رو نشون می‌ده.
// resolve وقتی popup بسته شد (چه کاربر کاری کرد چه فقط بستش) تا caller ادامه‌ی نصبِ شیدر رو بزنه.
function shaderLoaderGate(loader, mcv, destId) {
  return new Promise((resolve) => {
    if (loader === "optifine" || !loader) { resolve(); return; }
    const info = SHADER_LOADER_MOD[loader];
    const body = el("div", {});
    body.appendChild(el("p", { class: "muted", style: "margin-bottom:10px" },
      el("span", { text: `این پروفایل از OptiFine استفاده نمی‌کند — برای اینکه شیدر واقعاً روی بازی اعمال شود، باید ماد بارگذاریِ شیدر (${info ? info.name : "Iris/Oculus"}) را هم نصب کنی.` })));
    const tabs = el("div", { class: "chips", style: "margin-bottom:10px" });
    const tIran = el("div", { class: "chip chip-ic active" }, icon("home", 14), el("span", { text: "سرور ایران" }));
    const tExt = el("div", { class: "chip chip-ic" }, icon("globe", 14), el("span", { text: "سرور خارج" }));
    tabs.appendChild(tIran); tabs.appendChild(tExt);
    body.appendChild(tabs);
    const listArea = el("div", { class: "mod-grid", style: "max-height:280px;overflow:auto" });
    body.appendChild(listArea);
    body.appendChild(el("p", { class: "muted", style: "margin-top:10px;font-size:12px;display:flex;gap:6px;align-items:flex-start" },
      icon("info", 13), el("span", { text: "بعدِ نصبِ شیدر و مادِ بارگذاری، حتماً از تنظیماتِ ویدیوی بازی (Video Settings) گزینه‌ی شیدر رو انتخاب/فعال کن." })));

    async function loadIran() {
      listArea.innerHTML = "";
      listArea.appendChild(el("div", { class: "row", style: "justify-content:center;padding:14px;grid-column:1/-1" }, el("span", { class: "spinner" })));
      let files = [];
      try { files = await invoke("iran_addon_list", { kind: "mod", version: mcv }); } catch (_) {}
      const loaderPref = loader + "/";
      const words = ["iris", "oculus"];
      const items = files.filter((f) => f.toLowerCase().startsWith(loaderPref) && words.some((w) => f.toLowerCase().includes(w)));
      listArea.innerHTML = "";
      if (!items.length) { listArea.appendChild(el("div", { class: "dim", style: "padding:14px;grid-column:1/-1", text: "روی سرورِ ایران مادِ بارگذاریِ شیدر برای این لودر/نسخه نیست." })); return; }
      items.forEach((rel) => {
        const name = rel.split("/").pop();
        listArea.appendChild(el("div", { class: "card mod-card" },
          el("div", { class: "mc-top" }, icon("sun", 18), el("div", { class: "mc-title", text: name })),
          btn("نصب", "download", "btn btn-sm btn-primary", { onclick: (e) => installIranAddon("mod", mcv, rel, destId, e.currentTarget) })));
      });
    }
    function loadExternal() {
      listArea.innerHTML = "";
      if (!info) { listArea.appendChild(el("div", { class: "dim", style: "padding:14px;grid-column:1/-1", text: "این لودر مادِ بارگذاریِ شیدرِ شناخته‌شده‌ای ندارد." })); return; }
      listArea.appendChild(el("div", { class: "card mod-card" },
        el("div", { class: "mc-top" }, icon("sun", 18), el("div", { class: "mc-title", text: info.name })),
        el("div", { class: "dim", text: `نسخه ${mcv} · ${loader}` }),
        btn("نصب " + info.name, "download", "btn btn-sm btn-primary", { onclick: (e) => installContent({ project_id: info.slug, title: info.name }, e.currentTarget, "mod", mcv, loader, destId) })));
    }
    tIran.addEventListener("click", () => { if (tIran.classList.contains("active")) return; tIran.classList.add("active"); tExt.classList.remove("active"); loadIran(); });
    tExt.addEventListener("click", () => { if (tExt.classList.contains("active")) return; tExt.classList.add("active"); tIran.classList.remove("active"); loadExternal(); });
    loadIran();

    const dlg = modal({
      title: "لازمِ نصبِ شیدر", body,
      actions: [btn("متوجه شدم، ادامه بده", "check", "btn", { onclick: () => dlg.close() })],
      onClose: () => resolve(),
    });
  });
}
// اگر مقصدِ نصب یک پروفایلِ واقعی است، نسخه‌ی بازی/لودرِ همان پروفایل را جایگزینِ چیزی
// می‌کند که کاربر در فیلترهای جستجو انتخاب کرده — چون آن فیلترها فقط برای *مرور* هستند (مثلاً
// می‌شود «همه‌ی لودرها» را برای دیدنِ نتایجِ بیشتر انتخاب کرد) و اگر همان مقدارِ فیلتر بدونِ
// تغییر مستقیم به نصب برود، ممکن است مادِ لودرِ دیگری (یا نسخه‌ی دیگرِ بازی) نصب/دانلود شود که
// با پروفایل ناسازگار است. این دقیقاً باگِ «ورژنِ مادی که لود می‌کنه با ورژنِ لودرمون یکی نیست».
function destOverride(kind, mcv, loader, destId) {
  const prof = (State.profiles || []).find((p) => p.id === destId);
  if (!prof) return { mcv, loader };
  const profVer = profileMcVersion(prof);
  const profLoader = prof.loader === "vanilla" ? "" : (prof.loader || "");
  const outMcv = profVer || mcv;
  const outLoader = (kind === "mod" && profLoader && profLoader !== "optifine") ? profLoader : loader;
  return { mcv: outMcv, loader: outLoader };
}
async function installContent(h, btnEl, kind, mcv, loader, destId) {
  ({ mcv, loader } = destOverride(kind, mcv, loader, destId));
  if (kind === "shader") { await shaderLoaderGate(loader, mcv, destId); }
  const iid = String(h.project_id || h.slug || "");
  const old = btnEl.innerHTML;
  btnEl.disabled = true; btnEl.innerHTML = '<span class="spinner"></span>';
  if (iid) _installingIds.add(iid);
  try {
    const res = await installWithProgress("نصب " + (h.title || "محتوا"), "content_install", { projectId: h.project_id || h.slug, mcVersion: kind === "mod" ? mcv : "", loader: kind === "mod" ? loader : "", kind, instance: destId || null });
    if (res === null) { btnEl.disabled = false; btnEl.innerHTML = old; return; } // cancelled
    const where = "پروفایل";
    toast(`نصب شد در ${where}`, "success"); btnEl.innerHTML = ""; btnEl.appendChild(icon("check", 14)); btnEl.appendChild(el("span", { text: "نصب شد" }));
  } catch (e) { toast("خطا: " + e, "error"); btnEl.disabled = false; btnEl.innerHTML = old; }
  finally { if (iid) _installingIds.delete(iid); }
}

// نصبِ یک آیتم از CurseForge (شکلِ داده و شناسه‌ی عددی‌اش با مادرینث فرق دارد، پس مسیرِ
// نصبِ جدا دارد؛ ولی از همان الگوی پیشرفت/لغو و شیدر-گیت استفاده می‌کند).
async function installCurseforgeContent(m, btnEl, kind, mcv, loader, destId) {
  ({ mcv, loader } = destOverride(kind, mcv, loader, destId));
  if (kind === "shader") { await shaderLoaderGate(loader, mcv, destId); }
  const iid = "cf:" + String(m.id);
  const old = btnEl.innerHTML;
  btnEl.disabled = true; btnEl.innerHTML = '<span class="spinner"></span>';
  _installingIds.add(iid);
  try {
    const res = await installWithProgress("نصب " + (m.name || "محتوا"), "curseforge_install", { modId: m.id, mcVersion: kind === "mod" ? mcv : "", loader: kind === "mod" ? loader : "", kind, instance: destId || null });
    if (res === null) { btnEl.disabled = false; btnEl.innerHTML = old; return; } // cancelled
    toast("نصب شد در پروفایل", "success"); btnEl.innerHTML = ""; btnEl.appendChild(icon("check", 14)); btnEl.appendChild(el("span", { text: "نصب شد" }));
  } catch (e) { toast("خطا: " + e, "error"); btnEl.disabled = false; btnEl.innerHTML = old; }
  finally { _installingIds.delete(iid); }
}

// نصبِ یک مودپکِ سرورِ ایران (دانلودِ instanceِ خودکفا با مودالِ پیشرفت + لغو).
async function installIranModpack(m, btnEl) {
  if (!m.version_id) { toast("اطلاعاتِ نسخه‌ی این مودپک ناقص است.", "error"); return; }
  const _k = "mp:" + (m.slug || m.name || "");
  promptInput("نصب مودپک", "نام پروفایل", async (name) => {
    const old = btnEl.innerHTML;
    btnEl.disabled = true; btnEl.innerHTML = '<span class="spinner"></span>';
    _installingIds.add(_k);
    setStatus("نصب مودپک از سرور ایران...");
    try {
      const inst = await installWithProgress("نصب مودپک: " + m.name, "iran_modpack_install", {
        slug: m.slug, name, versionId: m.version_id, base: m.mc || "",
        loader: m.loader || "vanilla", loaderVersion: m.loader_version || "",
      });
      setStatus("آماده");
      if (inst === null) { btnEl.disabled = false; btnEl.innerHTML = old; return; } // لغو شد
      toast("مودپک نصب شد", "success"); openInstancePanel(inst);
    } catch (e) { toast("خطا: " + e, "error"); setStatus("آماده"); btnEl.disabled = false; btnEl.innerHTML = old; }
    finally { _installingIds.delete(_k); }
  }, m.name);
}

// مرورگرِ افزودنی‌های سرورِ ایران: برای نسخهٔ پروفایلِ مقصد، jarهای موجودِ CDN را لیست می‌کند.
async function renderIranAddons(mbody, kind, profVer, profLoader, destId) {
  const ic = kind === "shader" ? "sun" : kind === "resourcepack" ? "image" : "puzzle";
  const card = el("div", { class: "card" });
  card.appendChild(secTitle("افزودنی‌های سرور ایران", ic));
  mbody.appendChild(card);
  if (!destId) { card.appendChild(el("div", { class: "dim", style: "margin-top:10px", text: "اول یک پروفایلِ مقصد (با نسخه و لودر) بساز/انتخاب کن." })); return; }
  if (!profVer) { card.appendChild(el("div", { class: "dim", style: "margin-top:10px", text: "نسخهٔ این پروفایل مشخص نیست." })); return; }
  card.appendChild(el("p", { class: "muted", style: "margin:8px 0 12px", text: `نسخه ${profVer}${profLoader ? " · " + profLoader : ""} — فقط افزودنی‌های همین نسخه از سرورِ ایران.` }));
  const grid = el("div", { class: "mod-grid" });
  card.appendChild(grid);
  grid.appendChild(el("div", { class: "row", style: "justify-content:center;padding:20px;grid-column:1/-1" }, el("span", { class: "spinner" })));
  let files = [];
  try { files = await invoke("iran_addon_list", { kind, version: profVer }); } catch (_) { files = []; }
  // «optifine» زیرپوشه‌ی خودش را روی سرورِ ایران ندارد (فقط fabric/forge/quilt/neoforge) — برای
  // چنین پروفایلی فیلترِ لودر را نادیده بگیر (نه اینکه همه‌چیز را رد کنیم).
  const loaderPref = (kind === "mod" && profLoader && profLoader !== "optifine") ? profLoader + "/" : null;
  const items = files.filter((f) => {
    if (kind !== "mod") return !f.includes("/");          // ریسورس‌پک/شیدر: فقط ریشه
    if (!f.includes("/")) return true;                     // jarهای ریشه (لودرناوابسته/modloader)
    return loaderPref && f.startsWith(loaderPref);         // فقط زیرپوشه‌ی لودرِ پروفایل
  });
  grid.innerHTML = "";
  if (!items.length) { grid.appendChild(el("div", { class: "dim", style: "padding:14px;grid-column:1/-1", text: "برای این نسخه/لودر افزودنی‌ای روی سرورِ ایران نیست." })); return; }
  const q = el("input", { class: "input", style: "margin-bottom:12px", placeholder: "فیلترِ نام..." });
  card.insertBefore(q, grid);
  // ناظرِ دید: کارت که نزدیکِ نما شد، متادیتایش گرفته می‌شود و بعد رهایش می‌کنیم.
  const iconObserver = window.IntersectionObserver ? new IntersectionObserver((entries, obs) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      obs.unobserve(entry.target);
      const x = entry.target._iranIcon;
      if (x) resolveIranAddonIcon(entry.target, x.rel, kind, profVer, profLoader, x.titleEl, x.descEl);
    });
  }, { rootMargin: "240px" }) : null;
  const draw = (flt) => {
    grid.innerHTML = "";
    const f = lc(flt || "");
    items.filter((r) => !f || lc(r).includes(f)).slice(0, 400).forEach((rel) => {
      const name = rel.split("/").pop();
      // آیکون/عنوان/توضیح تنبل پر می‌شوند: هر کارت یک جستجوی متادیتا لازم دارد و
      // این فهرست صدها ردیف است، پس فقط آن‌هایی که به دید می‌آیند جستجو می‌شوند.
      const thumb = contentThumb("", ic);
      const titleEl = el("div", { class: "mc-title", text: addonSearchName(name) || name });
      const descEl = el("div", { class: "mc-desc", style: "display:none" });
      if (iconObserver) iconObserver.observe(thumb);
      else resolveIranAddonIcon(thumb, rel, kind, profVer, profLoader, titleEl, descEl);
      thumb._iranIcon = { rel, titleEl, descEl };
      grid.appendChild(el("div", { class: "card mod-card" },
        el("div", { class: "mc-top" }, thumb, titleEl),
        descEl,
        el("div", { class: "row spread" },
          el("span", { class: "dim", text: profVer + (profLoader ? " · " + profLoader : "") }),
          btn("نصب", "download", "btn btn-sm btn-primary", { onclick: async (e) => {
            if (kind === "shader") await shaderLoaderGate(profLoader, profVer, destId);
            installIranAddon(kind, profVer, rel, destId, e.currentTarget);
          } }))));
    });
  };
  draw("");
  q.addEventListener("input", debounce(() => draw(q.value), 200));
}

async function installIranAddon(kind, version, rel, destId, btnEl) {
  const old = btnEl.innerHTML;
  btnEl.disabled = true; btnEl.innerHTML = '<span class="spinner"></span>';
  try {
    const r = await installWithProgress("نصب افزودنی از سرور ایران", "iran_content_install",
      { kind, version, rel, instance: destId || null });
    if (r === null) { btnEl.disabled = false; btnEl.innerHTML = old; return; }
    toast("نصب شد", "success"); btnEl.innerHTML = ""; btnEl.appendChild(icon("check", 14)); btnEl.appendChild(el("span", { text: "نصب شد" }));
  } catch (e) { toast("خطا: " + e, "error"); btnEl.disabled = false; btnEl.innerHTML = old; }
}

// مودپک‌های سرورِ ایران (از iran-index.modpacks) — لیست + جستجو روی نام.
async function renderIranModpacks(root) {
  await loadIranIndex();
  const list = (_iranIdx && Array.isArray(_iranIdx.modpacks)) ? _iranIdx.modpacks : [];
  const card = el("div", { class: "card" });
  card.appendChild(secTitle("مودپک‌های سرور ایران", "gift"));
  card.appendChild(el("p", { class: "muted", style: "margin-bottom:12px",
    text: `${faNum(list.length)} مودپکِ آماده روی سرورِ ایران (مرتب‌شده بر اساسِ محبوبیت).` }));
  const q = el("input", { class: "input", placeholder: "نام مودپک..." });
  card.appendChild(q);
  const grid = el("div", { class: "mod-grid", style: "margin-top:14px" });
  card.appendChild(grid);
  root.appendChild(card);
  const render = (flt) => {
    grid.innerHTML = "";
    const f = lc(flt || "");
    const shown = list.filter((m) => !f || lc(m.name).includes(f)).slice(0, 200);
    if (!shown.length) { grid.appendChild(el("div", { class: "dim", style: "padding:14px", text: "چیزی پیدا نشد." })); return; }
    shown.forEach((m) => {
      grid.appendChild(el("div", { class: "card mod-card" },
        el("div", { class: "mc-top" },
          contentThumb(m.icon, "gift"),
          el("div", { class: "mc-title", text: m.name })),
        el("div", { class: "mc-desc", text: `ماینکرفت ${m.mc || "؟"} · ${m.loader || "?"}${m.loader_version ? " " + m.loader_version : ""}` }),
        el("div", { class: "row spread" },
          el("span", { class: "dim", text: `${faNum(m.mods || 0)} ماد` }),
          installBtnFor("mp:" + (m.slug || m.name || ""), (e) => installIranModpack(m, e.currentTarget)))));
    });
  };
  render("");
  q.addEventListener("input", debounce(() => render(q.value), 250));
}

// ── Modpacks (Modrinth → installs as an instance) ──────────
Pages.modpacks = async (root) => {
  // ۲ تب: سرورِ ایران (پیش‌فرض — کاملاً آفلاین/بدونِ فیلترشکن) و سرورِ خارج (Modrinth، جستجوی کامل).
  const srcTabs = el("div", { class: "chips", style: "margin-bottom:12px" });
  const tabIran = el("div", { class: "chip chip-ic active" }, icon("home", 14), el("span", { text: "سرور ایران" }));
  const tabExt = el("div", { class: "chip chip-ic" }, icon("globe", 14), el("span", { text: "سرور خارج (Modrinth)" }));
  // تبِ Modrinth فقط در حالتِ «سرور خارج» — در حالتِ ایران (پیش‌فرض) هیچ درخواستِ خارجی زده نمی‌شود.
  srcTabs.appendChild(tabIran); if (!usingIran()) srcTabs.appendChild(tabExt);
  root.appendChild(srcTabs);
  const iranBody = el("div", {});
  const extBody = el("div", { style: "display:none" });
  root.appendChild(iranBody); root.appendChild(extBody);
  let extLoaded = false;
  tabIran.addEventListener("click", () => {
    if (tabIran.classList.contains("active")) return;
    tabIran.classList.add("active"); tabExt.classList.remove("active");
    iranBody.style.display = ""; extBody.style.display = "none";
  });
  tabExt.addEventListener("click", () => {
    if (tabExt.classList.contains("active")) return;
    tabExt.classList.add("active"); tabIran.classList.remove("active");
    iranBody.style.display = "none"; extBody.style.display = "";
    if (!extLoaded) { extLoaded = true; renderExternalModpacks(extBody); }
  });
  await renderIranModpacks(iranBody);
};

async function renderExternalModpacks(root) {
  const sCard = el("div", { class: "card" });
  sCard.appendChild(secTitle("مودپک‌ها (Modrinth)", "gift"));
  sCard.appendChild(el("p", { class: "muted", style: "margin-bottom:12px", text: "با زدن «نصب»، مودپک به‌صورت یک پروفایل جدید با همه‌ی ماد‌ها و تنظیماتش نصب می‌شود." }));
  const sRow = el("div", { class: "row" });
  const q = el("input", { class: "input", style: "flex:1", placeholder: "نام مودپک..." });
  const goBtn = btn("جستجو", "search", "btn btn-primary");
  sRow.appendChild(q); sRow.appendChild(goBtn);
  sCard.appendChild(sRow);
  const results = el("div", { class: "mod-grid", style: "margin-top:14px" });
  sCard.appendChild(results);
  root.appendChild(sCard);

  const search = setupInfiniteSearch({
    resultsEl: results,
    getParams: () => ({ query: q.value, mcVersion: "", loader: "", category: "", projectType: "modpack" }),
    cardFn: (h) => {
      const cats = (h.categories || []).map(c => c.toLowerCase());
      const loaders = ["fabric", "forge", "quilt", "neoforge"].filter(l => cats.includes(l));
      const loaderText = loaders.length ? `لودر: ${loaders.join(", ")}` : "";
      return el("div", { class: "card mod-card" },
        el("div", { class: "mc-top" }, contentThumb(h.icon_url, "puzzle"), el("div", { class: "mc-title", text: h.title })),
        el("div", { class: "mc-desc", text: h.description || "" }),
        loaderText ? el("div", { class: "dim", style: "font-size:11px;margin-top:2px", text: loaderText }) : null,
        el("div", { class: "row spread" },
          el("span", { class: "dim dl-count" }, icon("download", 13), el("span", { text: (h.downloads || 0).toLocaleString("fa-IR") })),
          el("div", { class: "row", style: "gap:6px" },
            btn(null, "external", "btn btn-sm btn-icon", { title: "صفحه", onclick: () => T.opener.openUrl("https://modrinth.com/modpack/" + (h.slug || h.project_id)) }),
            installBtnFor("mp:" + (h.project_id || h.slug || h.title || ""), (e) => installModpack(h, e.currentTarget)))));
    },
  });
  goBtn.addEventListener("click", search.reset);
  q.addEventListener("keydown", (e) => { if (e.key === "Enter") search.reset(); });
  q.addEventListener("input", debounce(() => search.reset(), 350));
  search.reset(); // auto-load popular modpacks
}

// ── Host (server) ─────────────────────────────────────────
Pages.host = async (root) => {
  if (!accountGate(root, "ساخت سرور")) return;
  const hostGen = activeGen;            // برای توقفِ نظرسنجیِ وضعیت بعد از ترکِ تب
  { const _nb = netAdviceBanner(); if (_nb) root.appendChild(_nb); }
  root.appendChild(downloadSourceCard());
  let servers = [], listError = null;
  try { servers = await invoke("server_list"); }
  catch (e) { listError = e; }

  const createCard = el("div", { class: "card" });
  const newBtn = btn("سرور جدید", "plus", "btn btn-primary btn-sm", { onclick: showCreateServer });
  const ch = el("div", { class: "row spread" }, secTitle("ساخت سرور", "cloud"), newBtn);
  ch.querySelector(".section-title").style.margin = "0";
  createCard.appendChild(ch);
  createCard.appendChild(el("p", { class: "muted", style: "margin-top:8px",
    text: "سرور Paper، Purpur، Folia، Vanilla، Fabric یا Forge بساز و مثل یک پنل حرفه‌ای مدیریتش کن." }));
  root.appendChild(createCard);

  const listCard = el("div", { class: "card" });
  listCard.appendChild(secTitle("سرورهای من", "server"));
  // ردیفِ هر سرور را بلافاصله با وضعیتِ موقتِ «…» می‌سازیم تا تب فوری باز شود؛
  // وضعیتِ واقعیِ روشن/خاموش به‌صورتِ ناهمگام (موازی) گرفته و بعداً جایگزین می‌شود.
  // (قبلاً این حلقه برای هر سرور یک invoke("server_running") را پشتِ‌سرِهم await می‌کرد و
  //  چون wrap تا پایانِ ساخت مخفی است، کلِ تب تا تمام‌شدنِ همه‌ی این رفت‌وبرگشت‌ها هنگ می‌کرد.)
  const statusTags = [];               // [{ name, tagEl }] برای به‌روزرسانی و نظرسنجیِ بعدی
  if (listError) {
    listCard.appendChild(el("div", { class: "state-panel error-state" },
      el("div", { class: "state-icon" }, icon("warn", 30)),
      el("div", { class: "state-title", text: "فهرست سرورها باز نشد" }),
      el("div", { class: "state-copy", text: humanError(listError) }),
      btn("تلاش دوباره", "refresh", "btn btn-primary", { onclick: () => go("host") })));
  }
  else if (servers.length === 0) listCard.appendChild(el("div", { class: "state-panel" },
    el("div", { class: "state-icon" }, icon("server", 34)),
    el("div", { class: "state-title", text: "اولین سرورت را بساز" }),
    el("div", { class: "state-copy", text: "نوع و نسخه را انتخاب کن؛ دانلود و تنظیمات را خودمان انجام می‌دهیم." }),
    btn("ساخت سرور", "plus", "btn btn-primary", { onclick: showCreateServer })));
  else for (const s of servers) {
    const state = s.install_state || "ready";
    const ready = state === "ready" || state === "recovered";
    const displayName = s.display_name || s.name;
    let statusTag;
    if (state === "installing") statusTag = tag("در حال نصب", "tag blue");
    else if (state === "error" || state === "cancelled") statusTag = tag("نصب ناقص", "tag red");
    else if (state === "recovered") statusTag = tag("بازیابی‌شده", "tag amber");
    else statusTag = tag("…", "tag gray");
    if (ready) statusTags.push({ name: s.name, tagEl: statusTag });
    const primaryAction = ready
      ? btn("مدیریت", "sliders", "btn btn-sm btn-primary", { onclick: (e) => { e.stopPropagation(); openServerPanel(s); } })
      : state === "installing"
        ? btn("نمایش دانلود", "download", "btn btn-sm btn-primary", { onclick: (e) => { e.stopPropagation(); DownloadCenter.open(); } })
        : btn("ادامه دانلود", "refresh", "btn btn-sm btn-primary", { onclick: (e) => { e.stopPropagation(); retryServerInstall(s, e.currentTarget); } });
    const item = el("div", { class: "list-item srv-row" + (ready ? "" : " is-incomplete"), onclick: ready ? () => openServerPanel(s) : null },
      el("span", { class: "li-ico" }, icon("server", 18)),
      el("div", { style: "flex:1;min-width:0" }, el("div", { style: "font-weight:700", dir: "auto", text: displayName }),
        el("div", { class: "dim", text: `${s.server_type || "Server"} ${s.version || "؟"}${s.ram ? ` · ${s.ram}MB` : ""}` }),
        (!ready || state === "recovered") && s.last_error ? el("div", { class: "srv-inline-error" + (state === "recovered" ? " is-note" : ""), text: humanError(s.last_error) }) : el("span")),
      statusTag,
      primaryAction,
      btn("حذف", "trash", "btn btn-sm btn-danger", { title: "حذف سرور", "aria-label": `حذف ${displayName}`, onclick: (e) => { e.stopPropagation(); confirmDialog("حذف سرور", `«${displayName}» و همهٔ فایل‌هایش حذف شود؟`, async () => { await invoke("server_delete", { name: s.name }); toast("سرور حذف شد", "success"); go("host"); }); } }));
    listCard.appendChild(item);
  }
  root.appendChild(listCard);

  // ── وضعیتِ روشن/خاموش را ناهمگام و موازی بگیر و هر ردیف را وقتی داده‌اش رسید آپدیت کن ──
  const applyStatus = (tagEl, running) => {
    if (!tagEl.isConnected) return;
    tagEl.className = running ? "tag green" : "tag gray";
    tagEl.textContent = running ? "روشن" : "خاموش";
  };
  const refreshStatuses = async () => {
    if (pageStale(hostGen) || !statusTags.length) return;
    await Promise.all(statusTags.map(async ({ name, tagEl }) => {
      const running = await invoke("server_running", { name }).catch(() => false);
      if (pageStale(hostGen)) return;
      applyStatus(tagEl, running);
    }));
  };
  if (statusTags.length) {
    refreshStatuses();                 // اولین واکشی فوراً پس از پینتِ تب
    // وضعیت‌ها را با فاصله‌ی معقول تازه نگه دار و با ترکِ تب متوقف‌شان کن (cleanup).
    const statusPoll = setIntervalWhenVisible(() => {
      if (pageStale(hostGen)) { clearVisibleInterval(statusPoll); return; }
      refreshStatuses();
    }, 5000);
    onPageLeave(() => clearVisibleInterval(statusPoll));
  }
};

async function retryServerInstall(server, button) {
  const original = button && button.innerHTML;
  if (button) { button.disabled = true; button.innerHTML = '<span class="spinner"></span><span>در حال ادامه…</span>'; }
  try {
    DownloadCenter.update({ token: "srv-" + server.name, label: `ادامه ساخت «${server.display_name || server.name}»`, pct: 0, state: "queued", origin: "host" });
    await invoke("server_retry", { name: server.name });
    toast("سرور آماده شد و در فهرست قرار گرفت", "success");
    go("host");
  } catch (e) {
    toast(humanError(e), "error");
    go("host");
  } finally {
    if (button && button.isConnected) { button.disabled = false; button.innerHTML = original; }
  }
}

async function showCreateServer() {
  if (!State.selected) { toast("اول یک حساب ماینکرفت بساز یا انتخاب کن", "error"); openAccountManager(); return; }
  const existing = await invoke("server_list").catch(() => []);
  if (existing.length >= 2) {
    modal({
      title: "محدودیت ساخت سرور",
      body: el("div", {},
        el("div", { class: "row", style: "justify-content:center;margin-bottom:12px" }, el("span", { class: "li-ico" }, icon("warn", 40))),
        el("p", { class: "muted", style: "text-align:center", text: "هر کاربر می‌تواند حداکثر دو سرور بسازد. برای ساخت سرور جدید، اول یکی از سرورهای فعلی را حذف کن." })),
      actions: [btn("باشه", "check", "btn btn-primary", { onclick: function () { this.closest(".modal-backdrop").remove(); } })],
    });
    return;
  }
  let kinds = await invoke("server_kinds").catch(() => [
    { id: "paper", label: "Paper", desc: "" }, { id: "vanilla", label: "Vanilla", desc: "" },
  ]);
  // در حالتِ «سرورِ ایران» فقط نوع‌های سرورِ موجود روی CDN (fabric/forge/neoforge/paper)
  if (usingIran()) {
    await loadIranIndex();
    const have = new Set(Object.keys((_iranIdx && _iranIdx.servers) || {}));
    if (have.size) { const f = kinds.filter((k) => have.has(k.id)); if (f.length) kinds = f; }
  }
  const name = el("input", { class: "input", placeholder: "مثلاً دنیای دوستان", maxlength: "48", autocomplete: "off", enterkeyhint: "next", dir: "auto" });
  const version = dropdown({ options: [{ value: "", label: "در حال بارگذاری..." }], placeholder: "نسخه" });
  const ram = el("input", { class: "input", type: "number", min: "512", max: "4096", value: "1024" });
  const cpuCores = el("input", { class: "input", type: "number", min: "0", max: "128", value: "0", placeholder: "0 = خودکار" });
  const motd = el("input", { class: "input", value: "", placeholder: "MOTD" });
  // حالت آنلاین هنگام ساخت همیشه خاموش است (سرورِ باز/کرک‌فرندلی)؛ کاربر می‌تواند بعداً از
  // ویرایشگرِ server.properties آن را روشن کند. تیکِ ساختِ سرور حذف شد.

  // ── منبعِ دنیا: نسخه‌ی جدید (دنیای خالی) یا ساختِ سرور از یکی از دنیاهای موجودِ بازیکن ──
  let srcMode = "new";              // "new" | "world"
  let pickedWorld = null;          // نامِ دنیای انتخاب‌شده
  let pickedWorldObj = null;       // آبجکتِ کاملِ دنیای انتخاب‌شده (برای هشدارِ نسخه)
  const segNew = el("div", { class: "seg-btn active", text: "نسخه جدید" });
  const segWorld = el("div", { class: "seg-btn", text: "از دنیای موجود" });
  if (IS_MOBILE_UI) segWorld.style.display = "none";
  const seg = el("div", { class: "seg", style: "margin-top:4px" }, segNew, segWorld);
  const worldsBox = el("div", { style: "display:none;margin-top:8px" });
  const setSrc = (m) => {
    srcMode = m;
    segNew.classList.toggle("active", m === "new");
    segWorld.classList.toggle("active", m === "world");
    worldsBox.style.display = m === "world" ? "" : "none";
    if (m === "world" && !worldsBox._loaded) loadWorlds();
  };
  segNew.addEventListener("click", () => setSrc("new"));
  segWorld.addEventListener("click", () => setSrc("world"));
  async function loadWorlds() {
    worldsBox._loaded = true;
    worldsBox.innerHTML = "";
    worldsBox.appendChild(el("div", { class: "row", style: "justify-content:center;padding:14px" }, el("span", { class: "spinner" })));
    let ws = [];
    try { ws = await invoke("worlds_list"); } catch (_) { ws = []; }
    worldsBox.innerHTML = "";
    if (!Array.isArray(ws) || !ws.length) {
      worldsBox.appendChild(el("div", { class: "dim", style: "padding:6px 2px", text: "هیچ دنیایی پیدا نشد — اول یک دنیا در بازی بساز." }));
      pickedWorld = null;
      return;
    }
    const grid = el("div", { class: "world-pick" });
    const cards = [];
    const pick = (w, c) => { pickedWorld = w.name; pickedWorldObj = w; cards.forEach((x) => x.classList.remove("active")); c.classList.add("active"); };
    const toSrc = (window.__TAURI__.core && window.__TAURI__.core.convertFileSrc) ? window.__TAURI__.core.convertFileSrc : (p) => p;
    ws.forEach((w, i) => {
      let ico;
      if (w.icon) { ico = el("img", { class: "world-pick-ico", src: toSrc(w.icon), alt: "" }); ico.addEventListener("error", () => ico.replaceWith(el("div", { class: "world-pick-ico ph" }, icon("globe", 18)))); }
      else { ico = el("div", { class: "world-pick-ico ph" }, icon("globe", 18)); }
      // برچسبِ پروفایل (instance) را هم نشان بده تا دنیاهای هم‌نام از پروفایل‌های مختلف قابلِ تفکیک باشند
      const sub = (typeof w.size === "number" ? fmtBytes(w.size) : (w.size || "")) + (w.instance ? "  •  " + w.instance : "");
      const c = el("div", { class: "world-pick-card" }, ico,
        el("div", { style: "min-width:0;flex:1" },
          el("div", { class: "world-pick-name", text: w.name }),
          el("div", { class: "dim", style: "font-size:11px", text: sub })));
      c.addEventListener("click", () => pick(w, c));
      cards[i] = c;
      grid.appendChild(c);
    });
    // اولین دنیا را پیش‌فرض انتخاب کن
    pick(ws[0], cards[0]);
    worldsBox.appendChild(grid);
  }

  let selKind = kinds[0].id;
  const kindGrid = el("div", { class: "kind-grid" });
  const kindCards = {};
  kinds.forEach((k) => {
    const c = el("div", { class: "kind-card" + (k.id === selKind ? " active" : ""), onclick: () => {
      selKind = k.id;
      Object.values(kindCards).forEach((x) => x.classList.remove("active"));
      c.classList.add("active");
      loadVer();
    } },
      el("div", { class: "kind-top" }, icon(k.proxy ? "network" : "server", 16), el("span", { class: "kind-name", text: k.label })),
      el("div", { class: "kind-desc dim", text: k.desc || "" }));
    kindCards[k.id] = c;
    kindGrid.appendChild(c);
  });

  const snapCb = el("input", { type: "checkbox" });
  const MOD_KINDS = ["fabric", "forge", "quilt", "neoforge"];
  const moddedNote = el("div", { class: "row", style: "gap:8px;display:none;background:var(--accent-soft);border:1px solid var(--glass-brd-2);border-radius:10px;padding:9px 12px" },
    icon("info", 16),
    el("span", { class: "muted", text: "این نوعِ سرور مادیه: هر مادی که روی سرور می‌گذاری باید همون ماد روی ماینکرفتِ خودت و هر بازیکنی که می‌خواهد وصل شود هم نصب باشد، وگرنه ورود به سرور ممکن نیست." }));
  const advanced = el("details", { class: "advanced-options" },
    el("summary", {}, icon("sliders", 16), el("span", { text: "تنظیمات پیشرفته" })),
    el("div", { class: "advanced-options-body" },
      el("label", { class: "field" }, el("span", { text: "تعداد هسته CPU (۰ = خودکار)" }), cpuCores),
      el("label", { class: "field" }, el("span", { text: "پیام ورودی سرور (MOTD)" }), motd),
      el("label", { class: "row", style: "gap:8px" }, snapCb, el("span", { class: "muted", text: "نمایش نسخه‌های آزمایشی" }))));
  const body = el("div", { class: "grid", style: "gap:14px" },
    el("label", { class: "field" }, el("span", { text: "نام سرور" }), name),
    IS_MOBILE_UI
      ? el("div", { class: "field-hint" }, icon("globe", 16), el("span", { text: "یک دنیای تازه برای سرور ساخته می‌شود؛ بعداً می‌توانی دنیا را جایگزین کنی." }))
      : el("div", {}, el("span", { class: "field-lbl", text: "منبعِ دنیا" }), seg, worldsBox),
    el("div", {}, el("span", { class: "field-lbl", text: "نوع نرم‌افزار سرور" }), kindGrid),
    el("div", { class: "grid grid-2" }, el("label", { class: "field" }, el("span", { text: "نسخه" }), version), el("label", { class: "field" }, el("span", { text: "RAM (MB)" }), ram)),
    moddedNote,
    advanced,
    el("p", { class: "dim", style: "margin-top:2px", text: "پورت سرور به‌صورت خودکار از سمت رله به تو داده می‌شود. (حالت آنلاین خاموش است؛ هر کسی می‌تواند وارد شود — اگر خواستی فقط حساب‌های ثبت‌شده وارد شوند، بعد از ساخت از تنظیماتِ سرور «online-mode» را روشن کن.)" }),
    el("div", { id: "createProg", class: "dim", style: "display:none;direction:ltr;text-align:left;margin-top:2px" }));

  async function loadVer() {
    moddedNote.style.display = MOD_KINDS.includes(selKind) ? "" : "none";
    version.setOptions([{ value: "", label: "در حال بارگذاری..." }]); version.setValue("");
    try {
      let vs = await invoke("server_versions", { kind: selKind, showSnapshots: snapCb.checked });
      const allow = iranServerVersions(selKind);   // null اگر منبع ایران نباشد
      // ⚠️ قبلاً وقتی این نوع سرور اصلاً روی ایران نبود (allow.size === 0)، فیلتر رد می‌شد و کلِ
      // لیستِ زنده (که ایران ندارد) نشان داده می‌شد — دقیقاً همان چیزی که کاربر نمی‌خواست.
      if (allow) vs = vs.filter((v) => allow.has(lc(v)));
      if (!vs.length) {
        // اگر واقعاً نتوانستیم ایندکسِ ایران را بگیریم (نه اینکه این لودر خالی باشد)،
        // این را به کاربر به‌عنوانِ «عدمِ پشتیبانی» نگو — قبلاً همین اشتباه دهها گزارشِ
        // اشتباهی «نسخه پیدا نشد» ساخته بود (نگاه کن به isNetworkError در mihan-download.js).
        // دو مسیرِ کاملاً جدا این خطا را می‌سازند: پلِ نیتیوِ iran_index (_iranIdxFailed) —
        // برای فیلترِ نوعِ لودر — و versionManifest/iranList در mihan-download.js (که
        // server_versions از همان‌ها می‌آید) — برای خودِ فهرستِ نسخه‌ها؛ فورج/فبریک/وانیلا
        // از منیفستِ Mojang-mirrorِ ما رد می‌شوند، نه ایندکسِ ایران، پس این چک هم لازم است.
        const listFailed = await invoke("server_versions_list_failed").catch(() => false);
        const label = (_iranIdxFailed || listFailed)
          ? "دریافتِ فهرستِ سرورِ ایران ناموفق بود — دوباره امتحان کن"
          : (usingIran() ? "این نوع روی سرورِ ایران نسخه‌ای ندارد" : "نسخه‌ای پیدا نشد");
        version.setOptions([{ value: "", label }]);
        return;
      }
      version.setOptions(vs.map((v) => ({ value: v, label: v }))); version.setValue(vs[0]);
    }
    catch { version.setOptions([{ value: "", label: "خطا در بارگذاری (اینترنت/فیلترشکن را بررسی کن)" }]); }
  }
  snapCb.addEventListener("change", loadVer);
  loadVer();

  const dlg = modal({
    title: "ساخت سرور جدید", body,
    actions: [
      btn("ساخت سرور", "check", "btn btn-primary", { onclick: async (e) => {
        // اگر «از دنیای موجود» انتخاب شده ولی دنیایی برنگزیده، جلوگیری کن
        if (srcMode === "world" && !pickedWorld) { toast("یک دنیا انتخاب کن", "error"); return; }
        const b = e.currentTarget;
        async function proceedCreate() {
          const displayName = name.value.trim();
          if (!displayName) { toast("یک نام برای سرور وارد کن", "error"); name.focus(); return; }
          if (displayName.length > 48 || displayName === "." || displayName === ".." || /[\\/\x00-\x1f]/.test(displayName)) { toast("نام سرور معتبر نیست؛ نامی کوتاه و بدون / یا \\ انتخاب کن", "error"); name.focus(); return; }
          if (existing.some((s) => String(s.display_name || s.name).trim().toLocaleLowerCase("fa") === displayName.toLocaleLowerCase("fa"))) { toast("سروری با این نام از قبل وجود دارد", "error"); name.focus(); return; }
          const selectedVersion = version.getValue();
          if (!selectedVersion) { toast("نسخهٔ سرور را انتخاب کن", "error"); return; }
          b.disabled = true; b.innerHTML = '<span class="spinner"></span><span>در حال ثبت…</span>';
          const baseOpts = { name: displayName, version: selectedVersion, server_type: selKind, ram: clampRam(ram.value) || 1024, cpu_cores: parseInt(cpuCores.value) || 0, motd: motd.value, online_mode: false, launcher_only: false };
          let createPromise;
          try {
            if (srcMode === "world") {
              const worldOpts = Object.assign({}, baseOpts, { world: pickedWorld, saves_dir: (pickedWorldObj && pickedWorldObj.saves_dir) || "" });
              createPromise = invoke("create_server_from_world", { opts: worldOpts });
            } else {
              createPromise = invoke("server_create", { opts: baseOpts });
            }
            // متادیتا پیش از اولین درخواست شبکه ثبت می‌شود؛ بنابراین کاربر فوراً به فهرست
            // برمی‌گردد و سرور را با وضعیت زنده‌ی «در حال نصب» می‌بیند.
            dlg.close();
            toast("سرور ثبت شد؛ دانلود در پس‌زمینه ادامه دارد", "info");
            go("host");
            const srv = await createPromise;
            const ready = await invoke("server_ready", { name: (srv && srv.name) || displayName }).catch(() => false);
            if (!ready) {
              toast("نصب کامل نشد؛ از همین فهرست «ادامه دانلود» را بزن", "error");
              if (activePage === "host") go("host");
              return;
            }
            toast(`«${displayName}» آمادهٔ مدیریت است`, "success");
            if (activePage === "host") go("host");
          } catch (err) {
            toast(humanError(err), "error");
            if (dlg && dlg.close && document.body.contains(b)) { b.disabled = false; b.innerHTML = ""; b.appendChild(icon("check", 16)); b.appendChild(el("span", { text: "ساخت سرور" })); }
            if (activePage === "host") go("host");
          }
        }
        // هشدار: اگر نسخه‌ی سرور از نسخه‌ی دنیا قدیمی‌تر باشد، باز شدنِ دنیا ممکن است آن را خراب کند
        const srvVer = version.getValue();
        const worldVer = (pickedWorldObj && pickedWorldObj.version) || "";
        if (srcMode === "world" && worldVer && cmpVer(srvVer, worldVer) < 0) {
          confirmDialog("هشدار: نسخه‌ی قدیمی‌تر",
            `این دنیا با نسخه‌ی ${worldVer} ساخته شده، اما داری سرور را روی ${srvVer} (قدیمی‌تر) می‌سازی. باز کردنِ یک دنیا با نسخه‌ی قدیمی‌ترِ ماینکرفت می‌تواند آن را خراب کند. ادامه می‌دهی؟`,
            () => proceedCreate());
          return;
        }
        proceedCreate();
      } }),
      btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
    ],
  });
}

// ═══════════════════════════════════════════════════════════
//  Reusable sandboxed file browser (servers AND profiles).
//  `fsArgs` picks the backend root: { name } for a server folder,
//  { instance } for a profile/instance game dir. Renders into
//  `container`; arms OS drag-drop while the file list is showing.
// ═══════════════════════════════════════════════════════════
function renderFileManager(container, fsArgs) {
  let filesPath = "";
  const crumbLink = (label, target, cur) => el("span", { class: "crumb" + (target === cur ? " active" : ""), onclick: () => renderFiles(target) }, el("span", { text: label }));

  async function renderFiles(path) {
    filesPath = path;
    // (re)arm OS drag-drop for the current folder each time the list renders
    fileDropHandler = async (paths) => {
      if (!Array.isArray(paths) || paths.length === 0) return;
      toast("در حال آپلود " + paths.length + " فایل...");
      let ok = 0;
      for (const src of paths) { try { await invoke("fs_upload", { ...fsArgs, dest: filesPath, src }); ok++; } catch (e) { toast("خطا در آپلود: " + e, "error"); } }
      if (ok) toast(`${ok} فایل آپلود شد`, "success");
      renderFiles(filesPath);
    };
    container.innerHTML = "";
    const card = el("div", { class: "card files-card" });
    const crumbs = el("div", { class: "crumbs" }, crumbLink("ریشه", "", path));
    let acc = "";
    path.split("/").filter(Boolean).forEach((p) => { acc = acc ? acc + "/" + p : p; crumbs.appendChild(el("span", { class: "crumb-sep" }, icon("chevronLeft", 13))); crumbs.appendChild(crumbLink(p, acc, path)); });
    card.appendChild(el("div", { class: "files-toolbar" }, crumbs,
      el("div", { class: "row", style: "gap:8px" },
        // «باز کردن پوشه در ویندوز» این‌جا حذف شد: روی گوشی نه ویندوزی هست نه
        // فایل‌منیجرِ سیستمی‌ای که open_in_explorer بتواند باز کند — همیشه خطا می‌داد،
        // آن هم درست وسطِ فایل‌منیجرِ خودِ لانچر که همین کار را می‌کند.
        btn(null, "refresh", "btn btn-sm btn-icon", { title: "بروزرسانی", onclick: () => renderFiles(filesPath) }),
        btn("آپلود", "upload", "btn btn-sm", { onclick: uploadFiles }),
        btn("فایل جدید", "filePlus", "btn btn-sm", { onclick: () => promptInput("فایل جدید", "نام فایل (مثلاً config.yml)", async (v) => { const rel = filesPath ? filesPath + "/" + v : v; await invoke("fs_new_file", { ...fsArgs, path: rel }); renderFiles(filesPath); openEditor(rel); }) }),
        btn("پوشه جدید", "folderPlus", "btn btn-sm", { onclick: () => promptInput("پوشه جدید", "نام پوشه", async (v) => { const rel = filesPath ? filesPath + "/" + v : v; await invoke("fs_mkdir", { ...fsArgs, path: rel }); renderFiles(filesPath); }) }))));

    const searchInput = el("input", { class: "input file-search-input", placeholder: "جستجوی متن داخل فایل‌ها...", autocomplete: "off", spellcheck: "false" });
    const searchClear = btn(null, "x", "btn btn-sm btn-icon", { title: "پاک کردن", style: "display:none" });
    card.appendChild(el("div", { class: "file-search" }, el("span", { class: "file-search-ico" }, icon("search", 16)), searchInput, searchClear));
    const resultsBox = el("div", { class: "files-list fsearch-results", style: "display:none" });
    card.appendChild(resultsBox);
    const listBox = el("div", { class: "files-list" });
    card.appendChild(listBox);
    container.appendChild(card);

    async function runSearch(q) {
      q = q.trim();
      searchClear.style.display = q ? "" : "none";
      if (!q) { resultsBox.style.display = "none"; resultsBox.innerHTML = ""; listBox.style.display = ""; return; }
      listBox.style.display = "none"; resultsBox.style.display = "";
      resultsBox.innerHTML = '<div class="row" style="justify-content:center;padding:18px"><span class="spinner"></span></div>';
      let res;
      try { res = await invoke("fs_search", { ...fsArgs, query: q }); }
      catch (e) { resultsBox.innerHTML = ""; resultsBox.appendChild(el("div", { class: "dim", style: "padding:14px", text: "خطا: " + e })); return; }
      if (searchInput.value.trim() !== q) return;
      resultsBox.innerHTML = "";
      const matches = res.matches || [];
      if (matches.length === 0) { resultsBox.appendChild(el("div", { class: "dim", style: "padding:18px;text-align:center", text: "هیچ فایلی شامل این متن نیست." })); return; }
      resultsBox.appendChild(el("div", { class: "dim", style: "padding:8px 12px 4px", text: `${matches.length} نتیجه` + (res.truncated ? " (محدودشده — کلمه را دقیق‌تر کن)" : "") }));
      matches.forEach((m) => resultsBox.appendChild(el("div", { class: "fsearch-row", title: "باز کردن در ویرایشگر", onclick: () => openEditor(m.path) },
        el("span", { class: "file-ico" }, icon(fileEntryIcon({ ext: (m.path.split(".").pop() || "").toLowerCase() }), 16)),
        el("div", { style: "min-width:0;flex:1" },
          el("div", { class: "fsearch-path" }, el("span", { text: m.path }), el("span", { class: "fsearch-line", text: " : " + m.line })),
          el("div", { class: "fsearch-snippet" }, ...highlightNodes(m.text, q))))));
    }
    const liveSearch = debounce(() => runSearch(searchInput.value), 300);
    searchInput.addEventListener("input", liveSearch);
    searchInput.addEventListener("keydown", (e) => { if (e.key === "Enter") runSearch(searchInput.value); });
    searchClear.addEventListener("click", () => { searchInput.value = ""; runSearch(""); searchInput.focus(); });

    listBox.appendChild(el("div", { class: "row", style: "justify-content:center;padding:24px" }, el("span", { class: "spinner" })));
    let data;
    try { data = await invoke("fs_list", { ...fsArgs, path }); }
    catch (e) { listBox.innerHTML = ""; listBox.appendChild(el("div", { class: "dim", style: "padding:16px", text: "خطا: " + e })); return; }
    listBox.innerHTML = "";
    if (path) listBox.appendChild(el("div", { class: "file-row up", onclick: () => renderFiles(parentOf(path)) }, el("span", { class: "file-ico dir" }, icon("folderOpen", 17)), el("span", { class: "file-name", text: ".." })));
    if (data.entries.length === 0 && !path) listBox.appendChild(el("div", { class: "dim", style: "padding:18px;text-align:center", text: "این پوشه خالی است." }));
    data.entries.forEach((en) => {
      const rel = path ? path + "/" + en.name : en.name;
      const ico = el("span", { class: "file-ico" + (en.is_dir ? " dir" : "") }, icon(fileEntryIcon(en), 17));
      const nameCell = el("span", { class: "file-name", text: en.name });
      const acts = el("span", { class: "file-acts" });
      const meta = el("span", { class: "file-meta dim" }, el("span", { class: "f-date", text: fmtDateShort(en.modified) }));
      if (!en.is_dir) meta.appendChild(el("span", { class: "f-size", text: fmtBytes(en.size) }));
      const row = el("div", { class: "file-row" }, ico, nameCell, meta, acts);
      if (en.is_dir) { row.classList.add("is-dir"); row.onclick = () => renderFiles(rel); }
      else {
        row.style.cursor = "pointer"; row.onclick = () => openEditor(rel);
        acts.appendChild(btn(null, "pencil", "btn btn-sm btn-icon", { title: "ویرایش", onclick: (e) => { e.stopPropagation(); openEditor(rel); } }));
        acts.appendChild(btn(null, "download", "btn btn-sm btn-icon", { title: "دانلود", onclick: (e) => { e.stopPropagation(); downloadFile(rel, en.name); } }));
        if (["zip", "jar"].includes(en.ext)) acts.appendChild(btn(null, "archive", "btn btn-sm btn-icon", { title: "استخراج", onclick: (e) => { e.stopPropagation(); extractFile(rel); } }));
      }
      acts.appendChild(btn(null, "boxes", "btn btn-sm btn-icon", { title: "فشرده‌سازی (zip)", onclick: (e) => { e.stopPropagation(); compressItem(rel, en.name); } }));
      acts.appendChild(btn(null, "copy", "btn btn-sm btn-icon", { title: "تغییر نام", onclick: (e) => { e.stopPropagation(); promptInput("تغییر نام", "نام جدید", async (v) => { const np = parentOf(rel) ? parentOf(rel) + "/" + v : v; await invoke("fs_rename", { ...fsArgs, path: rel, newPath: np }); renderFiles(filesPath); }, en.name); } }));
      acts.appendChild(btn(null, "trash", "btn btn-sm btn-icon danger", { title: "حذف", onclick: (e) => { e.stopPropagation(); confirmDialog("حذف", `«${en.name}» حذف شود؟`, async () => { await invoke("fs_delete", { ...fsArgs, path: rel }); renderFiles(filesPath); }); } }));
      listBox.appendChild(row);
    });
  }

  async function uploadFiles() {
    const sel = await T.dialog.open({ multiple: true }).catch(() => null);
    if (!sel) return;
    const arr = Array.isArray(sel) ? sel : [sel];
    let ok = 0;
    for (const src of arr) { try { await invoke("fs_upload", { ...fsArgs, dest: filesPath, src }); ok++; } catch (e) { toast("خطا در آپلود: " + e, "error"); } }
    if (ok) toast(`${ok} فایل آپلود شد`, "success"); renderFiles(filesPath);
  }
  async function downloadFile(rel, fname) {
    const dest = await T.dialog.save({ defaultPath: fname }).catch(() => null);
    if (!dest) return;
    try { await invoke("fs_download", { ...fsArgs, path: rel, dest }); toast("ذخیره شد", "success"); } catch (e) { toast("خطا: " + e, "error"); }
  }
  async function extractFile(rel) {
    const base = rel.replace(/\.[^.]+$/, "");
    try { await invoke("fs_extract", { ...fsArgs, path: rel, dest: base }); toast("استخراج شد", "success"); renderFiles(filesPath); } catch (e) { toast("خطا: " + e, "error"); }
  }
  async function compressItem(rel, name) {
    const dest = filesPath ? filesPath + "/" + name + ".zip" : name + ".zip";
    toast("در حال فشرده‌سازی...");
    try { await invoke("fs_compress", { ...fsArgs, paths: [rel], dest }); toast("zip ساخته شد", "success"); renderFiles(filesPath); } catch (e) { toast("خطا: " + e, "error"); }
  }

  async function openEditor(rel) {
    container.innerHTML = "";
    const card = el("div", { class: "card editor-card" });
    const fname = rel.split("/").pop();
    const statusEl = el("span", { class: "editor-status dim" });
    const findBtn = btn("جستجو", "search", "btn btn-sm", { title: "جستجو در متن (Ctrl+F)" });
    const saveBtn = btn("ذخیره", "save", "btn btn-sm btn-primary");
    let doFind = () => {};
    findBtn.addEventListener("click", () => doFind());
    card.appendChild(el("div", { class: "editor-head" },
      el("div", { class: "row", style: "gap:8px;flex:1;min-width:0" }, icon("fileCode", 16), el("span", { class: "editor-name", text: rel })),
      el("div", { class: "row", style: "gap:8px" }, statusEl, findBtn, saveBtn,
        btn("بستن", "x", "btn btn-sm btn-ghost", { onclick: () => renderFiles(filesPath) }))));
    const host = el("div", { class: "editor-host" });
    card.appendChild(host);
    container.appendChild(card);
    let text = "";
    try { text = await invoke("fs_read", { ...fsArgs, path: rel }); }
    catch (e) { host.appendChild(el("div", { class: "empty" }, el("div", { class: "big" }, icon("warn", 36)), el("div", { text: String(e) }))); saveBtn.disabled = true; return; }
    let getValue;
    await ensureCodeMirror().catch(() => {});
    if (window.CodeMirror) {
      const cm = window.CodeMirror(host, { value: text, mode: cmModeFor(fname), theme: "mc-editor", lineNumbers: true, lineWrapping: true, autoCloseBrackets: true, matchBrackets: true, styleActiveLine: false, indentUnit: 2, tabSize: 2, direction: "ltr", extraKeys: { "Ctrl-S": () => doSave(), "Ctrl-F": "findPersistent", "Ctrl-H": "replace", "Ctrl-G": "jumpToLine" } });
      setTimeout(() => cm.refresh(), 30);
      cm.on("change", () => { statusEl.textContent = "ذخیره‌نشده"; });
      getValue = () => cm.getValue();
      doFind = () => { cm.focus(); cm.execCommand("findPersistent"); };
    } else {
      const ta = el("textarea", { class: "editor-fallback", spellcheck: "false" }); ta.value = text;
      ta.addEventListener("input", () => { statusEl.textContent = "ذخیره‌نشده"; });
      host.appendChild(ta);
      getValue = () => ta.value;
      doFind = () => { const q = prompt("جستجو در متن:"); if (!q) return; const i = ta.value.toLowerCase().indexOf(q.toLowerCase()); if (i >= 0) { ta.focus(); ta.setSelectionRange(i, i + q.length); } else toast("پیدا نشد", "error"); };
    }
    async function doSave() { saveBtn.disabled = true; try { await invoke("fs_write", { ...fsArgs, path: rel, content: getValue() }); statusEl.textContent = "ذخیره شد"; toast("ذخیره شد", "success"); } catch (e) { toast("خطا: " + e, "error"); } saveBtn.disabled = false; }
    saveBtn.addEventListener("click", doSave);
  }

  renderFiles("");
}

