let panelCleanup = null;
let fileDropHandler = null;
let migrateUnsub = null;
let migrateCache = null;
function disposeServerPanel() { fileDropHandler = null; if (panelCleanup) { try { panelCleanup(); } catch (_) {} panelCleanup = null; } }

const parentOf = (p) => { const i = p.lastIndexOf("/"); return i < 0 ? "" : p.slice(0, i); };
function fmtUptime(sec) {
  sec = +sec || 0;
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
  if (h) return `${h}س ${m}د`;
  if (m) return `${m}د ${s}ث`;
  return `${s}ث`;
}
function fmtRate(bps) {
  bps = +bps || 0;
  if (bps < 1024) return `${bps} B/s`;
  if (bps < 1024 * 1024) return `${(bps / 1024).toFixed(0)} KB/s`;
  return `${(bps / 1024 / 1024).toFixed(1)} MB/s`;
}
function fmtPlay(min) {
  min = +min || 0;
  const h = Math.floor(min / 60), m = min % 60;
  if (h) return `${h} ساعت ${m} دقیقه`;
  return `${m} دقیقه`;
}
// Persian (Jalali) date+time — fa-IR uses the Persian calendar by default.
const _faShort = (() => { try { return new Intl.DateTimeFormat("fa-IR", { year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" }); } catch (_) { return null; } })();
function fmtDateShort(ts) {
  if (!ts) return "";
  const d = new Date(ts * 1000);
  try { return _faShort ? _faShort.format(d) : d.toLocaleString("fa-IR"); }
  catch (_) { return d.toLocaleString("fa-IR"); }
}
function fileEntryIcon(en) {
  if (en.is_dir) return "folder";
  const e = en.ext || "";
  if (["json", "mcmeta", "yml", "yaml", "toml", "properties", "cfg", "conf", "xml", "sh", "bat", "cmd", "js"].includes(e)) return "fileCode";
  if (["txt", "log", "md", "csv"].includes(e)) return "fileText";
  if (["zip", "jar", "gz", "tar", "rar"].includes(e)) return "archive";
  return "file";
}
function cmModeFor(name) {
  const n = name.toLowerCase();
  if (n.endsWith(".json") || n.endsWith(".mcmeta")) return { name: "javascript", json: true };
  if (n.endsWith(".js")) return "javascript";
  if (n.endsWith(".yml") || n.endsWith(".yaml")) return "yaml";
  if (n.endsWith(".xml")) return "xml";
  if (n.endsWith(".toml")) return "toml";
  if (n.endsWith(".sh") || n.endsWith(".bat") || n.endsWith(".cmd")) return "shell";
  if (n.endsWith(".properties") || n === "eula.txt" || n.endsWith(".cfg") || n.endsWith(".conf")) return "properties";
  return null;
}
function promptInput(title, placeholder, onOk, initial = "") {
  const input = el("input", { class: "input", placeholder, value: initial });
  const dlg = modal({
    title, body: el("label", { class: "field" }, el("span", { text: placeholder }), input),
    actions: [
      btn("تأیید", "check", "btn btn-primary", { onclick: async () => { const v = input.value.trim(); if (!v) return; dlg.close(); try { await onOk(v); } catch (e) { toast("خطا: " + e, "error"); } } }),
      btn("انصراف", null, "btn btn-ghost", { onclick: () => dlg.close() }),
    ],
  });
  input.focus();
}

