    const pixelHeight = Math.max(1, Math.round(height * dpr));
    if (layer.canvas.width !== pixelWidth) layer.canvas.width = pixelWidth;
    if (layer.canvas.height !== pixelHeight) layer.canvas.height = pixelHeight;
    layer.width = width;
    layer.height = height;
