      const alpha = (front ? [.36, .58, .86] : [.2, .34, .52])[depth];
      ctx.fillStyle = `rgba(${color[0]},${color[1]},${color[2]},${alpha})`;
      ctx.beginPath();
      particles.forEach((particle) => {
        if (dt > 0) {
          particle.x -= particle.speed * dt;
          particle.y += particle.lift * dt;
          particle.rotation += particle.spin * dt;
          if (particle.x < -.1) {
            particle.x += 1.22;
            particle.y = ((particle.y + .37 + noise(Math.floor(time) + groupIndex, 2)) % 1.12) - .06;
          }
          if (particle.y < -.1) particle.y += 1.2;
          else if (particle.y > 1.1) particle.y -= 1.2;
        }
        const flutter = Math.sin(time * .001 * particle.waveSpeed + particle.phase);
        const x = (particle.x + flutter * particle.wave * .32) * width;
        const y = (particle.y + flutter * particle.wave) * height;
        const size = particle.size * (.78 + depth * .2);
        const halfWidth = size;
        const halfHeight = size * (.42 + .08 * Math.sin(particle.phase));
        const cos = Math.cos(particle.rotation);
        const sin = Math.sin(particle.rotation);
        const px = cos * halfWidth;
        const py = sin * halfWidth;
        const qx = -sin * halfHeight;
        const qy = cos * halfHeight;
        ctx.moveTo(x + px, y + py);
        ctx.lineTo(x + qx, y + qy);
        ctx.lineTo(x - px, y - py);
        ctx.lineTo(x - qx, y - qy);
        ctx.closePath();
      });
